def _build_generated_invest_projects():
    projects=[]
    for si,(sector,traction_unit,risk_driver) in enumerate(_INVEST_SECTORS):
        for ai,(slug,product,model,problem,plan,use,risk,event1,event2,event3,event4) in enumerate(_INVEST_ARCHETYPES[:14]):
            idx=si*len(_INVEST_ARCHETYPES)+ai
            ask=180000 + ((idx*137911 + si*90117) % 2200000)
            valuation=ask*(5 + (idx%7)) + 350000
            revenue=80000 + ((idx*43817 + 125000) % 1150000)
            burn=max(50000,int(revenue*(0.42 + (idx%5)*0.13)))
            runway=max(1,min(14,round((ask*2)/max(1,burn))))
            margin=max(7,min(78,12+((idx*11+si*7)%65)))
            count=180+((idx*97)%9400)
            founder_names=['Артём Волков','Полина Захарова','Денис Миронов','Алина Соколова','Илья Козлов','Вера Смирнова','Максим Белов','Дарья Фомина','Егор Павлов','София Крылова','Никита Орлов','Мария Лебедева','Тимур Егоров','Елена Власова','Кирилл Новиков']
            name=f'{slug} {sector.split()[0]} {si+1:02d}'
            risk_level='high' if idx%5==0 or runway<=3 else ('low' if idx%4==0 and runway>=7 else 'medium')
            projects.append({
                'id':f'gen_{si+1:02d}_{ai+1:02d}','name':name,'sector':sector,'founder':founder_names[(idx+si)%len(founder_names)],
                'ask':ask,'valuation':valuation,'traction':f'{count:,}'.replace(',',' ')+' '+traction_unit,
                'revenue':revenue,'burn':burn,'runway':runway,'margin':margin,'model':f'{product}: {model}',
                'problem':f'{problem} Сегмент проекта — {sector.lower()}; ключевая сложность — {risk_driver}.',
                'plan':f'{plan} Для направления «{sector}» первый этап ограничен одним регионом и проверяемой партией.',
                'use':use,'risk':f'{risk} Дополнительный отраслевой риск: {risk_driver}.','risk_level':risk_level,'duration':0,
                'story_arc':[
                    {'headline':'Первые сигналы рынка','body':event1,'impact':0.06 if idx%3 else 0.02,'stage':'Проверка спроса'},
                    {'headline':'Поворот в переговорах','body':event2,'impact':-0.08 if idx%4==0 else 0.045,'stage':'Первые продажи'},
                    {'headline':'Давление на экономику','body':event3,'impact':-0.16 if risk_level=='high' else -0.055,'stage':'Испытание модели'},
                    {'headline':'Новый раунд событий','body':event4,'impact':0.22 if idx%3 else -0.12,'stage':'Масштабирование'},
                ],
            })
    return projects

INVEST_PROJECT_POOL.extend(_build_generated_invest_projects())


