def _make_resell_launch_token(tg_id: int, ttl: int = 30 * 24 * 60 * 60) -> str:
    uid = str(int(tg_id))
    exp = int(time_module.time()) + int(ttl)
    payload = f"{uid}:{exp}"
    secret = str(API_TOKEN or BOT_TOKEN or "").encode("utf-8")
    sig = hmac.new(secret, payload.encode("utf-8"), hashlib.sha256).hexdigest()
    return f"{uid}.{exp}.{sig}"


def _resell_launch_url(tg_id: int, ref: str = "") -> str:
    token = _make_resell_launch_token(int(tg_id))
    url = f"{URL_RESELL}&resell_session={token}" if "?" in URL_RESELL else f"{URL_RESELL}?resell_session={token}"
    if ref:
        url += f"&ref={quote(str(ref), safe='')}"
    return url
