# V53: per-car tuning. Each component has 5 levels; every level adds speed,
# and the resulting speed directly increases that individual car's income.
CAR_TUNING_CONFIG = {
    "engine": {"title": "Двигатель", "description": "Мощность и отклик", "speed": 2, "max": 5, "costs": [25_000, 50_000, 100_000, 180_000, 300_000]},
    "transmission": {"title": "Трансмиссия", "description": "Передача мощности на колёса", "speed": 2, "max": 5, "costs": [20_000, 40_000, 80_000, 150_000, 250_000]},
    "turbo": {"title": "Турбина", "description": "Ускорение и тяга", "speed": 2, "max": 5, "costs": [35_000, 70_000, 140_000, 260_000, 450_000]},
    "suspension": {"title": "Подвеска", "description": "Стабильность на скорости", "speed": 2, "max": 5, "costs": [18_000, 36_000, 72_000, 130_000, 220_000]},
    "aerodynamics": {"title": "Аэродинамика", "description": "Снижение сопротивления", "speed": 2, "max": 5, "costs": [22_000, 45_000, 90_000, 165_000, 280_000]},
}

def _safe_car_tuning(raw=None):
    raw = raw if isinstance(raw, dict) else {}
    out = {}
    for key, cfg in CAR_TUNING_CONFIG.items():
        try:
            out[key] = max(0, min(int(cfg["max"]), int(raw.get(key, 0) or 0)))
        except (TypeError, ValueError):
            out[key] = 0
    return out

def _car_tuning_speed(tuning=None):
    u = _safe_car_tuning(tuning)
    return sum(int(CAR_TUNING_CONFIG[k]["speed"]) * int(u[k]) for k in CAR_TUNING_CONFIG)

def _car_speed(car, tuning=None):
    return max(0, int(car.get("speed_bonus", 0) or 0) + _car_tuning_speed(tuning))

def _car_income_per_hour(car, tuning=None):
    base = max(0, int(car.get("income_per_hour", 0) or 0))
    # Every +1 speed point adds +1% to this specific car's income.
    return max(0, int(round(base * (1.0 + _car_tuning_speed(tuning) / 100.0))))


def _load_authoritative_car_tuning(conn, player_id, collection, stats):
    """Merge persistent tuning into the per-car stats without losing legacy data.

    car_tuning_state is the source of truth; garage_car_stats remains a mirrored
    cache for compatibility with the existing taxi/economy code.
    """
    collection=list(collection or [])
    stats=list(stats or [])
    while len(stats)<len(collection):
        stats.append({})
    rows=conn.execute(
        "SELECT instance_index,car_id,tuning FROM car_tuning_state WHERE player_id=?",
        (int(player_id),)
    ).fetchall()
    by_idx={int(r["instance_index"]):r for r in rows}
    now=int(time_module.time())
    for idx,car_id in enumerate(collection):
        st=stats[idx] if isinstance(stats[idx],dict) else {}
        row=by_idx.get(idx)
        if row is not None and str(row["car_id"] or "") == str(car_id or ""):
            try: raw=json.loads(row["tuning"] or "{}")
            except Exception: raw={}
            tuning=_safe_car_tuning(raw)
        else:
            tuning=_safe_car_tuning(st.get("tuning"))
            conn.execute(
                "INSERT INTO car_tuning_state(player_id,instance_index,car_id,tuning,updated_at) VALUES(?,?,?,?,?) "
                "ON CONFLICT(player_id,instance_index) DO UPDATE SET car_id=excluded.car_id,tuning=excluded.tuning,updated_at=excluded.updated_at",
                (int(player_id),idx,str(car_id or ""),json.dumps(tuning,ensure_ascii=False),now)
            )
        st["tuning"]=tuning
        stats[idx]=st
    conn.execute("DELETE FROM car_tuning_state WHERE player_id=? AND instance_index>=?",(int(player_id),len(collection)))
    return stats

