# REAL ESTATE V2 — интерактивная модель недвижимости.
# Старые владельцы сохраняют историческую стоимость для wealth/leaderboard;
# новые покупки фиксируются по актуальной цене каталога.
PROPERTY_LEGACY_PURCHASE_PRICES = {
    "room": 0, "flat": 30_000, "house": 105_000, "villa": 300_000,
    "yacht": 750_000, "skyscraper": 9_000_000,
}
PROPERTY_SPECIALIZATIONS = {
    "balanced": {"name":"Сбалансировано", "income":1.00, "rep":1.00},
    "premium": {"name":"Премиум", "income":1.12, "rep":1.20},
    "income": {"name":"Доход", "income":1.20, "rep":0.90},
    "prestige": {"name":"Статус", "income":0.92, "rep":1.35},
    "office": {"name":"Офисный центр", "income":1.22, "rep":1.08},
    "hotel": {"name":"Премиум-отель", "income":1.10, "rep":1.30},
    "retail": {"name":"Торговая галерея", "income":1.28, "rep":1.05},
    "hq": {"name":"Штаб RESSELL", "income":0.98, "rep":1.55},
}

def _property_state(player, house=None):
    house = house or next((h for h in HOUSES if str(h["id"])==str(player.get("house","room"))), HOUSES[0])
    hid=str(house["id"])
    purchase=int(player.get("property_purchase_value") or 0)
    if purchase <= 0 and hid in PROPERTY_LEGACY_PURCHASE_PRICES and hid != "room":
        purchase=PROPERTY_LEGACY_PURCHASE_PRICES[hid]
    condition=max(0,min(100,int(player.get("property_condition") or 100)))
    reputation=max(0,min(100,int(player.get("property_reputation") or 0)))
    spec=str(player.get("property_specialization") or "balanced")
    if spec not in PROPERTY_SPECIALIZATIONS: spec="balanced"
    return {"purchase_value":purchase,"condition":condition,"reputation":reputation,"specialization":spec,
            "specialization_name":PROPERTY_SPECIALIZATIONS[spec]["name"],
            "last_action":int(player.get("property_last_action") or 0),
            "action_streak":int(player.get("property_action_streak") or 0)}

def _property_hourly_income(player, house=None):
    house=house or next((h for h in HOUSES if str(h["id"])==str(player.get("house","room"))),HOUSES[0])
    base=int(house.get("income_per_hour",0) or 0)
    if base<=0: return 0
    st=_property_state(player,house); cfg=PROPERTY_SPECIALIZATIONS[st["specialization"]]
    condition_factor=0.70 + st["condition"]*0.0035
    rep_factor=1.0 + st["reputation"]*0.002
    return max(0,int(round(base*condition_factor*rep_factor*cfg["income"])))

