for ti,(topic,g,q2,q3,q4,answers) in enumerate(_DIALOGUE_TOPICS):
    for vi,(style,p1,p2,p3) in enumerate(_DIALOGUE_STYLES):
        styled=[]
        for qi,row in enumerate(answers):
            # Keep every answer tied directly to the current question.
            styled.append([str(row[ci]) for ci in range(3)])
        CLIENT_DIALOGUES.append({"id":f"dlg_{ti+1:02d}_{vi+1}","title":f"{topic} · {style}","client_type":["normal","skeptic","normal","trader","skeptic"][vi],"phases":[g,q2,q3,q4,p1,p2,p3],"answer_sets":styled,"final_prompt":"Хорошо, с информацией разобрался. Теперь давай окончательно по цене.","final_agree":"Отлично, договорились. Я забираю товар по {price}₽.","final_decline":"Нет, при такой цене не готов. Спасибо за ответы, но пропущу."})

assert len(CLIENT_DIALOGUES)==60

def select_dialogue_scenario(item_obj: dict, client_type: str):
    """Select dialogue by the actual product family. Never give a jacket a phone/IMEI chat.
    Each family has its own logical questions, while buyer personality still changes the tone.
    """
    item_obj = item_obj if isinstance(item_obj, dict) else {}
    text = " ".join(str(item_obj.get(k, "")) for k in ("name","cat","category","type","found_type","hunt_type")).lower()
    phone = any(k in text for k in ("iphone","айфон","samsung","самсунг","xiaomi","сяоми","redmi","pixel","телефон","смартфон","phone"))
    clothing = any(k in text for k in ("куртк","пальто","футболк","худи","свитшот","джинс","брюк","одежд","плать","рубаш","толстов","ma-1","nuptse"))
    footwear = any(k in text for k in ("обув","кроссов","кросс","ботин","кед","sneaker"))
    accessory = any(k in text for k in ("аксессуар","сумк","рюкзак","ремень","очки","часы","wallet","кошел"))
    computer = any(k in text for k in ("macbook","ноутбук","laptop","компьютер","pc","планшет","ipad","monitor","монитор","камера","фотоаппарат"))
    rare = any(k in text for k in ("редкий","эпический","легендарный","коллекцион","vintage","винтаж"))
    if phone:
        topic_ids = {"01"}
    elif clothing or footwear:
        topic_ids = {"02","03"}
    elif computer:
        topic_ids = {"02","07","09"}
    elif accessory:
        topic_ids = {"02","09","11"}
    elif rare:
        topic_ids = {"10","12","02"}
    else:
        topic_ids = {"02","04","06","07","08","09","11"}
    preferred = [d for d in CLIENT_DIALOGUES if any(d.get("id","").startswith(f"dlg_{tid}_") for tid in topic_ids) and d.get("client_type")==client_type]
    if not preferred:
        preferred = [d for d in CLIENT_DIALOGUES if any(d.get("id","").startswith(f"dlg_{tid}_") for tid in topic_ids)]
    return random.choice(preferred or CLIENT_DIALOGUES)

