def _json_obj(value, default):
    if isinstance(value, (dict,list)): return value
    try: return json.loads(value) if value else default
    except Exception: return default

def _avito_asset_wealth_sync(player_id:int, player_data:dict|None=None) -> int:
    """Server-side approximate net worth used only for Avito item discovery.
    It intentionally reads real owned assets; no client value is trusted.
    """
    conn=get_db()
    try:
        row=conn.execute("SELECT * FROM players WHERE id=?",(int(player_id),)).fetchone()
        if not row: return 0
        p=dict(row)
        balance=max(0,int(p.get("balance",0) or 0))
        wealth=balance
        inv=_json_obj(p.get("inventory"),[])
        if isinstance(inv,list): wealth+=sum(max(0,int((x or {}).get("market_price",(x or {}).get("value",0)) or 0)) for x in inv if isinstance(x,dict))
        cars=_json_obj(p.get("car_collection"),[])
        car_prices={str(x.get("id")):int(x.get("price",0) or 0) for x in CARS}
        if isinstance(cars,list):
            for c in cars:
                cid=str(c.get("id")) if isinstance(c,dict) else str(c)
                wealth+=car_prices.get(cid,0)
        house=_json_obj(p.get("house"),{})
        if isinstance(house,dict):
            wealth+=int(_property_state(p, next((x for x in HOUSES if str(x.get("id"))==str(house.get("id"))), HOUSES[0]))["purchase_value"])
        elif house:
            wealth+=int(p.get("property_purchase_value") or PROPERTY_LEGACY_PURCHASE_PRICES.get(str(house),0))
        shop_catalog={str(x.get("id")):int(x.get("price",0) or 0) for x in SHOP_LEVELS}
        for r in conn.execute("SELECT shop_id,purchase_price FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active'",(int(player_id),)).fetchall():
            wealth+=max(int(r[1] or 0),shop_catalog.get(str(r[0]),0))
        taxi_catalog={str(x.get("id")):int(x.get("price",0) or 0) for x in TAXOPARK_LEVELS}
        for r in conn.execute("SELECT level_id,purchase_price FROM user_taxoparks WHERE player_id=? AND status='active'",(int(player_id),)).fetchall():
            wealth+=max(int(r[1] or 0),taxi_catalog.get(str(r[0]),0))
        for r in conn.execute("SELECT price FROM mining_rigs WHERE player_id=? AND status='active'",(int(player_id),)).fetchall(): wealth+=int(r[0] or 0)
        stock_prices={str(r[0]):int(r[1] or 0) for r in conn.execute("SELECT symbol,price FROM stock_prices").fetchall()}
        for r in conn.execute("SELECT symbol,quantity,avg_buy_price FROM user_stocks WHERE player_id=? AND quantity>0",(int(player_id),)).fetchall():
            wealth+=max(0,int(r[1] or 0))*stock_prices.get(str(r[0]),max(0,int(r[2] or 0)))
        market_catalog={str(x.get("id")):int(x.get("price",0) or 0) for x in (RESSELL_EMPIRE_CATALOG+RESSELL_COLLECTIBLE_CATALOG+RESSELL_BLACK_MARKET_POOL+RESSELL_COLLECTOR_CARS+RESSELL_DROP_CATALOG)}
        for r in conn.execute("SELECT asset_id FROM resell_market_assets WHERE player_id=?",(int(player_id),)).fetchall(): wealth+=market_catalog.get(str(r[0]),0)
        for r in conn.execute("SELECT COALESCE(SUM(amount),0) FROM deposits WHERE player_id=? AND status='active'",(int(player_id),)).fetchone() or [0]: wealth+=int(r or 0)
        club=conn.execute("SELECT level,venue_style,artist_count,security_level FROM night_clubs WHERE player_id=? AND level>0",(int(player_id),)).fetchone()
        if club:
            levels={int(x.get("level",0)):int(x.get("price",0) or 0) for x in NIGHT_CLUB_LEVELS}; styles={str(x.get("id")):int(x.get("price",0) or 0) for x in NIGHT_CLUB_STYLES}
            lv,sty,artists,security=int(club[0] or 0),str(club[1] or ""),int(club[2] or 0),int(club[3] or 0)
            wealth+=levels.get(lv,0)+styles.get(sty,0)+8_000_000*artists*(artists+1)//2+sum(20_000_000+15_000_000*i for i in range(security))
        debt=conn.execute("SELECT COALESCE(SUM(MAX(amount-paid_amount,0)),0) FROM loans WHERE player_id=? AND status IN ('active','overdue')",(int(player_id),)).fetchone()
        wealth-=int((debt[0] if debt else 0) or 0)
        return max(0,int(wealth))
    finally: conn.close()

def get_avito_discovery_info(player_id:int,player_data:dict|None=None)->dict:
    """Return Avito supplier progression and the special-lot pity state.

    Progression is driven by completed Avito sales only. Passive income and
    wealth are not used for unlocking or weighting cars: once a car tier is
    opened, that car stays in the pool. Failed car rolls raise the next chance
    gradually, capped at 14%; this is anti-frustration pressure, not a guarantee.
    """
    player_data=player_data or {}
    sales=max(0,int(player_data.get("total_sales",0) or 0))

    milestone_rows=[
        (0,"Обычная поставка"),(10,"Редкая поставка"),(20,"Улучшенная поставка"),
        (35,"Премиальная поставка"),(50,"Легендарная поставка"),(75,"Элитная поставка"),
        (125,"Эксклюзивная поставка"),(175,"Титановая поставка")
    ]
    tier_label="Обычная поставка"
    next_sales=0
    for threshold,label in milestone_rows:
        if sales>=threshold:
            tier_label=label
        elif not next_sales:
            next_sales=threshold

    car_tiers=[
        {"id":'found_hyundai_solaris',"label":'Hyundai Solaris'},
        {"id":'found_kia_rio',"label":'Kia Rio'},
        {"id":'found_camry',"label":'Toyota Camry 70'},
        {"id":'found_bmw_3',"label":'BMW 330i'},
        {"id":'found_land_cruiser',"label":'Toyota Land Cruiser 300'},
        {"id":'found_g63',"label":'Mercedes G 63 AMG'},
        {"id":'found_porsche_911',"label":'Porsche 911 Carrera'},
        {"id":'found_range_rover',"label":'Range Rover Autobiography'},
        {"id":'found_lotus_emira',"label":'Lotus Emira'},
        {"id":'found_lexus_lc500',"label":'Lexus LC 500'},
        {"id":'found_bmw_m8_competition',"label":'BMW M8 Competition Gran Coupe'},
        {"id":'found_audi_rs6_performance',"label":'Audi RS6 Avant Performance'},
        {"id":'found_urus_performante',"label":'Lamborghini Urus Performante'},
        {"id":'found_dodge_demon_170',"label":'Dodge Challenger SRT Demon 170'},
        {"id":'found_bentayga_speed',"label":'Bentley Bentayga Speed'},
        {"id":'found_pagani_huayra_roadster',"label":'Pagani Huayra Roadster'},
        {"id":'found_aston_martin_valkyrie',"label":'Aston Martin Valkyrie'},
        {"id":'found_koenigsegg_jesko_absolut',"label":'Koenigsegg Jesko Absolut'},
    ]
    max_car_tier=-1
    for idx,tier in enumerate(car_tiers):
        required=int(next((x.get("min_sales",0) for x in AVITO_FOUND_DROPS if x.get("id")==tier["id"]),0) or 0)
        if sales>=required:
            max_car_tier=idx

    conn=get_db()
    try:
        row=conn.execute(
            "SELECT COALESCE(avito_drop_misses,0),COALESCE(avito_car_cooldown,0) FROM players WHERE id=?",
            (int(player_id),)
        ).fetchone()
        misses=min(20,max(0,int(row[0] or 0))) if row else 0
    finally:
        conn.close()

    # Cars keep a random result, but restore the former 3% base chance and
    # the linear +0.5 percentage-point pressure after each failed vehicle roll.
    # It is still not guaranteed: the chance is bounded at 14% to protect the
    # economy while avoiding long dry streaks for Solaris and newly added cars.
    if max_car_tier>=0:
        sales_bonus=min(0.0040, max(0, sales-50)/900.0*0.0040)
        base_car_chance=0.0300 + min(0.0060, max_car_tier*0.0010) + sales_bonus + min(0.0020, max(0, sales-10000)/12500*0.0020)
        retry_bonus=min(0.1000, 0.0050 * misses)
        car_chance=min(0.1400, base_car_chance + retry_bonus)
    else:
        base_car_chance=0.0
        car_chance=0.0

    # Non-car special lots (iPhones, MacBooks, consoles, etc.) also become
    # noticeably more common than in the old 1% system, but remain separate
    # from the car pity meter so a phone cannot consume a guaranteed car roll.
    unlocked_non_cars=[]
    unlocked_ultra=[]
    for item in AVITO_FOUND_DROPS:
        if item.get("type")=="car":
            continue
        if sales>=int(item.get("min_sales",0) or 0):
            if item.get("ultra_find"):
                unlocked_ultra.append(item)
            else:
                unlocked_non_cars.append(item)
    # Increased from the overly low 8.2% base after the expanded product list
    # diluted each item's share. The total remains capped, while new catalogue
    # entries also receive a separate weight compensation below.
    non_car_chance=min(0.160,0.105 + min(0.055,sales/10000.0*0.055)) if unlocked_non_cars else 0.0
    # Yachts and aircraft stay genuinely rare even for veteran sellers.
    ultra_chance=min(0.0026,0.00135 + max(0,min(0.00125,(sales-75)/100000.0))) if unlocked_ultra else 0.0

    eligible=[x for x in AVITO_FOUND_DROPS if sales>=int(x.get("min_sales",0) or 0)]
    unlock_groups={}
    for threshold,label,items in AVITO_UNLOCK_MILESTONES:
        threshold=int(threshold)
        if sales<threshold:
            continue
        group=unlock_groups.setdefault(threshold,{"sales":threshold,"labels":[],"items":[]})
        label=str(label or "")
        if label and label not in group["labels"]:
            group["labels"].append(label)
        for unlocked_name in (items or []):
            unlocked_name=str(unlocked_name)
            if unlocked_name not in group["items"]:
                group["items"].append(unlocked_name)
    unlocks=[{"sales":threshold,"label":" · ".join(group["labels"]),"items":group["items"]}
             for threshold,group in sorted(unlock_groups.items())]
    return {
        "wealth":0,
        "passive_income":0,
        "sales":sales,
        "chance":round(car_chance,6),
        "max_chance":0.1400 if max_car_tier>=0 else 0.0,
        "economy_factor":0.0,
        "misses":misses,
        "car_cooldown":0,
        "max_car_tier":max_car_tier,
        "tier_label":tier_label,
        "next_sales":next_sales,
        "eligible":eligible,
        "unlocked_non_cars":unlocked_non_cars,
        "unlocked_ultra":unlocked_ultra,
        "non_car_chance":round(non_car_chance,6),
        "ultra_chance":round(ultra_chance,6),
        "hard_pity":None,
        "unlocks":unlocks,
    }


def _pick_avito_found_drop(player_id:int,player_data:dict|None=None)->dict|None:
    info=get_avito_discovery_info(player_id,player_data)
    sales=max(0,int(info.get("sales",0) or 0))
    misses=min(20,max(0,int(info.get("misses",0) or 0)))
    max_car_tier=int(info.get("max_car_tier",-1))
    car_order=['found_hyundai_solaris', 'found_kia_rio', 'found_camry', 'found_bmw_3', 'found_land_cruiser', 'found_g63', 'found_porsche_911', 'found_range_rover', 'found_lotus_emira', 'found_lexus_lc500', 'found_bmw_m8_competition', 'found_audi_rs6_performance', 'found_urus_performante', 'found_dodge_demon_170', 'found_bentayga_speed', 'found_pagani_huayra_roadster', 'found_aston_martin_valkyrie', 'found_koenigsegg_jesko_absolut']
    car_index={cid:i for i,cid in enumerate(car_order)}

    unlocked_cars=[]
    unlocked_non_cars=[]
    for x in AVITO_FOUND_DROPS:
        if sales < int(x.get("min_sales",0) or 0):
            continue
        if str(x.get("type"))=="car":
            idx=car_index.get(str(x.get("id")),-1)
            if 0<=idx<=max_car_tier:
                unlocked_cars.append(x)
        else:
            if x.get("ultra_find"):
                unlocked_non_cars.append(x)  # compatibility placeholder; filtered below
            else:
                unlocked_non_cars.append(x)

    unlocked_ultra=[x for x in unlocked_non_cars if x.get("ultra_find")]
    unlocked_non_cars=[x for x in unlocked_non_cars if not x.get("ultra_find")]

    # --- Cars: independent random roll with only a soft, non-guaranteed
    # pressure effect. There is deliberately no "20 attempts = car" rule. ---
    if unlocked_cars:
        car_chance=float(info.get("chance",0) or 0)
        car_hit=(random.random()<car_chance)
        if car_hit:
            # Price is the main rarity axis: the cheaper unlocked cars are
            # meaningfully more common, while expensive cars remain possible.
            weights=[]
            for x in unlocked_cars:
                idx=car_index.get(str(x.get("id")),0)
                rarity_weight=max(0.10,1.0/(1.0+0.42*idx))
                catalog_weight=max(0.05,float(x.get("weight",1) or 1))
                expanded_boost=1.55 if str(x.get("id")) in AVITO_EXPANDED_DROP_IDS else 1.0
                weights.append(catalog_weight*rarity_weight*expanded_boost)
            item=dict(random.choices(unlocked_cars,weights=weights,k=1)[0])
            item["value"]=random.randint(int(item["min"]),int(item["max"]))
            bmin=float(item.get("buy_min",0.66)); bmax=float(item.get("buy_max",0.82))
            if str(item.get("type"))=="car":
                bmin=max(0.56,bmin-0.10)
                bmax=max(bmin+0.08,bmax-0.08)
            item["buy_price"]=max(100,int(round(item["value"]*random.uniform(bmin,bmax))))
            conn=get_db()
            try:
                conn.execute("UPDATE players SET avito_drop_misses=0,avito_car_cooldown=0 WHERE id=?",(int(player_id),))
                conn.commit()
            finally:
                conn.close()
            return item

        # Failed car roll: advance only the soft-randomness state. It never
        # guarantees the next result and a phone roll below does not consume
        # or reset this state.
        conn=get_db()
        try:
            conn.execute(
                "UPDATE players SET avito_drop_misses=MIN(COALESCE(avito_drop_misses,0)+1,20), avito_car_cooldown=0 WHERE id=?",
                (int(player_id),)
            )
            conn.commit()
        finally:
            conn.close()

    # --- Ultra-lots (yachts / aircraft): deliberately much rarer than cars. ---
    if unlocked_ultra and random.random()<float(info.get("ultra_chance",0) or 0):
        weights=[]
        for x in unlocked_ultra:
            weights.append(max(0.01,float(x.get("weight",1) or 1)))
        item=dict(random.choices(unlocked_ultra,weights=weights,k=1)[0])
        item["value"]=random.randint(int(item["min"]),int(item["max"]))
        bmin=float(item.get("buy_min",0.78)); bmax=float(item.get("buy_max",0.90))
        item["buy_price"]=max(100,int(round(item["value"]*random.uniform(bmin,bmax))))
        return item

    # --- Phones / clothing / other premium finds: separate, more frequent roll. ---
    if unlocked_non_cars and random.random()<float(info.get("non_car_chance",0) or 0):
        weights=[]
        for x in unlocked_non_cars:
            rarity_bonus={"редкий":1.0,"эпический":0.72,"легендарный":0.42,"мифический":0.18}.get(str(x.get("rarity")),1.0)
            expanded_boost=1.65 if str(x.get("id")) in AVITO_EXPANDED_DROP_IDS else 1.0
            weights.append(max(0.05,float(x.get("weight",1) or 1))*rarity_bonus*expanded_boost)
        item=dict(random.choices(unlocked_non_cars,weights=weights,k=1)[0])
        item["value"]=random.randint(int(item["min"]),int(item["max"]))
        if item.get("profit_min") is not None:
            pmin=max(0,int(item.get("profit_min") or 0)); pmax=max(pmin,int(item.get("profit_max") or pmin))
            desired_profit=random.randint(pmin,pmax)
            item["buy_price"]=max(100,item["value"]-desired_profit)
        else:
            bmin=float(item.get("buy_min",0.66)); bmax=float(item.get("buy_max",0.82))
            item["buy_price"]=max(100,int(round(item["value"]*random.uniform(bmin,bmax))))
        return item

    return None

def get_avito_review_summary_sync(player_id:int,limit:int=8)->dict:
    conn=get_db()
    try:
        row=conn.execute("SELECT COUNT(*),COALESCE(AVG(rating),0) FROM avito_reviews WHERE player_id=?",(int(player_id),)).fetchone()
        count=int(row[0] or 0); avg=float(row[1] or 0)
        rows=conn.execute("SELECT id,buyer_id,item_name,rating,text,created_at FROM avito_reviews WHERE player_id=? ORDER BY id DESC LIMIT ?",(int(player_id),max(1,min(50,int(limit))))).fetchall()
        return {"count":count,"average":round(avg,1) if count else 0,"reviews":[dict(x) for x in rows]}
    finally: conn.close()

def maybe_create_avito_review_sync(player_id:int,buyer_id:int,item_name:str)->dict|None:
    # Buyers leave feedback sometimes, not after every sale.
    if random.random()>0.58: return None
    rating=random.choices([5,4,3,2,1],weights=[52,30,11,5,2],k=1)[0]
    positive=[
        "Взял {item}. Всё как в описании, забрал без проблем.",
        "Купил {item}. Состояние хорошее, продавец адекватный.",
        "{item} приехал как договаривались. Остался доволен.",
    ]
    neutral=[
        "Взял {item}. В целом нормально, пришлось уточнить пару моментов.",
        "{item} соответствует объявлению. Не идеально, но всё ок.",
    ]
    negative=[
        "Купил {item}. Ожидал немного лучше по состоянию.",
        "{item} получил, но впечатления средние. Есть нюансы.",
    ]
    if rating>=4: text=random.choice(positive).format(item=item_name)
    elif rating==3: text=random.choice(neutral).format(item=item_name)
    else: text=random.choice(negative).format(item=item_name)
    conn=get_db()
    try:
        now=int(time_module.time())
        conn.execute("INSERT INTO avito_reviews(player_id,buyer_id,item_name,rating,text,created_at) VALUES(?,?,?,?,?,?)",(int(player_id),int(buyer_id or 0),str(item_name)[:160],int(rating),text[:220],now))
        conn.commit()
        return {"rating":int(rating),"text":text,"item_name":str(item_name)[:160],"created_at":now}
    finally: conn.close()

def _avito_persist_player_sync(player_id:int, published=None, chats=None):
    """Persist one player's unsold Avito listing and active buyer chats."""
    pid=int(player_id)
    if published is None:
        published=published_items.get(pid)
    if chats is None:
        chats=[dict(v) for v in active_chats.values() if int(v.get("user_id",0) or 0)==pid and not v.get("finished")]
    pub=dict(published) if isinstance(published,dict) and not published.get("finished") else None
    chat_list=[dict(v) for v in (chats or []) if isinstance(v,dict) and not v.get("finished")]
    conn=get_db()
    try:
        if pub or chat_list:
            conn.execute(
                "INSERT OR REPLACE INTO avito_sessions(player_id,published_json,chats_json,updated_at) VALUES(?,?,?,?)",
                (pid,json.dumps(pub,ensure_ascii=False,separators=(",",":")) if pub else "",
                 json.dumps(chat_list,ensure_ascii=False,separators=(",",":")),int(time_module.time()))
            )
        else:
            conn.execute("DELETE FROM avito_sessions WHERE player_id=?",(pid,))
        conn.commit()
    finally:
        conn.close()


def _restore_avito_sessions_sync():
    """Restore unsold Avito sessions after a process restart."""
    conn=get_db()
    try:
        rows=conn.execute("SELECT player_id,published_json,chats_json FROM avito_sessions").fetchall()
    finally:
        conn.close()
    restored=0
    for row in rows:
        pid=int(row["player_id"])
        try:
            pub=json.loads(row["published_json"] or "") if row["published_json"] else None
        except Exception:
            pub=None
        try:
            chats=json.loads(row["chats_json"] or "[]")
        except Exception:
            chats=[]
        if isinstance(pub,dict) and not pub.get("finished"):
            published_items[pid]=pub
        if isinstance(chats,list):
            for chat in chats:
                if not isinstance(chat,dict) or chat.get("finished"): continue
                key=str(chat.get("chat_key") or "")
                if not key: continue
                active_chats[key]=chat
                restored+=1
    return restored


def _persist_avito_snapshots_sync(snapshots:dict):
    for pid,state in (snapshots or {}).items():
        _avito_persist_player_sync(int(pid), state.get("published"), state.get("chats",[]))
    return len(snapshots or {})

AVITO_ASSISTANT_COST = 5_000_000
AVITO_ASSISTANT_MAX = 5
AVITO_ASSISTANT_MIN_INTERVAL = 120   # 2 min between real procurement cycles
AVITO_ASSISTANT_MAX_INTERVAL = 240   # 4 min, visible activity without turning helpers into a money printer
AVITO_ASSISTANT_TICK_LOCKS = defaultdict(threading.Lock)


def _get_avito_assistant_count_sync(player_id:int)->int:
    conn=get_db()
    try:
        row=conn.execute("SELECT count FROM avito_assistants WHERE player_id=?",(int(player_id),)).fetchone()
        return max(0,min(AVITO_ASSISTANT_MAX,int(row[0] or 0))) if row else 0
    finally:
        conn.close()


def _set_avito_assistant_count_sync(player_id:int,count:int,next_run_at:float=0,schedule:dict|None=None)->None:
    conn=get_db()
    try:
        if schedule is None:
            row=conn.execute("SELECT schedule_json FROM avito_assistants WHERE player_id=?",(int(player_id),)).fetchone()
            try: schedule=json.loads(row[0] or "{}") if row and row[0] else {}
            except Exception: schedule={}
        conn.execute("INSERT OR REPLACE INTO avito_assistants(player_id,count,next_run_at,updated_at,schedule_json) VALUES(?,?,?,?,?)",
                     (int(player_id),max(0,min(AVITO_ASSISTANT_MAX,int(count))),float(next_run_at or 0),int(time_module.time()),json.dumps(schedule or {},separators=(",",":"))))
        conn.commit()
    finally:
        conn.close()


def _hire_avito_assistant_sync(player_id:int)->dict:
    conn=get_db(); cur=conn.cursor()
    try:
        cur.execute("BEGIN IMMEDIATE")
        row=cur.execute("SELECT balance FROM players WHERE id=?",(int(player_id),)).fetchone()
        if not row: conn.rollback(); return {"success":False,"message":"Игрок не найден."}
        balance=int(row[0] or 0)
        row=cur.execute("SELECT count FROM avito_assistants WHERE player_id=?",(int(player_id),)).fetchone()
        count=max(0,int(row[0] or 0)) if row else 0
        if count>=AVITO_ASSISTANT_MAX:
            conn.rollback(); return {"success":False,"message":f"Достигнут лимит помощников: {AVITO_ASSISTANT_MAX}."}
        if balance<AVITO_ASSISTANT_COST:
            conn.rollback(); return {"success":False,"message":f"Нужно {AVITO_ASSISTANT_COST:,} ₽ для найма помощника."}
        new_balance=balance-AVITO_ASSISTANT_COST
        now=time_module.time()
        next_run=now+random.randint(8,18)  # first real procurement shortly after hiring
        schedule={}
        if row is not None:
            try:
                old_row=cur.execute("SELECT schedule_json FROM avito_assistants WHERE player_id=?",(int(player_id),)).fetchone()
                schedule=json.loads(old_row[0] or "{}") if old_row and old_row[0] else {}
                if not isinstance(schedule,dict): schedule={}
            except Exception: schedule={}
        schedule[str(count+1)]=next_run
        cur.execute("UPDATE players SET balance=? WHERE id=?",(new_balance,int(player_id)))
        cur.execute("INSERT OR REPLACE INTO avito_assistants(player_id,count,next_run_at,updated_at,schedule_json) VALUES(?,?,?,?,?)",
                    (int(player_id),count+1,next_run,int(now),json.dumps(schedule,separators=(",",":"))))
        conn.commit()
        return {"success":True,"count":count+1,"max":AVITO_ASSISTANT_MAX,"cost":AVITO_ASSISTANT_COST,"balance":new_balance}
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()


def _assistant_supplier_item(player_id:int,player_data:dict)->dict|None:
    # Generate the same supplier pool used by Avito, but never choose an
    # expensive found-car lot for routine assistant cycles. Rare/high-value
    # finds remain a player-facing discovery mechanic.
    try:
        generate_supplier_items(player_id,player_data)
        items=list(supplier_stock["items_by_player"].get(player_id,[]))
    except Exception:
        return None
    regular=[x for x in items if x.get("item_type")!="avito_found" and int(x.get("buy_price",0) or 0)>0]
    if not regular: return None
    # Assistants favour sensible margins instead of always selecting the most expensive lot.
    weights=[]
    for x in regular:
        margin=max(0,float(x.get("margin_pct",0) or 0))
        price=max(1,float(x.get("buy_price",1) or 1))
        weights.append(max(.1,1.0+min(2.0,margin/35.0))/(1.0+price/250000.0))
    return dict(random.choices(regular,weights=weights,k=1)[0])


def _assistant_buy_item_atomic_sync(player_id:int,item:dict,assistant_no:int)->tuple[bool,dict|str]:
    price=max(1,int(item.get("buy_price",0) or 0))
    new_item={
        "uid": item.get("uid") or make_item_uid(),
        "name": str(item.get("name") or "Товар"),
        "cat": str(item.get("cat") or "Категория"),
        "buy_price": price,
        "market_price": int(item.get("market_price",price) or price),
        "rarity": item.get("rarity","обычный"),
        "rarity_color": item.get("rarity_color","⬜"),
        "assistant_bought": True,
        "assistant_no": int(assistant_no),
        "assistant_listed": True,
        "assistant_bought_at": time_module.time(),
    }
    conn=get_db(); cur=conn.cursor()
    try:
        cur.execute("BEGIN IMMEDIATE")
        row=cur.execute("SELECT balance,inventory FROM players WHERE id=?",(int(player_id),)).fetchone()
        if not row: conn.rollback(); return False,"Игрок не найден."
        balance=int(row[0] or 0)
        if balance<price:
            conn.rollback(); return False,"Недостаточно средств для закупки помощником."
        try: inv=json.loads(row[1] or "[]")
        except Exception: inv=[]
        if not isinstance(inv,list): inv=[]
        inv.append(new_item)
        cur.execute("UPDATE players SET balance=?,inventory=? WHERE id=?",
                    (balance-price,json.dumps(inv,ensure_ascii=False),int(player_id)))
        if cur.rowcount!=1:
            conn.rollback(); return False,"Не удалось сохранить закупку помощника."
        conn.commit(); return True,new_item
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()


def _create_assistant_chat_sync(player_id:int,item:dict,assistant_no:int)->dict:
    now=time_module.time()
    price=max(1,int(item.get("market_price",item.get("buy_price",1)) or 1))
    # Conservative resale price: assistants do not magically obtain the best price.
    # Помощник должен работать как реальный продавец, но его сделка не должна
    # превращаться в источник гарантированного убытка. Минимальная цена сделки
    # всегда выше закупки; если рынок ниже закупки, помощник просто ждёт/
    # использует минимально положительную маржу, а не продаёт в минус.
    buy_price=max(1,int(item.get("buy_price",1) or 1))
    market_offer=max(1,int(price*random.uniform(.96,1.04)))
    min_profit=max(100,int(buy_price*0.03))
    offer=max(buy_price+min_profit,market_offer)
    offer=(offer//100)*100+99
    buyer_id=random.randint(10000,99999)
    chat_key=f"{player_id}_assistant_{assistant_no}_{uuid.uuid4().hex[:8]}"
    chat={
        "user_id":player_id,"buyer_id":buyer_id,"client_type":"assistant",
        "assistant_id":assistant_no,"item":item["name"],"item_uid":item["uid"],
        "price":price,"offer":offer,"round":1,"max_rounds":3,"finished":False,
        "phase":1,"trust":55,"dialogue":{"answer_sets":[["Показать состояние","Подтвердить наличие","Ответить коротко"],["Показать комплект","Подтвердить детали","Уточнить нюанс"],["Подтвердить условия","Обсудить цену","Завершить обсуждение"]]},
        "history":[{"role":"assistant","content":f"Здравствуйте. Интересует {item['name']}. Помощник уже проверяет состояние и комплект."}],
        "chat_key":chat_key,"item_obj":dict(item),"created_at":now,"unread":True,
        "last_activity_at":now,"assistant_next_at":now+random.randint(18,35),
    }
    active_chats[chat_key]=chat
    return chat


def _assistant_auto_sale_sync(player_id:int,chat:dict)->dict:
    # Assistant closes its own deal using the same atomic sale ledger as normal Avito sales.
    final=max(1,int(chat.get("offer",0) or 0))
    item=chat.get("item_obj") or {}
    buy=max(0,int(item.get("buy_price",0) or 0))
    raw_profit=final-buy
    sale=_complete_avito_sale_sync(player_id,chat,raw_profit)
    return sale


def _tick_avito_assistants_sync_unlocked(player_id:int)->dict:
    """Advance real assistant marketplace cycles. Called whenever Avito is opened/refreshed."""
    now=time_module.time()
    conn=get_db()
    try:
        row=conn.execute("SELECT count,next_run_at,schedule_json FROM avito_assistants WHERE player_id=?",(int(player_id),)).fetchone()
        count=max(0,min(AVITO_ASSISTANT_MAX,int(row[0] or 0))) if row else 0
        next_run=float(row[1] or 0) if row else 0
        try: schedule=json.loads(row[2] or "{}") if row and row[2] else {}
        except Exception: schedule={}
        if not isinstance(schedule,dict): schedule={}
    finally:
        conn.close()
    if count<=0: return {"count":0,"events":[]}
    # Repair/seed per-assistant schedules for old records.
    changed=False
    for i in range(1,count+1):
        if float(schedule.get(str(i),0) or 0)<=0:
            schedule[str(i)]=now+random.randint(8,18); changed=True
    if changed:
        _set_avito_assistant_count_sync(player_id,count,next_run,schedule)

    events=[]
    # Finish due assistant conversations first. They remain visible in Chats until the next poll,
    # then are marked finished and the sale is credited through the same atomic path as a human sale.
    due=[]
    for key,chat in list(active_chats.items()):
        if int(chat.get("user_id",0) or 0)!=int(player_id) or chat.get("finished") or chat.get("client_type")!="assistant": continue
        if float(chat.get("assistant_next_at",0) or 0)<=now:
            due.append((key,chat))
    for key,chat in due[:count]:
        age=now-float(chat.get("created_at",now) or now)
        if age>=90:
            sale=_assistant_auto_sale_sync(player_id,chat)
            if sale.get("success"):
                chat["finished"]=True
                events.append({"type":"sale","item":chat.get("item"),"final_price":int(sale.get("final_price",0) or 0),"profit":int(sale.get("profit",0) or 0),"assistant":int(chat.get("assistant_id",0) or 0),"chat_key":key})
            else:
                # If the item vanished due to an old/invalid session, terminate only that assistant chat.
                chat["finished"]=True
        else:
            chat["round"]=min(3,int(chat.get("round",1) or 1)+1)
            chat["phase"]=min(4,int(chat.get("phase",1) or 1)+1)
            chat["history"]=(chat.get("history") or [])+[{
                "role":"assistant","content":random.choice([
                    "Покупатель уточнил детали. Помощник отправил фото и подтверждение состояния.",
                    "Клиент вернулся с вопросом по комплекту. Помощник ответил и продолжил переговоры.",
                    "Покупатель готов торговаться. Помощник удерживает адекватную цену и ведёт сделку.",
                ])
            }]
            chat["last_activity_at"]=now; chat["unread"]=True; chat["assistant_next_at"]=now+random.randint(18,35)
            events.append({"type":"chat","item":chat.get("item"),"assistant":int(chat.get("assistant_id",0) or 0),"chat_key":key})

    # Each assistant has its own timer. At most two workers start a cycle on one
    # Avito request, preventing a five-assistant burst while keeping all hires meaningful.
    active_assistant_ids={int(c.get("assistant_id",0) or 0) for c in active_chats.values() if int(c.get("user_id",0) or 0)==int(player_id) and not c.get("finished") and c.get("client_type")=="assistant"}
    due_ids=[i for i in range(1,count+1) if float(schedule.get(str(i),0) or 0)<=now and i not in active_assistant_ids]
    for assistant_no in due_ids[:2]:
        player=get_player_data(player_id) or {}
        item=_assistant_supplier_item(player_id,player)
        if item:
            ok,new_item=_assistant_buy_item_atomic_sync(player_id,item,assistant_no)
            if ok:
                chat=_create_assistant_chat_sync(player_id,new_item,assistant_no)
                # Закупка помощника — внутренняя пассивная операция. Не отправляем
                # отдельное всплывающее уведомление: пользователь увидит уже итог
                # сделки, как при обычной продаже.
                _avito_persist_player_sync(player_id,None,[v for v in active_chats.values() if int(v.get("user_id",0) or 0)==int(player_id) and not v.get("finished")])
        schedule[str(assistant_no)]=now+random.randint(AVITO_ASSISTANT_MIN_INTERVAL,AVITO_ASSISTANT_MAX_INTERVAL)
    if due_ids:
        next_global=min(float(schedule.get(str(i),now+AVITO_ASSISTANT_MAX_INTERVAL) or now+AVITO_ASSISTANT_MAX_INTERVAL) for i in range(1,count+1))
        _set_avito_assistant_count_sync(player_id,count,next_global,schedule)
    return {"count":count,"events":events}


def _tick_avito_assistants_sync(player_id:int)->dict:
    # Avito can be polled from several UI paths at once (opening the sheet,
    # switching tabs, refresh button, and the 7-second poller). Serialize one
    # player's assistant cycle so one chat can never be processed twice by
    # overlapping requests.
    lock=AVITO_ASSISTANT_TICK_LOCKS[int(player_id)]
    with lock:
        return _tick_avito_assistants_sync_unlocked(int(player_id))



def _get_avito_assistant_meta_sync(player_id:int)->dict:
    conn=get_db()
    try:
        row=conn.execute("SELECT count,next_run_at,updated_at FROM avito_assistants WHERE player_id=?",(int(player_id),)).fetchone()
        return {"count":int(row[0] or 0) if row else 0,"next_run_at":float(row[1] or 0) if row else 0.0,"updated_at":int(row[2] or 0) if row else 0}
    finally:
        conn.close()

