# Direction-specific progression for the Info Business career.  The level is
# earned by actually running the company: building, shipping, fixing, hiring,
# marketing and handling business events.  It deliberately does not grow from
# the passive live pulse.
INFO_LEVELS = [
    {"level":1,"xp":0,"projects":1,"team":0,"rank":"СОЛО-ОСНОВАТЕЛЬ"},
    {"level":2,"xp":250,"projects":2,"team":1,"rank":"ПЕРВЫЙ СОТРУДНИК"},
    {"level":3,"xp":650,"projects":3,"team":2,"rank":"СТУДИЯ"},
    {"level":4,"xp":1200,"projects":4,"team":4,"rank":"КОМАНДА"},
    {"level":5,"xp":2000,"projects":5,"team":6,"rank":"АГЕНТСТВО"},
    {"level":6,"xp":3200,"projects":5,"team":8,"rank":"КОМПАНИЯ"},
    {"level":7,"xp":5000,"projects":5,"team":10,"rank":"ГРУППА"},
    {"level":8,"xp":7500,"projects":5,"team":12,"rank":"КОРПОРАЦИЯ"},
]

def _info_level_for_xp(xp:int)->dict:
    xp=max(0,int(xp or 0))
    current=INFO_LEVELS[0]
    for item in INFO_LEVELS:
        if xp>=item["xp"]: current=item
        else: break
    idx=INFO_LEVELS.index(current)
    nxt=INFO_LEVELS[idx+1] if idx+1<len(INFO_LEVELS) else None
    return {"level":current["level"],"xp":xp,"next_xp":nxt["xp"] if nxt else None,"rank":current["rank"],"max_projects":current["projects"],"team_slots":current["team"]}

def _ensure_info_progress(st:dict, meta:dict|None=None)->dict:
    meta=meta if isinstance(meta,dict) else {}
    prog=st.setdefault("progress",{})
    if "xp" not in prog:
        # Smooth migration for saves created by the older generic career XP.
        prog["xp"]=max(0,int(meta.get("xp",0) or 0))
    info=_info_level_for_xp(int(prog.get("xp",0) or 0))
    prog.update(info)
    st["level"]=info["level"]; st["xp"]=info["xp"]; st["rank"]=info["rank"]
    return info

def _add_info_xp(st:dict, amount:int, meta:dict|None=None)->tuple[dict,int,bool]:
    before=_ensure_info_progress(st,meta); old_level=int(before["level"])
    prog=st.setdefault("progress",{}); prog["xp"]=int(prog.get("xp",0) or 0)+max(0,int(amount or 0))
    after=_ensure_info_progress(st,meta)
    return after,max(0,int(amount or 0)),int(after["level"])>old_level

