def _brand_migrate_v2(st:dict):
    """Additive migration. Never removes legacy brand fields or progress."""
    st.setdefault("logo", "")
    st.setdefault("brand_style", st.get("style") or "minimal")
    st.setdefault("brand_schema", 2)
    # Legacy saves can contain malformed scalar values after older UI versions.
    # Normalize collection fields without dropping valid records or resetting progress.
    if not isinstance(st.get("store_objects"), list): st["store_objects"] = []
    if not isinstance(st.get("factory_objects"), list): st["factory_objects"] = []
    for _key in ("products", "production_jobs", "staff", "blogger_deals", "campaigns", "history"):
        if not isinstance(st.get(_key), list): st[_key] = []
    st.setdefault("blogger_deals", [])
    st.setdefault("campaigns", [])
    st.setdefault("history", [])
    st.setdefault("last_tick_at", int(time_module.time()))
    st.setdefault("active_product_id", "")
    st.setdefault("total_production_cost", 0)
    # Migrate the old single factory without deleting it.
    old_factory=st.get("factory") if isinstance(st.get("factory"),dict) else {}
    if old_factory and not st["factory_objects"]:
        cap=int(old_factory.get("capacity",300) or 300)
        lvl=1 if cap<=5000 else (2 if cap<=12000 else 3)
        st["factory_objects"]=[{"id":_career_product_id("factory"),"city":"Москва","country":"Россия","lat":55.7558,"lng":37.6173,"level":lvl,"capacity":cap,"quality":int(old_factory.get("quality",70) or 70),"utilization":0,"status":"working","legacy":True}]
    if not st["factory_objects"] and st.get("name"):
        st["factory_objects"]=[{"id":_career_product_id("factory"),"city":"Москва","country":"Россия","lat":55.7558,"lng":37.6173,"level":1,"capacity":5000,"quality":70,"utilization":0,"status":"working","starter":True}]
    # Migrate old regional store counters into map objects.
    try: _legacy_store_count=max(0,min(100,int(st.get("stores",0) or 0)))
    except (TypeError,ValueError,OverflowError): _legacy_store_count=0
    if not st["store_objects"] and _legacy_store_count>0:
        regs=st.get("regions") if isinstance(st.get("regions"),dict) else {}
        cities=list(BRAND_CITY_CATALOG)
        for i in range(_legacy_store_count):
            city=cities[i%len(cities)]; c=BRAND_CITY_CATALOG[city]
            st["store_objects"].append({"id":_career_product_id("store"),"city":city,"country":c["country"],"lat":c["lat"],"lng":c["lng"],"type":"store","level":1,"revenue":0,"sales":0,"status":"working","legacy":True})
    for p in st.get("products",[]) if isinstance(st.get("products"),list) else []:
        if not isinstance(p,dict): continue
        p.setdefault("design","basic"); p.setdefault("material","standard_cotton"); p.setdefault("logo_position","chest"); p.setdefault("logo_size","medium")
        p.setdefault("expected_demand",50); p.setdefault("recommended_quantity",1000); p.setdefault("target_margin",0); p.setdefault("batch_count",0)
    st["brand_schema"]=2
    return st

def _brand_total_capacity(st):
    facs=st.get("factory_objects") if isinstance(st.get("factory_objects"),list) else []
    return max(5000,sum(max(0,int(x.get("capacity",0) or 0)) for x in facs if isinstance(x,dict)))

def _brand_demand(product, st):
    mat=BRAND_MATERIALS.get(str(product.get("material") or "standard_cotton"),BRAND_MATERIALS["standard_cotton"])
    price=max(1,int(product.get("price",1) or 1)); cost=max(1,int(product.get("cost",1) or 1))
    quality=int(product.get("quality",mat["quality"]) or mat["quality"])
    reputation=int(st.get("reputation",0) or 0); marketing=int(st.get("marketing",0) or 0); stores=len(st.get("store_objects") or [])
    price_factor=max(0.25,min(1.35,2400/max(price,600)))
    margin_signal=max(0.2,min(1.3,quality/75))
    demand=max(1,min(100,round((quality*0.42+reputation*0.18+marketing*0.10+stores*6+mat["demand"]*0.20)*price_factor*margin_signal)))
    return demand

def _brand_v2_reconcile_stock(st):
    """Refresh legacy aggregate inventory from the per-product stock ledger.

    V3 snapshots contain normalized warehouse_stock fields; do not overwrite their
    inventory from a legacy scalar. For genuine V2 saves, available units are the
    sum of product.stock, so a sold-out product must never leave a phantom warehouse
    count blocking the next batch.
    """
    if not isinstance(st, dict):
        return
    products=st.get("products") if isinstance(st.get("products"), list) else []
    if not products or st.get("brand_id") or any(isinstance(p,dict) and "warehouse_stock" in p for p in products):
        return
    if not all(isinstance(p,dict) and ("stock" in p or "produced" in p) for p in products):
        return
    total=sum(max(0,_career_safe_int(p.get("stock"),0,0,100000000)) for p in products)
    st["warehouse"]=total
    st["units"]=total


def _brand_tick_sales(st, now=None):
    """Server-authoritative lightweight sales tick. Called on career reads/actions."""
    now=int(now or time_module.time()); _brand_migrate_v2(st)
    _brand_v2_reconcile_stock(st)
    last=int(st.get("last_tick_at",now) or now); elapsed=max(0,min(now-last,24*3600));
    if elapsed<30: return 0,0
    units_sold=0; revenue=0
    products=st.get("products") if isinstance(st.get("products"),list) else []
    stores=st.get("store_objects") if isinstance(st.get("store_objects"),list) else []
    store_power=sum(float(BRAND_STORE_TYPES.get(str(x.get("type") or "store"),BRAND_STORE_TYPES["store"])["sales"]) for x in stores)
    campaign_boost=1.0
    for c in st.get("campaigns") if isinstance(st.get("campaigns"),list) else []:
        if isinstance(c,dict) and int(c.get("ends_at",0) or 0)>now: campaign_boost+=float(c.get("demand_boost",0) or 0)
    for p in products:
        if not isinstance(p,dict): continue
        stock=max(0,int(p.get("stock",0) or 0));
        if stock<=0: continue
        demand=_brand_demand(p,st); p["expected_demand"]=demand
        per_hour=max(0.0,(demand/100.0)*(0.4+store_power*0.7)*campaign_boost*max(1,elapsed/3600)*max(1,int(p.get("produced",0) or 0)/5000))
        sold=min(stock,max(0,int(round(per_hour))))
        if sold<=0: continue
        p["stock"]=stock-sold; p["sold"]=int(p.get("sold",0))+sold
        units_sold+=sold; rev=sold*max(1,int(p.get("price",0) or 0)); revenue+=rev
        p["status"]="hit" if demand>=78 else ("good" if demand>=55 else "slow")
    if units_sold:
        st["sales"]=int(st.get("sales",0))+units_sold; st["units"]=max(0,int(st.get("units",0))-units_sold); st["warehouse"]=max(0,int(st.get("warehouse",0))-units_sold); st["revenue"]=int(st.get("revenue",0))+revenue
        for x in stores:
            if isinstance(x,dict): x["sales"]=int(x.get("sales",0))+max(0,units_sold//max(1,len(stores))); x["revenue"]=int(x.get("revenue",0))+max(0,revenue//max(1,len(stores)))
        st.setdefault("history",[]).append({"type":"sales","units":units_sold,"revenue":revenue,"at":now})
        st["history"]=st["history"][-30:]
    st["last_tick_at"]=now
    return units_sold,revenue



