def get_avito_level_info(sales:int)->dict:
    sales=max(0,int(sales or 0))
    # This is a display label only. There is no separate XP/progression system.
    if sales < 5: level,name=1,"НОВИЧОК"
    elif sales < 15: level,name=2,"НАЧИНАЮЩИЙ"
    elif sales < 25: level,name=3,"ПРОДАВЕЦ"
    elif sales < 50: level,name=4,"ПРО"
    elif sales < 100: level,name=5,"ЭКСПЕРТ"
    elif sales < 250: level,name=6,"ЭЛИТА"
    else: level,name=7,"ТИТАН"
    next_threshold=next((x for x in (5,15,25,50,100,250) if sales<x),None)
    prev=max([x for x in (0,5,15,25,50,100,250) if x<=sales],default=0)
    # Persuasion is a direct function of real completed sales, not a new XP bar.
    persuasion=min(100,round(20 + sales*0.32))
    price_boost_pct=min(18,round(sales/2500*18,1))
    return {"level":level,"name":name,"sales":sales,"next_sales":next_threshold,"prev_sales":prev,"persuasion":persuasion,"price_boost_pct":price_boost_pct}

# ==================== ГЕНЕРАЦИЯ ТОВАРОВ У ПОСТАВЩИКОВ ====================
def generate_supplier_items(player_id:int,player_data:dict,market_state_ready:bool=False):
    # Avito's state route already hydrates the market before an explicit refresh.
    # Keep the default behavior for assistant/background callers, but don't repeat
    # the same DB market-state work on the player's foreground refresh path.
    if not market_state_ready:
        player_data=ensure_market_state_sync(player_id,player_data)
    player_data=player_data or {}
    demand=player_data.get("market_demand",{}) or {}
    # Supplier quality improves with completed Avito sales. Beginners still see
    # the full basic pool, while experienced resellers get a meaningfully
    # higher chance of uncommon/rare/epic/legendary lots.
    sales=max(0,int(player_data.get("total_sales",0) or 0))
    rarities=list(SUPPLIER_ITEM_RARITIES); weights=[]
    rarity_boost={"COMMON":1.0,"UNCOMMON":1.0+min(0.75,sales/100),"RARE":1.0+min(2.5,sales/60),"EPIC":1.0+min(5.0,sales/50),"LEGENDARY":1.0+min(8.0,sales/40)}
    for r in rarities:
        weights.append(float(SUPPLIER_ITEM_RARITIES[r]["chance"])*rarity_boost.get(str(r).upper(),1.0))
    total=sum(weights) or 1; weights=[w/total for w in weights]
    items=[]; used=set()
    for _ in range(random.randint(8,10)):
        rarity=random.choices(rarities,weights=weights,k=1)[0]; rd=SUPPLIER_ITEM_RARITIES[rarity]; base=random.choice(BASE_ITEMS); dm=float(demand.get(base["cat"],1.0))
        market=max(50,int(round(base["base_price"]*random.uniform(rd["price_mult_min"],rd["price_mult_max"])*(0.92+0.10*dm)*1.0)))
        buy_factor=max(0.45,min(0.82,random.uniform(0.58,0.80)-max(0,dm-1.3)*0.035)); bp=max(50,int(round(market*buy_factor)))
        iid=uuid.uuid4().int%900000000+100000000
        while iid in used: iid=uuid.uuid4().int%900000000+100000000
        used.add(iid)
        items.append({"id":iid,"uid":make_item_uid(),"name":f"{rd['color']} {base['cat']} {base['name']}","cat":base["cat"],"buy_price":bp,"market_price":market,"rarity":rarity,"rarity_color":rd["color"],"demand":dm,"expected_profit":max(0,market-bp),"margin_pct":round((market-bp)/bp*100,1) if bp else 0,"end_time":time_module.time()+random.randint(300,900)})
    # One found high-value lot may appear right inside the same supplier feed.
    found=_pick_avito_found_drop(player_id,player_data)
    if found:
        fid=uuid.uuid4().int%900000000+100000000
        buy_price=int(found["buy_price"]); market_price=int(found["value"])
        items.append({"id":fid,"uid":make_item_uid(),"name":found["name"],"cat":found["cat"],"buy_price":buy_price,"market_price":market_price,"rarity":found["rarity"],"rarity_color":"","demand":1.0,"expected_profit":max(0,market_price-buy_price),"margin_pct":round((market_price-buy_price)/buy_price*100,1) if buy_price else 0,"end_time":time_module.time()+random.randint(300,900),"item_type":"avito_found","found_type":found["type"],"found_id":found["id"],"found_icon":found["icon"],"description":found["desc"],"min_sales":int(found["min_sales"]),"min_wealth":int(found.get("min_wealth",0) or 0)})
        random.shuffle(items)
    supplier_stock["items_by_player"][player_id]=items; supplier_stock["last_update_by_player"][player_id]=time_module.time()

def check_supplier_update(player_id: int, player_data: dict):
    last_update = supplier_stock["last_update_by_player"].get(player_id, 0)
    items = supplier_stock["items_by_player"].get(player_id, [])
    # если прошло больше 5 минут или список пуст – генерируем новый
    if time_module.time() - last_update >= 300 or not items:
        generate_supplier_items(player_id, player_data)
        return True
    # удаляем просроченные товары (по end_time)
    now = time_module.time()
    fresh_items = [i for i in items if i["end_time"] > now]
    supplier_stock["items_by_player"][player_id] = fresh_items
    return False

async def get_supplier_items(player_id: int, player_data: dict):
    async with supplier_lock:
        check_supplier_update(player_id, player_data)
        return supplier_stock["items_by_player"].get(player_id, [])

# ==================== РЕАЛЬНЫЕ ЦЕНЫ С BINANCE SPOT ====================
async def fetch_crypto_prices():
    """Единый источник цен трейдинга: только Binance Spot.
    Никакого CoinGecko, локальной синтетики или подмены цены.
    Используем официальный Binance API через общий прокси с резервными
    официальными Binance-hosts.
    """
    symbols = {"BTC":"BTCUSDT", "ETH":"ETHUSDT", "SOL":"SOLUSDT", "DOGE":"DOGEUSDT"}
    try:
        result = {}
        for asset, symbol in symbols.items():
            data = await _binance_public(f"/api/v3/ticker/price?symbol={symbol}")
            price = float(data.get("price"))
            if not price > 0:
                raise ValueError(f"invalid Binance price for {symbol}")
            result[asset] = price
        return result
    except Exception as e:
        print(f"⚠️ Ошибка получения цен с Binance Spot: {e}")
    return None

async def fetch_binance_single_price(asset: str):
    """Возвращает только реальную текущую Binance Spot цену."""
    symbols = {"BTC":"BTCUSDT", "ETH":"ETHUSDT", "SOL":"SOLUSDT", "DOGE":"DOGEUSDT"}
    symbol = symbols.get(asset)
    if not symbol:
        return None
    try:
        data = await _binance_public(f"/api/v3/ticker/price?symbol={symbol}")
        price = float(data.get("price"))
        return price if price > 0 else None
    except Exception as e:
        print(f"⚠️ Binance Spot single price failed for {asset}: {e}")
        return None

