async def start_chat_for_item(seller_id:int,buyer_id:int,item:dict,pub:dict)->dict:
    async with chats_lock:
        item_uid=str(item.get("uid") or item.get("name"))
        for chat in active_chats.values():
            if chat.get("user_id")==seller_id and not chat.get("finished") and str(chat.get("item_uid"))==item_uid:
                return {"success":False,"message":"Чат по этому экземпляру товара уже существует"}
        client_type=random.choices(["normal","skeptic","trader"],weights=[55,30,15],k=1)[0]
        price=max(1,int(item.get("market_price",1)))
        if client_type=="trader": offer=max(100,int(price*random.uniform(.72,.90))); offer=(offer//100)*100+99
        elif client_type=="skeptic": offer=max(100,int(price*random.uniform(.88,.98)))
        else: offer=price
        special_type=str(item.get("found_type") or item.get("hunt_type") or item.get("type") or "")
        if special_type in AVITO_SPECIAL_DIALOGUES:
            hpool=AVITO_SPECIAL_DIALOGUES[special_type]
            seed=int(hashlib.sha256(f"special-dialog:{seller_id}:{item_uid}:{int(time_module.time()//86400)}".encode()).hexdigest()[:12],16)
            hs=dict(hpool[seed%len(hpool)])
            scenario={"client_type":"special","phases":list(hs.get("phases",[])),"answer_sets":[["Показать подтверждение","Дать подробности","Ответить коротко"],["Показать состояние","Уточнить детали","Ответить по факту"],["Показать комплект","Подтвердить наличие","Уточнить нюанс"],["Подтвердить условия","Обсудить детали","Завершить обсуждение"]],"final_prompt":"Хорошо. Информации достаточно — теперь решаем по цене.","final_agree":random.choice(hs.get("agree",["Договорились на {price} ₽."])),"final_decline":random.choice(hs.get("decline",["Не готов покупать."]))}
            client_type="special"
        else:
            scenario=select_dialogue_scenario(item, client_type)
        msg=scenario["phases"][0].format(item=item["name"],price=f"{price:,}",offer=f"{offer:,}")
        chat_key=f"{seller_id}_{buyer_id}_{uuid.uuid4().hex[:8]}"
        active_chats[chat_key]={"user_id":seller_id,"buyer_id":buyer_id,"client_type":client_type,"item":item["name"],"item_uid":item_uid,"price":price,"offer":offer,"round":1,"max_rounds":5,"finished":False,"phase":1,"trust":50,"dialogue":scenario,"found_type":str(item.get("found_type") or item.get("hunt_type") or item.get("type") or ""),"history":[{"role":"assistant","content":msg}],"chat_key":chat_key,"item_obj":dict(item),"created_at":time_module.time(),"unread":True,"last_activity_at":time_module.time()}
        # Return the complete chat payload as part of the publish response.
        # The frontend can open the new dialogue immediately without a second
        # /avito GET request (which was the source of the misleading Load failed
        # after a successful publication on unstable Telegram WebViews).
        return {"success":True,"message":msg,"buyer_id":buyer_id,"offer":offer,"chat_key":chat_key,
                "chat":_web_chat_payload(active_chats[chat_key])}

