def update_user_stock(player_id: int, symbol: str, quantity_change: int, price: int):
    """quantity_change может быть отрицательным (продажа). price - цена сделки."""
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT quantity, avg_buy_price FROM user_stocks WHERE player_id = ? AND symbol = ?", (player_id, symbol))
    row = cursor.fetchone()
    if row:
        old_qty = row["quantity"]
        old_avg = row["avg_buy_price"]
        new_qty = old_qty + quantity_change
        if new_qty <= 0:
            cursor.execute("DELETE FROM user_stocks WHERE player_id = ? AND symbol = ?", (player_id, symbol))
        else:
            # Новая средняя цена (для покупки)
            if quantity_change > 0:
                new_avg = (old_qty * old_avg + quantity_change * price) // new_qty
            else:
                new_avg = old_avg  # при продаже средняя не меняется
            cursor.execute(
                "UPDATE user_stocks SET quantity = ?, avg_buy_price = ? WHERE player_id = ? AND symbol = ?",
                (new_qty, new_avg, player_id, symbol)
            )
    else:
        if quantity_change > 0:
            cursor.execute(
                "INSERT INTO user_stocks (player_id, symbol, quantity, avg_buy_price) VALUES (?, ?, ?, ?)",
                (player_id, symbol, quantity_change, price)
            )
    conn.commit()
    conn.close()

def add_stock_transaction(player_id: int, symbol: str, type_op: str, quantity: int, price: int, total: int):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO stock_transactions (player_id, symbol, type, quantity, price, total, date) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (player_id, symbol, type_op, quantity, price, total, datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    )
    conn.commit()
    conn.close()

def get_stock_transactions(player_id: int, limit: int = 10) -> List[Dict[str, Any]]:
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "SELECT symbol, type, quantity, price, total, date FROM stock_transactions WHERE player_id = ? ORDER BY id DESC LIMIT ?",
        (player_id, limit)
    )
    rows = cursor.fetchall()
    conn.close()
    return [dict(row) for row in rows]

def calculate_portfolio_value(player_id: int) -> Tuple[int, int]:
    """Возвращает (общая стоимость, общая прибыль/убыток по отношению к затратам)"""
    stocks = get_user_stocks(player_id)
    total_cost = 0
    current_value = 0
    for s in stocks:
        sym = s["symbol"]
        stock_info = get_stock_price(sym)
        if stock_info:
            current_price = stock_info["price"]
            current_value += current_price * s["quantity"]
            total_cost += s["avg_buy_price"] * s["quantity"]
    profit = current_value - total_cost
    return current_value, profit

def give_dividends():
    """Фоновая задача: раз в сутки начислять дивиденды (0.5-3% от стоимости портфеля)"""
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM players")
    players = cursor.fetchall()
    for row in players:
        pid = row["id"]
        value, _ = calculate_portfolio_value(pid)
        if value > 0:
            dividend_rate = random.uniform(0.005, 0.03)  # 0.5% - 3%
            dividend = int(value * dividend_rate)
            if dividend > 0:
                cursor.execute("UPDATE players SET balance = balance + ? WHERE id = ?", (dividend, pid))
                # Запись в историю (можно опционально)
                add_stock_transaction(pid, "DIV", "dividend", 0, 0, dividend)
    conn.commit()
    conn.close()

AD_BOOST_DURATION_SEC = 10 * 60
AD_BOOST_WINDOW_SEC = 12 * 60 * 60
AD_BOOST_MAX_VIEWS = 20
AD_BOOST_MULTIPLIER = 2.0
AD_BOOST_MIN_ACCOUNT_AGE_SEC = 3 * 86400


def _ad_boost_intervals(player_id: int, start_at: int, end_at: int):
    start = int(start_at or 0); end = int(end_at or time_module.time())
    if start <= 0 or end <= start: return []
    conn = get_db()
    try:
        rows = conn.execute("SELECT started_at,expires_at FROM ad_boosts WHERE player_id=? AND expires_at>? AND started_at<? ORDER BY started_at", (int(player_id),start,end)).fetchall()
        return [(max(start,int(r['started_at'])),min(end,int(r['expires_at']))) for r in rows if int(r['expires_at'] or 0)>start and int(r['started_at'] or 0)<end]
    finally: conn.close()

def _ad_boost_overlap_seconds(player_id: int, start_at: int, end_at: int) -> int:
    intervals=sorted(_ad_boost_intervals(player_id,start_at,end_at))
    if not intervals: return 0
    total=0; cur_s,cur_e=intervals[0]
    for ss,ee in intervals[1:]:
        if ss<=cur_e: cur_e=max(cur_e,ee)
        else: total+=max(0,cur_e-cur_s); cur_s,cur_e=ss,ee
    return int(total+max(0,cur_e-cur_s))

def _ad_boosted_income_for_interval(player_id: int, start_at: int, end_at: int, hourly: int):
    start=int(start_at or 0); end=int(end_at or 0); hourly=max(0,int(hourly or 0))
    base=int(hourly*max(0,end-start)/3600.0)
    overlap=_ad_boost_overlap_seconds(player_id,start,end)
    extra=int(hourly*overlap/3600.0*(AD_BOOST_MULTIPLIER-1.0))
    return base+extra,extra

def _ad_boost_state_sync(player_id: int, now: int | None = None):
    now=int(now or time_module.time()); conn=get_db()
    try:
        active=conn.execute("SELECT COALESCE(MAX(expires_at),0) AS e FROM ad_boosts WHERE player_id=? AND expires_at>?",(int(player_id),now)).fetchone()
        recent=conn.execute("SELECT COUNT(*) AS c FROM ad_boosts WHERE player_id=? AND created_at>=?",(int(player_id),now-AD_BOOST_WINDOW_SEC)).fetchone()
        stats=conn.execute("SELECT bonus_earned FROM ad_boost_stats WHERE player_id=?",(int(player_id),)).fetchone()
        until=int(active['e'] or 0); views=int(recent['c'] or 0)
        return {"active_until":until,"active_seconds":max(0,until-now),"multiplier":AD_BOOST_MULTIPLIER if until>now else 1.0,"views_12h":views,"views_left":max(0,AD_BOOST_MAX_VIEWS-views),"duration_sec":AD_BOOST_DURATION_SEC,"bonus_earned":int(stats['bonus_earned'] or 0) if stats else 0,"max_views":AD_BOOST_MAX_VIEWS,"window_sec":AD_BOOST_WINDOW_SEC}
    finally: conn.close()


def get_upgrade_state(player_id: int):
    """Return purchased WebApp upgrade levels for a player, defaulting to level 0."""
    levels = {key: 0 for key in UPGRADE_CARDS}
    conn = get_db()
    try:
        rows = conn.execute(
            "SELECT upgrade_id, level FROM webapp_upgrades WHERE player_id = ?",
            (int(player_id),),
        ).fetchall()
        for row in rows:
            key = str(row["upgrade_id"] or "")
            if key in levels:
                try:
                    levels[key] = max(0, min(int(row["level"] or 0), len(UPGRADE_CARDS[key]["costs"])))
                except (TypeError, ValueError):
                    levels[key] = 0
        return levels
    finally:
        conn.close()


def get_upgrade_income(player_id: int) -> int:
    """Return the total passive hourly income provided by WebApp upgrades."""
    levels = get_upgrade_state(int(player_id))
    total = 0
    for key, cfg in UPGRADE_CARDS.items():
        level = int(levels.get(key, 0) or 0)
        total += level * int(cfg.get("income_per_level", 0) or 0)
    return int(total)


def get_hourly_income(player_id: int, include_referrals: bool = True, include_ad_boost: bool = True):
    player = get_player_data(player_id)
    if not player:
        return 0, {}

    house = next((h for h in HOUSES if h["id"] == player.get("house", "room")), HOUSES[0])
    house_income = _property_hourly_income(player, house)
    car = next((c for c in CARS if c["id"] == player.get("current_car", "none")), None)
    owned_cars = _safe_json_list(player.get("car_collection"))
    car_stats = _safe_car_stats(player.get("garage_car_stats"), len(owned_cars))
    current_idx = next((i for i, cid in enumerate(owned_cars) if str(cid) == str(car.get("id") if car else "")), -1)
    current_tuning = car_stats[current_idx].get("tuning") if 0 <= current_idx < len(car_stats) else {}
    car_income = _car_income_per_hour(car, current_tuning) if car else 0
    taxopark = player.get("taxopark", {"level": "none", "cars": []})
    taxopark_income = _taxi_current_hourly_sync(
        player,
        income_multiplier=1.0,
    )
    if taxopark_income > 0:
        taxopark_income += _taxi_upgrade_bonus_per_hour(_taxi_upgrades_for_player_sync(player_id))

    conn = get_db()
    now = int(time_module.time())
    shop_rows = conn.execute(
        "SELECT id, shop_id, purchase_price, last_payment, COALESCE(status, 'active') AS status FROM user_shops WHERE player_id = ?", (player_id,)
    ).fetchall()
    # HARD STOP: a business that reached its maintenance limit is seized here,
    # before ANY passive-income calculation. This also repairs old rows that
    # were still marked active after already becoming overdue.
    active_shop_rows = []
    for row in shop_rows:
        status = str(row["status"] or "active")
        if status != "active":
            continue
        shop_price = get_business_purchase_price(row["shop_id"], row["purchase_price"])
        debt = get_business_maintenance_debt(shop_price, int(row["last_payment"] or 0), now)
        limit = get_business_maintenance_limit(shop_price)
        if debt >= limit:
            conn.execute("UPDATE user_shops SET status='seized' WHERE id=? AND COALESCE(status,'active')='active'", (int(row["id"]),))
            continue
        active_shop_rows.append(row)
    if any(str(r["status"] or "active") == "active" for r in shop_rows):
        conn.commit()
    shops_income = sum(
        next((s["income_per_hour"] for s in SHOP_LEVELS if s["id"] == row["shop_id"]), 0)
        for row in active_shop_rows
    )
    mining_rows = conn.execute(
        "SELECT daily_income FROM mining_rigs WHERE player_id = ? AND status = 'active'",
        (player_id,),
    ).fetchall()
    mining_income = sum(int(r["daily_income"] or 0) for r in mining_rows) // 24
    conn.close()

    upgrade_income = get_upgrade_income(player_id)
    breakdown = {
        "house": house_income,
        "car": car_income,
        "taxopark": taxopark_income,
        "shops": shops_income,
        "mining": mining_income,
        "upgrades": upgrade_income,
    }

    referral_multiplier = get_referral_boost_multiplier(player_id)
    for key in ("car", "taxopark", "shops", "mining", "upgrades"):
        breakdown[key] = int(breakdown[key] * referral_multiplier)

    if include_referrals:
        conn = get_db()
        relations = conn.execute(
            "SELECT invitee_tg_id FROM referral_relations WHERE inviter_tg_id = ? AND reward_paid = 1",
            (int(player.get("tg_id") or 0),),
        ).fetchall()
        conn.close()
        referral_income = 0
        referral_passive_percent = get_referral_passive_percent(len(relations))
        for rel in relations:
            invitee_player_id = get_player_id_by_tg_sync(int(rel["invitee_tg_id"]))
            if invitee_player_id:
                invitee_hourly, _ = get_hourly_income(
                    invitee_player_id, include_referrals=False, include_ad_boost=False
                )
                referral_income += int(
                    invitee_hourly * referral_passive_percent / 100
                )
        breakdown["referrals"] = referral_income

    # Unified economy: every active passive source contributes its full rate.
    # There is intentionally no artificial 1.25M ₽/hour cap: new Business assets
    # must visibly increase the player's expected income and collection amount.
    total = sum(breakdown.values())
    if include_ad_boost and _ad_boost_state_sync(player_id)["active_until"] > int(time_module.time()):
        total = int(total * AD_BOOST_MULTIPLIER)
        breakdown = {k:int(v*AD_BOOST_MULTIPLIER) for k,v in breakdown.items()}
    return total, breakdown


async def calculate_max_loan(player: Dict[str, Any]) -> int:
    total_earned = player.get("total_earned", 0)
    balance = player.get("balance", 0)
    items_sold = player.get("items_sold", 0)
    
    hourly_income, _ = await run_sync_db(get_hourly_income, player["id"])
    
    base = int(total_earned * 0.2 + balance * 0.3)
    sales_bonus = min(items_sold * 1000, 100_000)
    passive_bonus = min(hourly_income * 2000, 300_000)
    max_loan = base + sales_bonus + passive_bonus
    max_loan = max(10_000, min(1_000_000, max_loan))
    return max_loan

BUSINESS_MAINTENANCE_PERIOD_SEC = 3 * 86400
BUSINESS_MAINTENANCE_RATE = 0.01
# Maintenance accrues continuously for one 3-day cycle. Reaching the full
# 3-day maintenance charge is the hard limit; reaching it seizes the
# business with no refund. There is no prepaid multi-cycle period.
BUSINESS_MAINTENANCE_MAX_DEBT_PERIOD_SEC = 3 * 86400

def get_business_purchase_price(shop_id: str, stored_price: int) -> int:
    """Return the real catalog purchase price, repairing legacy zero-price rows.

    Older user_shops rows were created before purchase_price existed and can
    therefore contain 0. Maintenance must still be based on the actual
    business price; otherwise those businesses accrue a 0₽ debt forever.
    """
    stored = int(stored_price or 0)
    if stored > 0:
        return stored
    shop = next((x for x in SHOP_LEVELS if str(x.get("id")) == str(shop_id)), None)
    return int(shop.get("price") or 0) if shop else 0

def get_maintenance_cost_shop(shop_price: int) -> int:
    return max(1, int(shop_price * BUSINESS_MAINTENANCE_RATE))

def get_business_maintenance_debt(shop_price: int, last_payment: int, now: Optional[int] = None) -> int:
    now = int(time_module.time()) if now is None else int(now)
    last_payment = int(last_payment or 0)
    # A missing legacy timestamp must never be interpreted as a full debt.
    # upgrade_db initializes it, while this defensive fallback grants the
    # business a clean cycle if a partially migrated row is encountered.
    if last_payment <= 0:
        return 0
    elapsed = max(0, now - last_payment)
    cost = get_maintenance_cost_shop(shop_price)
    debt = int(cost * elapsed / BUSINESS_MAINTENANCE_PERIOD_SEC)
    return min(cost, max(0, debt))

def get_business_maintenance_limit(shop_price: int) -> int:
    return get_maintenance_cost_shop(shop_price)

def get_maintenance_cost_taxopark(price: int) -> int:
    return int(price * 0.08)

def get_maintenance_cost_shop_per_day(shop_price: int) -> float:
    return get_maintenance_cost_shop(shop_price) / 3.0

def get_maintenance_cost_taxopark_per_day(price: int) -> float:
    return price * 0.08 / 30

async def calculate_total_debt(player_id: int) -> int:
    def _sync():
        conn=get_db(); cur=conn.cursor(); now=int(time_module.time())
        try:
            rows=cur.execute("SELECT shop_id,purchase_price,last_payment FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active'",(player_id,)).fetchall()
            return sum(get_business_maintenance_debt(get_business_purchase_price(r['shop_id'], r['purchase_price']), int(r['last_payment'] or 0), now) for r in rows)
        finally:
            conn.close()
    return int(await run_sync_db(_sync))

async def pay_all_debt(player_id: int):
    def _sync():
        conn=get_db(); cur=conn.cursor(); now=int(time_module.time())
        try:
            cur.execute("BEGIN IMMEDIATE")
            rows=cur.execute("SELECT id,shop_id,purchase_price,last_payment FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active'",(player_id,)).fetchall()
            if not rows:
                conn.rollback(); return False,"Нет активных бизнесов."
            overdue=[]; debts=[]
            for r in rows:
                debt=get_business_maintenance_debt(get_business_purchase_price(r['shop_id'], r['purchase_price']),int(r['last_payment'] or 0),now)
                limit=get_business_maintenance_limit(get_business_purchase_price(r['shop_id'], r['purchase_price']))
                if debt>=limit:
                    overdue.append(r)
                else:
                    debts.append((r,debt))
            for r in overdue:
                cur.execute("UPDATE user_shops SET status='seized' WHERE id=? AND COALESCE(status,'active')='active'",(int(r['id']),))
            if overdue:
                conn.commit()
                return False,"Часть бизнесов уже потеряна: лимит долга достигнут. Возврата нет."
            total=sum(debt for _,debt in debts)
            if total<=0:
                conn.rollback(); return False,"Обслуживание пока не накопилось."
            bal=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
            if not bal or int(bal['balance'] or 0)<total:
                conn.rollback(); return False,f"Недостаточно средств! Нужно {total}₽."
            new_balance=int(bal['balance'])-total
            for r,_ in debts:
                cur.execute("UPDATE user_shops SET last_payment=?, maintenance_notice_stage=0 WHERE id=? AND COALESCE(status,'active')='active'",(now,int(r['id'])))
            cur.execute("UPDATE players SET balance=? WHERE id=?",(new_balance,player_id))
            conn.commit(); return True,f"Обслуживание оплачено. Списано {total}₽. Баланс: {new_balance}₽."
        except Exception:
            conn.rollback(); raise
        finally: conn.close()
    return await run_sync_db(_sync)

async def pay_shop_maintenance(player_id: int, shop_id: str, shop_price: int):
    return await pay_all_debt(player_id)

async def fetch_stock_price(symbol: str) -> tuple[Optional[int], Optional[float]]:
    """Возвращает (цена_в_рублях, процент_изменения) или (None, None) при ошибке."""
    async with aiohttp.ClientSession() as session:
        try:
            url = f"https://www.alphavantage.co/query?function=GLOBAL_QUOTE&symbol={symbol}&apikey={ALPHA_VANTAGE_API_KEY}"
            async with session.get(url, timeout=10) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    quote = data.get("Global Quote", {})
                    price_str = quote.get("05. price")
                    change_pct_str = quote.get("10. change percent", "0%")
                    if price_str:
                        price_usd = float(price_str)
                        # Получаем курс рубля (можно кэшировать)
                        usd_rate = await get_usd_rub_rate()
                        price_rub = int(price_usd * usd_rate)
                        change_pct = float(change_pct_str.replace("%", ""))
                        return price_rub, change_pct
        except Exception as e:
            print(f"Ошибка получения цены {symbol}: {e}")
    return None, None

async def get_usd_rub_rate() -> float:
    try:
        async with aiohttp.ClientSession() as session:
            url = "https://www.cbr-xml-daily.ru/daily_json.js"
            async with session.get(url, timeout=5) as resp:
                data = await resp.json()
                return data["Valute"]["USD"]["Value"]
    except Exception:
        return 90.0  # запасной курс

async def update_all_stock_prices():
    # Получаем список акций без блокировки БД
    stocks = await run_sync_db(get_stock_prices)
    
    for stock in stocks:
        symbol = stock["symbol"]
        # Внешний API-запрос – вне блокировки
        price_rub, change_pct = await fetch_stock_price(symbol)
        
        if price_rub is not None:
            # Короткая блокировка только на запись
            async with db_lock:
                await run_sync_db(update_stock_price, symbol, price_rub, change_pct)
        else:
            # Симуляция изменения цены
            old_price = stock["price"]
            change_pct = random.uniform(-3.0, 3.0)
            new_price = int(old_price * (1 + change_pct / 100))
            new_price = max(100, new_price)
            async with db_lock:
                await run_sync_db(update_stock_price, symbol, new_price, change_pct)

