        sellers={}
        if seller_ids:
            def _auction_sellers():
                conn=get_db();
                try:
                    marks=','.join('?' for _ in seller_ids)
                    rows=conn.execute(f"SELECT id,nickname,tg_id FROM players WHERE id IN ({marks})",tuple(seller_ids)).fetchall()
                    return {int(r['id']):str(r['nickname'] or f"ID {r['tg_id']}") for r in rows}
                finally: conn.close()
