@dp.callback_query(lambda c: c.data.startswith("buy_mining_"))
async def buy_mining(callback: CallbackQuery):
    rig_type = callback.data.split("_")[2]  # small, medium, large
    rig = MINING_RIGS[rig_type]
    user_id = callback.from_user.id
    player_id = await get_player_id_by_tg(user_id)
    player = await run_sync_db(get_player_data, player_id)
    if player['balance'] < rig['price']:
        await safe_callback_answer(callback, f"Недостаточно денег! Нужно {rig['price']}₽", show_alert=True)
        return
    async with db_lock:
        def _legacy_mining_count():
            conn=get_db()
            try:
                return int(conn.execute("SELECT COUNT(*) AS c FROM mining_rigs WHERE player_id=? AND status='active'", (player_id,)).fetchone()['c'] or 0)
            finally:
                conn.close()
        current_count = await run_sync_db(_legacy_mining_count)
        if current_count >= MAX_MINING_RIGS:
            await safe_callback_answer(callback, f"Достигнут лимит: максимум {MAX_MINING_RIGS} ферм.", show_alert=True)
            return
        new_balance = player['balance'] - rig['price']
        await run_sync_db(update_player_data, player_id, {"balance": new_balance})
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO mining_rigs (player_id, rig_type, hash_rate, daily_income, price, purchase_time) VALUES (?, ?, ?, ?, ?, ?)",
        (player_id, rig_type, 0, rig['daily_income'], rig['price'], int(time_module.time()))
    )
    conn.commit()
    conn.close()
    await safe_delete_message(callback.message)
    await callback.message.answer(f"✅ Вы купили {rig['name']} за {rig['price']}₽. Доход {rig['daily_income']}₽/день будет начисляться каждый час.")
    await unified_profit_callback(callback)

@dp.message(Form.waiting_for_deposit_amount)
async def deposit_amount(message: Message, state: FSMContext):
    if _RESELL_MINI_APP_ONLY:
        return
    try:
        amount = int(message.text.strip())
        if amount < 10000 or amount > MAX_DEPOSIT_AMOUNT:
            raise ValueError
    except (TypeError, ValueError, AttributeError):
        await message.answer(f"❌ Сумма должна быть от 10 000 до {MAX_DEPOSIT_AMOUNT:,}₽.")
        return
    user_id = message.from_user.id
    player_id = await get_player_id_by_tg(user_id)
    player = await run_sync_db(get_player_data, player_id)  # <-- ИСПРАВЛЕНО
    if player['balance'] < amount:
        await message.answer("❌ Недостаточно средств.")
        return
    data = await state.get_data()
    duration = data['deposit_duration']
    rate = data['deposit_rate']
    
    async with db_lock:
        await run_sync_db(update_player_data, player_id, {"balance": player['balance'] - amount})  # <-- ИСПРАВЛЕНО
    
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO deposits (player_id, amount, start_time, duration_days, interest_rate) VALUES (?, ?, ?, ?, ?)",
        (player_id, amount, int(time_module.time()), duration, rate)
    )
    conn.commit()
    conn.close()
    
    await message.answer(f"✅ Депозит на {amount}₽ открыт на {duration} дней под {rate}%.\nПо окончании срока вы получите {int(amount * rate / 100) + amount}₽.")
    await state.clear()
    await message.answer("✅ Депозит успешно открыт!", reply_markup=menu_kb())

# ---------- ВСПОМОГАТЕЛЬНАЯ ФУНКЦИЯ ДЛЯ ВЫЗОВА API ИЗ БОТА ----------
player_action_locks = defaultdict(asyncio.Lock)

async def handle_action(action: PlayerAction):
    key=f"{action.platform}:{action.platform_id}"
    async with player_action_locks[key]:
        return await _handle_action_locked(action)

async def api_call(user_id: int, action: str, data: dict = None) -> dict:
    req_action = PlayerAction(platform="tg", platform_id=user_id, action=action, data=data or {})
    try:
        result = await handle_action(req_action)
        if result is None:
            return {"success": False, "message": "Неизвестное действие"}
        if not isinstance(result, dict):
            print(f"API Call Error: unexpected result type {type(result).__name__} for action={action}")
            return {"success": False, "message": "Некорректный ответ игрового обработчика"}
        return result
    except Exception as e:
        print(f"API Call Error: {e}")
        return {"success": False, "message": f"Ошибка сервера: {str(e)}"}

# ---------- ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ДЛЯ ТЕЛЕГРАМ (ОБЁРТКИ НАД API) ----------
async def get_player_skin(tg_id: int) -> str:
    r = await api_call(tg_id, "get_player_skins")
    return r.get("current", "default") if r.get("success") else "default"

async def get_nickname(tg_id: int) -> str:
    r = await api_call(tg_id, "get_stats")
    return r.get("stats", {}).get("nickname", "Торгаш") if r.get("success") else "Торгаш"

async def get_shop_name(tg_id: int) -> str:
    r = await api_call(tg_id, "get_shop_name")
    return r.get("shop_name", "Без названия") if r.get("success") else "Без названия"

async def set_nickname(tg_id: int, nickname: str) -> tuple:
    r = await api_call(tg_id, "set_nickname", {"nickname": nickname})
    return r.get("success", False), r.get("message", "")

async def set_shop_name(tg_id: int, shopname: str) -> tuple:
    r = await api_call(tg_id, "set_shop_name", {"name": shopname})
    return r.get("success", False), r.get("message", "")

# ---------- RESSELL-ONLY TELEGRAM GATE ----------
# The legacy text bot remains in this file for compatibility, but ordinary
# players must never be able to reach its handlers. The Mini App is the only
# player interface. Admin handlers, Web App data and Telegram Stars payments
# remain available to the server.
_RESELL_MINI_APP_ONLY = True

# ---------- ОБРАБОТЧИКИ КОМАНД ----------
@dp.message(Command('start'))
async def start_cmd(message: types.Message, state: FSMContext):
    """
    RESSELL bot is now a thin entry point only.
    It does not expose the old text-game UI, profile, balance or command menu.
    /start only:
      1) remembers a referral code, if present;
      2) sends the RESSELL introduction;
      3) gives one Web App button.
    """
    user_id = message.from_user.id
    args = message.text.split(maxsplit=1)
    start_arg = args[1].strip() if len(args) > 1 else ""
    # Clear any legacy FSM state so an old unfinished text flow cannot wake up.
    try:
        await state.clear()
    except Exception:
        pass

    # Secure RESSELL auth bridge. A challenge is random, short-lived, and was
    # created by this backend for the browser polling it. Confirm it only with
    # Telegram's trusted message.from_user.id; never accept a browser-supplied ID.
    if start_arg.startswith("auth_"):
        nonce = start_arg[5:].strip()
        session_token = _confirm_resell_auth_challenge(nonce, int(user_id))
        if session_token:
            try:
                await message.answer(
                    "✅ <b>Вход в RESSELL подтверждён.</b>\n\n"
                    "Вернись в открытое приложение — вход завершится автоматически.",
                    parse_mode="HTML"
                )
            except Exception as exc:
                print(f"[TG_AUTH] challenge confirmation reply failed: {type(exc).__name__}: {exc}")
        else:
            try:
                await message.answer(
                    "⌛ Запрос входа устарел или уже использован. Открой RESSELL заново и повтори вход."
                )
            except Exception:
                pass
        return

    # Referral is still recorded server-side. Nothing else from the old bot UI
    # is exposed to the player.
    if start_arg.startswith("ref_"):
        ref_code = start_arg[4:].strip()
        try:
            inviter_id = await run_sync_db(find_user_by_ref_code, ref_code)
            if inviter_id and int(inviter_id) != int(user_id):
                await run_sync_db(set_pending_referral, int(user_id), int(inviter_id), "telegram_start")
        except Exception as exc:
            print(f"[TG] referral start processing failed: {type(exc).__name__}: {exc}")

    # Keep the chat as a thin launcher only. Telegram cannot auto-open a Mini App
    # merely because a user opened the bot chat, so expose it through the chat menu
    # button and one compact launch button instead of the old welcome/text UI.
    resell_url = _resell_launch_url(user_id, start_arg if start_arg.startswith("ref_") else "")
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="ОТКРЫТЬ RESSELL", web_app=WebAppInfo(url=resell_url))]
    ])
    try:
        # Per-user launch URL carries a server-issued, user-bound RESSELL session.
        await bot.set_chat_menu_button(
            chat_id=user_id,
            menu_button=MenuButtonWebApp(
                text="RESSELL",
                web_app=WebAppInfo(url=_resell_launch_url(user_id))
            )
        )
    except Exception as exc:
        print(f"[TG] could not set RESSELL chat menu button: {type(exc).__name__}: {exc}")

    # Remove the /start command bubble where Telegram permits it, so the chat does
    # not accumulate a second text interface. The app button below remains usable.
    try:
        await message.delete()
    except Exception:
        pass
    try:
        await bot.send_message(user_id, "◼️ RESSELL", reply_markup=kb)
    except Exception as exc:
        print(f"[TG] compact RESSELL launcher failed: {type(exc).__name__}: {exc}")
        try:
            await message.answer("◼️ RESSELL", reply_markup=kb)
        except Exception:
            pass

