@dp.callback_query(lambda c: c.data.startswith("trade_up_") or c.data.startswith("trade_down_"))
async def trade_bet_callback(callback: CallbackQuery, state: FSMContext):
    direction = "up" if "up" in callback.data else "down"
    asset = callback.data.split("_")[2]
    await state.update_data(trade_asset=asset, trade_direction=direction)
    await state.set_state(Form.waiting_for_trade_amount)   # <-- ИЗМЕНЕНО
    await callback.message.answer(f"💵 Введите сумму ставки для {asset} ({direction}):\nМин: {TRADING_ASSETS[asset]['min_bet']}₽, Макс: {TRADING_ASSETS[asset]['max_bet']}₽")
    await safe_callback_answer(callback)

@dp.message(StateFilter(Form.waiting_for_trade_amount))   # <-- ИЗМЕНЕНО
async def handle_trade_bet(message: Message, state: FSMContext):
    user_id = message.from_user.id
    try:
        amount = int(message.text.strip())
    except:
        await message.answer("❌ Введите число.")
        return
    data = await state.get_data()
    asset = data.get("trade_asset")
    direction = data.get("trade_direction")
    if not asset or not direction:
        await message.answer("❌ Ошибка, начните заново.")
        await state.clear()
        return

    asset_info = TRADING_ASSETS.get(asset)
    if not asset_info:
        await message.answer("❌ Актив не найден.")
        await state.clear()
        return

    if amount < asset_info["min_bet"] or amount > asset_info["max_bet"]:
        await message.answer(f"❌ Ставка должна быть от {asset_info['min_bet']} до {asset_info['max_bet']}₽")
        return

    player_id = await get_player_id_by_tg(user_id)
    player = await run_sync_db(get_player_data, player_id)
    if not player or player.get("balance", 0) < amount:
        await message.answer("❌ Недостаточно средств!")
        await state.clear()
        return

    async with trading_lock:
        if asset not in trading_prices:
            await message.answer("❌ Цены ещё не загружены, попробуйте позже.")
            await state.clear()
            return
        start_price = trading_prices[asset]["price"]

    async with db_lock:
        def _debit_legacy_trade():
            conn=get_db(); cur=conn.cursor()
            try:
                cur.execute("BEGIN IMMEDIATE")
                changed=cur.execute("UPDATE players SET balance=balance-? WHERE id=? AND balance>=?",(amount,player_id,amount)).rowcount
                if changed!=1:
                    conn.rollback(); return None
                row=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
                conn.commit(); return int(row["balance"] if row else 0)
            except Exception:
                conn.rollback(); raise
            finally: conn.close()
        fresh_balance=await run_sync_db(_debit_legacy_trade)
    if fresh_balance is None:
        await state.clear()
        await message.answer("❌ Недостаточно средств!")
        return

    bet_id = f"{user_id}_{int(time_module.time()*1000)}"
    active_bets[bet_id] = {
        "user_id": user_id,
        "asset": asset,
        "direction": direction,
        "amount": amount,
        "start_price": start_price,
        "start_time": time_module.time()
    }

    # Не отправляем подтверждение ставки в обычный Telegram-чат.
    await state.clear()
    asyncio.create_task(check_bet_result(bet_id))

async def _get_fresh_trading_price(asset: str):
    """Финальная цена сделки с того же Binance Spot, что и график клиента."""
    price = await fetch_binance_single_price(asset)
    if price and price > 0:
        async with trading_lock:
            if asset in trading_prices:
                old=trading_prices[asset]["price"]
                trading_prices[asset]["price"]=price
                trading_prices[asset]["trend"]=(price-old)/old if old else 0
                trading_prices[asset]["history"].append(price)
        return float(price)
    async with trading_lock:
        return float(trading_prices.get(asset,{}).get("price",0) or 0)

async def check_bet_result(bet_id: str):
    await asyncio.sleep(30)
    bet = active_bets.get(bet_id)
    if not bet:
        return

    user_id = bet["user_id"]
    asset = bet["asset"]
    direction = bet["direction"]
    amount = bet["amount"]
    start_price = float(bet["start_price"])

    # Не удаляем ставку до получения финальной цены. Если Binance временно
    # недоступен, сделка останется активной и будет закрыта повторно.
    current_price = 0.0
    for attempt in range(3):
        current_price = await _get_fresh_trading_price(asset)
        if current_price and current_price > 0:
            break
        await asyncio.sleep(2 + attempt)
    if not current_price:
        asyncio.create_task(check_bet_result(bet_id))
        return

    # Снимаем ставку только после успешного получения цены, чтобы при сбое API
    # игрок никогда не потерял деньги без результата.
    active_bets.pop(bet_id, None)

    if direction == "up":
        win = current_price > start_price
    else:
        win = current_price < start_price

    payout_percent = 85
    multiplier = payout_percent / 100.0 if win else 0.0
    profit = int(round(amount * multiplier)) if win else -amount

    player_id = await get_player_id_by_tg(user_id)
    if player_id:
        payout_delta = (amount + profit) if win else 0
        lock = player_action_locks.setdefault(f"tg:{int(player_id)}", asyncio.Lock())
        async with lock:
            async with db_lock:
                def _settle_balance():
                    conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        row=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
                        if not row:
                            conn.rollback(); return None
                        current=int(row["balance"] or 0)
                        new_balance=current+payout_delta
                        cur.execute("UPDATE players SET balance=? WHERE id=?",(new_balance,player_id))
                        conn.commit(); return new_balance
                    except Exception:
                        conn.rollback(); raise
                    finally: conn.close()
                await run_sync_db(_settle_balance)

    bet_history[user_id].append({
        "asset": asset,
        "direction": "вверх" if direction == "up" else "вниз",
        "bet": amount,
        "result": "win" if win else "loss",
        "profit": profit,
        "payout_percent": payout_percent if win else 0,
        "entry_price": start_price,
        "exit_price": current_price,
        "time": time_module.time()
    })

    # Persistent settlement ledger: event progress survives page reloads and server restarts.
    if player_id:
        await audit(user_id,user_id,"trading_settlement",int(profit),f"asset={asset};direction={direction};bet={amount};result={'win' if win else 'loss'}")

    # V48: результаты трейдинга больше НЕ отправляются в обычный Telegram-бот.
    # Результат, баланс и история отображаются только внутри trading.html.
    if win and player_id:
        await run_sync_db(update_daily_quest, player_id, "trade_win", 1)

