@app.middleware("http")
async def maintenance_middleware(request:Request,call_next):
    path=request.url.path
    if path in ('/maintenance/status','/health','/api/health','/updates/latest') or path.startswith('/admin/') or path.startswith('/auth/'):
        return await call_next(request)
    if await run_sync_db(_maintenance_enabled_sync):
        uid=await _maintenance_request_user(request)
        if not (uid and await admin_allowed(int(uid))):
            if path.startswith('/api/') or path.startswith('/profile/') or path.startswith('/trading/') or request.headers.get('accept','').find('application/json')>=0:
                return JSONResponse({"success":False,"maintenance":True,"error":"Технические работы","message":"RESSELL временно недоступен"},status_code=503)
            return HTMLResponse("<html><body style='background:#050605;color:#fff;font-family:sans-serif;text-align:center;padding:60px'>RESSELL · Технические работы</body></html>",status_code=503)
    return await call_next(request)

