# ==================== TRADING MARKET PROXY ====================
# Telegram WebView иногда режет прямой Binance CORS/WebSocket. Поэтому график
# получает историю и стакан через наш backend, а backend уже ходит в Binance.
BINANCE_PUBLIC_HOSTS = [
    "https://api.binance.com",
    "https://api1.binance.com",
    "https://data-api.binance.vision",
]

async def _binance_public(path: str):
    last = None
    for host in BINANCE_PUBLIC_HOSTS:
        try:
            timeout = aiohttp.ClientTimeout(total=7)
            async with aiohttp.ClientSession(timeout=timeout) as session:
                async with session.get(host + path, headers={"Accept":"application/json"}) as resp:
                    if resp.status != 200:
                        last = RuntimeError(f"Binance HTTP {resp.status}")
                        continue
                    return await resp.json()
        except Exception as exc:
            last = exc
    raise last or RuntimeError("Binance unavailable")

