# ==================== WEB TRADING API ====================
def _trading_bet_view(bet_id, bet):
    now=time_module.time()
    duration=30
    return {
        "id": bet_id,
        "asset": bet["asset"],
        "direction": bet["direction"],
        "amount": int(bet["amount"]),
        "entry_price": float(bet["start_price"]),
        "started_at": int(bet["start_time"]*1000),
        "end_at": int((bet["start_time"]+duration)*1000),
        "remaining": max(0, int((bet["start_time"]+duration)-now)),
        "duration": duration,
    }

@app.post("/trading/open")
async def trading_open(request: Request):
    try:
        data=await request.json()
        tg_id=int(data.get("userId") or data.get("user_id") or 0)
        asset=str(data.get("asset") or "").upper()
        direction=str(data.get("direction") or "").lower()
        amount=int(data.get("amount") or 0)
        request_id=str(data.get("request_id") or "").strip()[:128]
        if not tg_id or asset not in TRADING_ASSETS or direction not in ("up","down"):
            return JSONResponse({"success":False,"error":"Некорректная сделка"},status_code=400)
        info=TRADING_ASSETS[asset]
        if amount < info["min_bet"] or amount > info["max_bet"]:
            return JSONResponse({"success":False,"error":f"Ставка от {info['min_bet']} до {info['max_bet']} ₽"},status_code=400)
        ok=_verify_telegram_webapp_request(request,tg_id)
        if not ok:
            return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
        player_id=await get_player_id_by_tg(tg_id)
        if not player_id:
            return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
        price=await fetch_binance_single_price(asset)
        if not price or price<=0:
            return JSONResponse({"success":False,"error":"Цена Binance временно недоступна"},status_code=503)
        async with trading_lock:
            # Идемпотентность: повторный tap не создаёт вторую ставку.
            if request_id:
                for bid,b in active_bets.items():
                    if b.get("user_id")==tg_id and b.get("request_id")==request_id:
                        player=await run_sync_db(get_player_data,player_id) or {}
                        return JSONResponse({"success":True,"duplicate":True,"bet":_trading_bet_view(bid,b),"balance":int(player.get("balance",0) or 0)})
            async with db_lock:
                def _debit():
                    conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        row=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
                        if not row or int(row["balance"] or 0)<amount:
                            conn.rollback(); return None
                        cur.execute("UPDATE players SET balance=balance-? WHERE id=?",(amount,player_id))
                        new_bal=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()["balance"]
                        conn.commit(); return int(new_bal)
                    except Exception:
                        conn.rollback(); raise
                    finally: conn.close()
                new_balance=await run_sync_db(_debit)
            if new_balance is None:
                return JSONResponse({"success":False,"error":"Недостаточно средств"},status_code=400)
            bet_id=f"web_{tg_id}_{uuid.uuid4().hex}"
            active_bets[bet_id]={"user_id":tg_id,"asset":asset,"direction":direction,"amount":amount,
                                "start_price":price,"start_time":time_module.time(),"request_id":request_id}
        asyncio.create_task(check_bet_result(bet_id))
        return JSONResponse({"success":True,"bet":_trading_bet_view(bet_id,active_bets[bet_id]),"balance":new_balance})
    except Exception as e:
        print(f"❌ /trading/open: {e}")
        return JSONResponse({"success":False,"error":"Ошибка открытия сделки"},status_code=500)


@app.post("/games/resell-run/claim")
async def resell_run_claim(request: Request):
    """Атомарно зачисляет один завершённый RESELL RUN в основной баланс."""
    try:
        data=await request.json()
        tg_id=int(data.get("user_id") or data.get("userId") or 0)
        amount=int(data.get("amount") or 0)
        run_id=str(data.get("run_id") or "").strip()[:128]
        score=int(data.get("score") or 0)
        level=int(data.get("level") or 1)
        world=int(data.get("world") or 0)
        if not tg_id or not run_id or amount<=0:
            return JSONResponse({"success":False,"error":"Некорректные данные RESELL RUN"},status_code=400)
        if not _verify_telegram_webapp_request(request,tg_id):
            return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
        player_id=await get_player_id_by_tg(tg_id)
        if not player_id:
            return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)

        # Сумма всё ещё приходит из клиента, поэтому держим жёсткий серверный
        # предел. Главное отличие: guard и начисление теперь находятся в ОДНОЙ
        # транзакции, поэтому невозможно отметить run как забранный и не выдать
        # деньги из-за последующего сбоя.
        safe_amount=max(0,min(amount,100000))
        if safe_amount<=0:
            return JSONResponse({"success":False,"error":"Некорректная сумма заработка"},status_code=400)

        lock=player_action_locks.setdefault(f"tg:{int(player_id)}",asyncio.Lock())
        async with lock:
            async with db_lock:
                def _claim():
                    now=int(time_module.time()); conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        cur.execute("DELETE FROM api_request_guard WHERE created_at < ?",(now-30*86400,))
                        key=f"resell-run:{tg_id}:{run_id}"
                        cur.execute("INSERT OR IGNORE INTO api_request_guard(request_key,endpoint,player_id,created_at) VALUES(?,?,?,?)",(key,"resell-run-claim",player_id,now))
                        if cur.rowcount != 1:
                            row=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
                            conn.commit()
                            return ("duplicate",int(row["balance"] or 0) if row else 0,0)
                        row=cur.execute("SELECT balance,total_earned FROM players WHERE id=?",(player_id,)).fetchone()
                        if not row:
                            conn.rollback(); return ("missing",0,0)
                        cur.execute("UPDATE players SET balance=balance+?, total_earned=total_earned+?, stat_earned_today=stat_earned_today+? WHERE id=?",(safe_amount,safe_amount,safe_amount,player_id))
                        if cur.rowcount!=1:
                            conn.rollback(); return ("error",0,0)
                        new=cur.execute("SELECT balance,total_earned FROM players WHERE id=?",(player_id,)).fetchone()
                        conn.commit()
                        return ("ok",int(new["balance"]),int(new["total_earned"]))
                    except Exception:
                        conn.rollback(); raise
                    finally:
                        conn.close()
                result=await run_sync_db(_claim)

        if result[0]=="duplicate":
            return JSONResponse({"success":False,"duplicate":True,"error":"Заработок за этот забег уже забран","balance":result[1]},status_code=409)
        if result[0]=="missing":
            return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
        if result[0]!="ok":
            return JSONResponse({"success":False,"error":"Не удалось зачислить заработок"},status_code=500)
        try:
            await audit(tg_id,tg_id,"resell_run_claim",safe_amount,f"run_id={run_id};score={score};level={level};world={world}")
        except Exception:
            pass
        return JSONResponse({"success":True,"amount":safe_amount,"balance":result[1],"total_earned":result[2],"run_id":run_id,"message":f"Заработок {safe_amount}₽ зачислен на основной баланс"})
    except Exception as e:
        print(f"❌ /games/resell-run/claim: {e}")
        return JSONResponse({"success":False,"error":"Ошибка зачисления RESELL RUN"},status_code=500)

@app.get("/trading/active")
async def trading_active(request: Request):
    try:
        tg_id=int(request.query_params.get("userId") or request.query_params.get("user_id") or 0)
        if not tg_id: return JSONResponse({"success":False,"error":"userId required"},status_code=400)
        ok=_verify_telegram_webapp_request(request,tg_id)
        if not ok: return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
        async with trading_lock:
            bets=[_trading_bet_view(bid,b) for bid,b in active_bets.items() if b.get("user_id")==tg_id]
        return JSONResponse({"success":True,"bets":bets})
    except Exception as e:
        return JSONResponse({"success":False,"error":"Ошибка"},status_code=500)

