def ensure_wheel_tables_sync():
    conn=get_db()
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS wheel_rounds(
            round_id TEXT PRIMARY KEY, player_id INTEGER NOT NULL, stake INTEGER NOT NULL,
            case_id TEXT NOT NULL DEFAULT 'rare', status TEXT NOT NULL DEFAULT 'open', result_id TEXT, result_name TEXT,
            result_rarity TEXT, result_color TEXT, result_image TEXT,
            result_value INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL,
            opened_at INTEGER, paid_at INTEGER,
            FOREIGN KEY(player_id) REFERENCES players(id))""")
        cols={r[1] for r in conn.execute("PRAGMA table_info(wheel_rounds)").fetchall()}
        if "case_id" not in cols:
            conn.execute("ALTER TABLE wheel_rounds ADD COLUMN case_id TEXT NOT NULL DEFAULT 'rare'")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_wheel_rounds_player_status ON wheel_rounds(player_id,status)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_wheel_rounds_player_created ON wheel_rounds(player_id,created_at)")
        conn.commit()
    finally: conn.close()

def _wheel_pick_result_sync(case_id="rare"):
    cfg=WHEEL_CASES.get(str(case_id),WHEEL_CASES["rare"])
    items=cfg["items"] or {}
    if not items:
        raise ValueError(f"Пустой пул контейнера: {case_id}")
    # Товарщик хранит товары без weight. Для него используем равномерный выбор;
    # для остальных контейнеров сохраняем заданные веса.
    weighted=[(item_id,item,float(item.get("weight",0) or 0)) for item_id,item in items.items()]
    total_weight=sum(w for _,_,w in weighted)
    if total_weight<=0:
        chosen=random.choice(list(items.keys()))
    else:
        r=random.random()*total_weight; cursor=0.0; chosen=list(items.keys())[-1]
        for item_id,item,w in weighted:
            cursor+=w
            if r<cursor:
                chosen=item_id
                break
    item=dict(items[chosen]); item["id"]=chosen
    if "value_min" in item:
        item["value"]=random.randint(int(item["value_min"]),int(item["value_max"]))
        item["name"]=f"💰 {item['value']:,} ₽".replace(","," ")
    else: item["value"]=0
    return item

def _wheel_public_item(row):
    if not row or not row["result_id"]: return None
    return {"id":row["result_id"],"name":row["result_name"],"rarity":row["result_rarity"],"rarityColor":row["result_color"],"image":row["result_image"],"value":int(row["result_value"] or 0),"type":"car" if str(row["result_id"]) in {str(c.get("id")) for c in CARS} else ("case_goods" if str(row["result_id"]) in WHEEL_GOODS else "money"),"case_id":str(row["case_id"] or "rare")}

def _wheel_goods_claim_sync(conn, player_id:int, goods_id:str, round_id:str=""):
    item=WHEEL_GOODS.get(str(goods_id))
    if not item: return
    row=conn.execute("SELECT inventory FROM players WHERE id=?",(int(player_id),)).fetchone()
    if not row: return
    try: inv=json.loads(row["inventory"] or "[]")
    except Exception: inv=[]
    if not isinstance(inv,list): inv=[]
    inv,_=normalize_inventory(inv)
    inv.append({
        "uid": make_item_uid(),
        "name": item["name"],
        "cat": "🎒 Товары",
        "buy_price": 0,
        "market_price": int(item.get("market_price",1)),
        "rarity": item.get("rarity","обычная"),
        "rarity_color": item.get("rarity_color","#9aa7b5"),
        "item_type": "case_goods",
        "case_goods_id": str(goods_id),
        "wheel_round_id": str(round_id or ""),
        "description": "Товар из кейса товарщика. Можно продать или выставить на продажу через RESSELL."
    })
    inv,_=normalize_inventory(inv)
    conn.execute("UPDATE players SET inventory=? WHERE id=?",(json.dumps(inv,ensure_ascii=False),int(player_id)))

def _wheel_car_claim_sync(conn, player_id:int, car_id:str):
    row=conn.execute("SELECT car_collection,garage_car_stats,current_car FROM players WHERE id=?",(int(player_id),)).fetchone()
    if not row: return
    cars=_safe_json_list(row["car_collection"] or [])
    stats=_safe_car_stats(row["garage_car_stats"] or [],len(cars))
    cars.append(str(car_id))
    stats.append({"mileage":0,"wear":0,"total_income":0,"updated_at":int(time_module.time()),"tuning":_safe_car_tuning({})})
    current=str(row["current_car"] or "none")
    new_current=str(car_id) if current in ("","none","0") else current
    conn.execute("UPDATE players SET car_collection=?,garage_car_stats=?,current_car=? WHERE id=?",(json.dumps(cars,ensure_ascii=False),json.dumps(stats,ensure_ascii=False),new_current,int(player_id)))

@app.get("/wheel/case/state")
async def wheel_case_state(request: Request, userId: int = 0, tg_id: int = 0):
    supplied_tg_id=int(userId or tg_id or 0)
    tg_id=_trusted_resell_tg_id(request, supplied_tg_id)
    if not tg_id or not _verify_telegram_webapp_request(request,tg_id): return JSONResponse({"success":False,"error":"Недействительная сессия RESSELL"},status_code=401)
    player_id=await get_player_id_by_tg(tg_id)
    if not player_id: return JSONResponse({"success":False,"error":"Аккаунт RESSELL не найден"},status_code=404)
    await run_sync_db(ensure_wheel_tables_sync)
    def _state():
        conn=get_db()
        try:
            rows=conn.execute("SELECT * FROM wheel_rounds WHERE player_id=? AND status IN ('open','revealed') ORDER BY created_at ASC",(player_id,)).fetchall()
            bal=conn.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
            return rows,int(bal["balance"] or 0) if bal else 0
        finally: conn.close()
    rows,balance=await run_sync_db(_state)
    pending=[{"round_id":r["round_id"],"stake":int(r["stake"]),"case_id":str(r["case_id"] or "rare"),"status":r["status"],"result":_wheel_public_item(r)} for r in rows]
    return JSONResponse({"success":True,"balance":balance,"pending":(pending[0] if pending else None),"pending_rounds":pending})

@app.post("/wheel/case/buy")
async def wheel_case_buy(request: Request):
    """Purchase one container. Trader/supplier case uses the same authoritative flow."""
    try:
        data=await request.json()
        if not isinstance(data,dict):
            return JSONResponse({"success":False,"error":"Некорректные данные запроса"},status_code=400)
        try:
            supplied_tg_id=int(data.get("userId") or data.get("user_id") or 0)
        except (TypeError,ValueError):
            supplied_tg_id=0
        tg_id=_trusted_resell_tg_id(request,supplied_tg_id)
        raw_case=str(data.get("case_id") or "rare").strip().lower()
        # Accept old frontend aliases for the supplier/trader container.
        case_aliases={"trader":"trader_goods","trader_case":"trader_goods","supplier":"trader_goods","supplier_goods":"trader_goods","goods":"trader_goods"}
        case_id=case_aliases.get(raw_case,raw_case)
        request_id=str(data.get("request_id") or uuid.uuid4().hex).strip()[:128]
        if not tg_id or case_id not in WHEEL_CASES:
            return JSONResponse({"success":False,"error":"Некорректные данные контейнера"},status_code=400)
        if not _verify_telegram_webapp_request(request,tg_id):
            return JSONResponse({"success":False,"error":"Недействительная сессия RESSELL"},status_code=401)
        player_id=await get_player_id_by_tg(tg_id)
        if not player_id:
            return JSONResponse({"success":False,"error":"Аккаунт RESSELL не найден"},status_code=404)
        await run_sync_db(ensure_wheel_tables_sync)
        if case_id=="trader_goods" and not WHEEL_GOODS:
            return JSONResponse({"success":False,"error":"Кейс товарщика временно недоступен: пул товаров пуст"},status_code=503)
        key=f"wheel-buy:{request_id}"
        if not await run_sync_db(claim_request_once_sync,key,"wheel-case-buy",player_id,86400):
            return JSONResponse({"success":False,"duplicate":True,"error":"Повторный запрос уже обработан"},status_code=409)
        price=int(WHEEL_CASES[case_id]["price"])
        lock=player_action_locks.setdefault(f"tg:{int(player_id)}",asyncio.Lock())
        async with lock:
            async with db_lock:
                def _buy():
                    conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        cur.execute("UPDATE players SET balance=balance-? WHERE id=? AND balance>=?",(price,player_id,price))
                        if cur.rowcount!=1:
                            conn.rollback(); return ("funds",None,None,None)
                        rid=uuid.uuid4().hex; now=int(time_module.time())
                        cur.execute("INSERT INTO wheel_rounds(round_id,player_id,stake,case_id,status,created_at) VALUES(?,?,?,?,?,?)",(rid,player_id,price,case_id,"open",now))
                        bal=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
                        if not bal:
                            conn.rollback(); return ("player_missing",None,None,None)
                        conn.commit()
                        return ("ok",rid,case_id,int(bal["balance"] or 0))
                    except Exception:
                        conn.rollback(); raise
                    finally:
                        conn.close()
                res=await run_sync_db(_buy)
        if res[0]=="funds":
            return JSONResponse({"success":False,"error":"Недостаточно R-Coin на основном балансе RESSELL"},status_code=400)
        if res[0]=="player_missing":
            return JSONResponse({"success":False,"error":"Аккаунт RESSELL не найден"},status_code=404)
        try: await activate_pending_referral(tg_id,"container_open")
        except Exception: pass
        return JSONResponse({"success":True,"round_id":res[1],"case_id":res[2],"balance":res[3],"price":price})
    except Exception as e:
        print(f"❌ Ошибка в /wheel/case/buy: {type(e).__name__}: {e}")
        return JSONResponse({"success":False,"error":"Не удалось купить контейнер. Попробуйте ещё раз."},status_code=500)

@app.post("/wheel/case/buy-many")
async def wheel_case_buy_many(request: Request):
    """Buy several containers in one atomic transaction.
    This endpoint matches the existing containers.html UI and does not alter its design or client logic.
    """
    try:
        data = await request.json()
        supplied_tg_id = int(data.get("userId") or data.get("user_id") or 0)
        tg_id = _trusted_resell_tg_id(request, supplied_tg_id)
        case_id = str(data.get("case_id") or "rare").strip()
        quantity = int(data.get("quantity") or 1)
        request_id = str(data.get("request_id") or uuid.uuid4().hex)[:128]

        if not tg_id or case_id not in WHEEL_CASES:
            return JSONResponse({"success": False, "error": "Некорректные данные контейнера"}, status_code=400)
        if quantity < 1 or quantity > 20:
            return JSONResponse({"success": False, "error": "Некорректное количество контейнеров"}, status_code=400)
        if not _verify_telegram_webapp_request(request, tg_id):
            return JSONResponse({"success": False, "error": "Недействительная сессия RESSELL"}, status_code=401)

        player_id = await get_player_id_by_tg(tg_id)
        if not player_id:
            return JSONResponse({"success": False, "error": "Аккаунт RESSELL не найден"}, status_code=404)

        await run_sync_db(ensure_wheel_tables_sync)
        key = f"wheel-buy-many:{request_id}"
        if not await run_sync_db(claim_request_once_sync, key, "wheel-case-buy-many", player_id, 86400):
            return JSONResponse({"success": False, "duplicate": True, "error": "Повторный запрос уже обработан"}, status_code=409)

        price = int(WHEEL_CASES[case_id]["price"])
        total = price * quantity
        lock = player_action_locks.setdefault(f"tg:{int(player_id)}", asyncio.Lock())
        async with lock:
            async with db_lock:
                def _buy_many():
                    conn = get_db(); cur = conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        cur.execute(
                            "UPDATE players SET balance=balance-? WHERE id=? AND balance>=?",
                            (total, player_id, total)
                        )
                        if cur.rowcount != 1:
                            conn.rollback()
                            return ("funds", [], 0)

                        now = int(time_module.time())
                        ids = []
                        for _ in range(quantity):
                            rid = uuid.uuid4().hex
                            ids.append(rid)
                            cur.execute(
                                "INSERT INTO wheel_rounds(round_id,player_id,stake,case_id,status,created_at) VALUES(?,?,?,?,?,?)",
                                (rid, player_id, price, case_id, "open", now)
                            )
                        bal = cur.execute("SELECT balance FROM players WHERE id=?", (player_id,)).fetchone()
                        conn.commit()
                        return ("ok", ids, int(bal["balance"] or 0))
                    except Exception:
                        conn.rollback()
                        raise
                    finally:
                        conn.close()

                res = await run_sync_db(_buy_many)

        if res[0] == "funds":
            return JSONResponse({"success": False, "error": "Недостаточно R-Coin на основном балансе RESSELL"}, status_code=400)

        try:
            await activate_pending_referral(tg_id, "container_open")
        except Exception:
            pass

        return JSONResponse({
            "success": True,
            "round_ids": res[1],
            "balance": res[2],
            "price": price,
            "quantity": quantity,
            "case_id": case_id
        })
    except Exception as e:
        print(f"❌ Ошибка в /wheel/case/buy-many: {e}")
        return JSONResponse({"success": False, "error": "Не удалось купить контейнеры"}, status_code=500)

@app.post("/wheel/case/open")
async def wheel_case_open(request: Request):
    try:
        data=await request.json(); supplied_tg_id=int(data.get("userId") or data.get("user_id") or 0); tg_id=_trusted_resell_tg_id(request, supplied_tg_id); rid=str(data.get("round_id") or "").strip()[:128]
        if not tg_id or not rid: return JSONResponse({"success":False,"error":"Некорректные данные"},status_code=400)
        if not _verify_telegram_webapp_request(request,tg_id): return JSONResponse({"success":False,"error":"Недействительная сессия RESSELL"},status_code=401)
        player_id=await get_player_id_by_tg(tg_id)
        if not player_id: return JSONResponse({"success":False,"error":"Аккаунт RESSELL не найден"},status_code=404)
        await run_sync_db(ensure_wheel_tables_sync)
        lock=player_action_locks.setdefault(f"tg:{int(player_id)}",asyncio.Lock())
        async with lock:
            async with db_lock:
                def _open():
                    conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        row=cur.execute("SELECT * FROM wheel_rounds WHERE round_id=? AND player_id=?",(rid,player_id)).fetchone()
                        if not row: conn.rollback(); return ("missing",None)
                        if row["status"]=="paid": conn.rollback(); return ("paid",None)
                        if row["status"]=="revealed": conn.rollback(); return ("ok",_wheel_public_item(row))
                        case_id=str(row["case_id"] or "rare")
                        item=_wheel_pick_result_sync(case_id); now=int(time_module.time())
                        cur.execute("UPDATE wheel_rounds SET status='revealed',result_id=?,result_name=?,result_rarity=?,result_color=?,result_image=?,result_value=?,opened_at=? WHERE round_id=? AND player_id=? AND status='open'",(item["id"],item["name"],item["rarity"],item["rarity_color"],item["image"],int(item["value"]),now,rid,player_id))
                        conn.commit(); return ("ok",{**item,"rarityColor":item["rarity_color"],"type":"car" if str(item["id"]) in {str(c.get("id")) for c in CARS} else ("case_goods" if str(item["id"]) in WHEEL_GOODS else "money"),"case_id":case_id})
                    except Exception: conn.rollback(); raise
                    finally: conn.close()
                res=await run_sync_db(_open)
        if res[0]=="missing": return JSONResponse({"success":False,"error":"Контейнер не найден"},status_code=404)
        if res[0]=="paid": return JSONResponse({"success":False,"error":"Контейнер уже получен"},status_code=409)
        return JSONResponse({"success":True,"result":res[1]})
    except Exception as e:
        print(f"❌ Ошибка в /wheel/case/open: {e}"); return JSONResponse({"success":False,"error":"Не удалось открыть контейнер"},status_code=500)

@app.post("/wheel/case/claim")
async def wheel_case_claim(request: Request):
    try:
        data=await request.json(); supplied_tg_id=int(data.get("userId") or data.get("user_id") or 0); tg_id=_trusted_resell_tg_id(request, supplied_tg_id); rid=str(data.get("round_id") or "").strip()[:128]
        if not tg_id or not rid: return JSONResponse({"success":False,"error":"Некорректные данные"},status_code=400)
        if not _verify_telegram_webapp_request(request,tg_id): return JSONResponse({"success":False,"error":"Недействительная сессия RESSELL"},status_code=401)
        player_id=await get_player_id_by_tg(tg_id)
        if not player_id: return JSONResponse({"success":False,"error":"Аккаунт RESSELL не найден"},status_code=404)
        await run_sync_db(ensure_wheel_tables_sync)
        lock=player_action_locks.setdefault(f"tg:{int(player_id)}",asyncio.Lock())
        async with lock:
            async with db_lock:
                def _claim():
                    conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        row=cur.execute("SELECT * FROM wheel_rounds WHERE round_id=? AND player_id=?",(rid,player_id)).fetchone()
                        if not row: conn.rollback(); return ("missing",0,0,None)
                        if row["status"]=="paid":
                            bal=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone(); conn.rollback(); return ("paid",int(bal["balance"] or 0) if bal else 0,int(row["result_value"] or 0),str(row["result_id"] or ""))
                        if row["status"]!="revealed": conn.rollback(); return ("not_revealed",0,0,None)
                        payout=int(row["result_value"] or 0); result_id=str(row["result_id"] or ""); now=int(time_module.time())
                        cur.execute("UPDATE wheel_rounds SET status='paid',paid_at=? WHERE round_id=? AND player_id=? AND status='revealed'",(now,rid,player_id))
                        if cur.rowcount!=1: conn.rollback(); return ("race",0,0,None)
                        if result_id in WHEEL_GOODS:
                            _wheel_goods_claim_sync(conn,player_id,result_id,rid)
                        elif result_id in {str(c.get("id")) for c in CARS}:
                            _wheel_car_claim_sync(conn,player_id,result_id)
                        elif payout>0:
                            cur.execute("UPDATE players SET balance=balance+? WHERE id=?",(payout,player_id))
                        bal=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone(); conn.commit(); return ("ok",int(bal["balance"] or 0) if bal else 0,payout,result_id)
                    except Exception: conn.rollback(); raise
                    finally: conn.close()
                res=await run_sync_db(_claim)
        if res[0]=="missing": return JSONResponse({"success":False,"error":"Контейнер не найден"},status_code=404)
        if res[0]=="not_revealed": return JSONResponse({"success":False,"error":"Сначала откройте контейнер"},status_code=409)
        if res[0]=="race": return JSONResponse({"success":False,"error":"Выдача награды уже выполняется"},status_code=409)
        return JSONResponse({"success":True,"balance":res[1],"reward":res[2],"reward_id":res[3],"car_added":res[3] in {str(c.get("id")) for c in CARS},"goods_added":res[3] in WHEEL_GOODS})
    except Exception as e:
        print(f"❌ Ошибка в /wheel/case/claim: {e}"); return JSONResponse({"success":False,"error":"Не удалось выдать награду"},status_code=500)

@app.post("/game_result")
async def game_result(request: Request):
    try:
        data=await request.json()
        tg_id=data.get("userId") or data.get("user_id")
        result=str(data.get("result","")).lower().strip()
        bet=int(data.get("bet",0)); win=int(data.get("win",0)); game=str(data.get("game","unknown"))[:40]
        request_id=str(data.get("request_id") or data.get("round_id") or "").strip()[:128]
        if not tg_id or result not in {"win","lose"} or bet<=0 or bet>LEGACY_CASINO_MAX_BET or win<0:
            return JSONResponse({"error":"Некорректные данные игры"},status_code=400)
        # Даже legacy-казино endpoint не должен позволять выбрать чужой tg_id.
        # Размер выигрыша по-прежнему должен определяться серверной логикой казино;
        # endpoint отмечен для отдельной миграции на server-authoritative rounds.
        if not _verify_telegram_webapp_request(request,int(tg_id)):
            return JSONResponse({"error":"Недействительная сессия Telegram"},status_code=401)
        player_id=await get_player_id_by_tg(int(tg_id))
        if not player_id:
            player_id=await run_sync_db(get_or_create_player,"tg",int(tg_id))
        if not player_id:
            return JSONResponse({"error":"Player not found"},status_code=404)
        key=f"game:{request_id}" if request_id else _request_fingerprint("game_result",int(tg_id),game,result,bet,win,bucket_seconds=2)
        if not await run_sync_db(claim_request_once_sync,key,"game_result",player_id,86400):
            current=await run_sync_db(get_player_data,player_id) or {}
            return JSONResponse({"status":"duplicate","new_balance":int(current.get("balance",0) or 0),"game":game,"result":result},status_code=409)
        lock=player_action_locks.setdefault(f"tg:{int(player_id)}",asyncio.Lock())
        async with lock:
            async with db_lock:
                def _update():
                    conn=get_db(); cur=conn.cursor()
                    try:
                        cur.execute("BEGIN IMMEDIATE")
                        row=cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()
                        if not row:
                            conn.rollback(); return None
                        current=int(row["balance"] or 0)
                        recent_profit=_legacy_casino_recent_profit_sync(cur,player_id,int(time_module.time()))
                        safe_win,safe_profit=_server_authoritative_game_result(bet,win if result=="win" else 0,game,recent_profit)
                        delta=safe_win-bet
                        if delta<0 and current<(-delta):
                            conn.rollback(); return ("funds",current)
                        cur.execute("UPDATE players SET balance=balance+?,casino_games_played=casino_games_played+1 WHERE id=? AND balance>=?",(delta,player_id,max(0,-delta)))
                        if cur.rowcount!=1:
                            conn.rollback(); return ("funds",current)
                        new_balance=int(cur.execute("SELECT balance FROM players WHERE id=?",(player_id,)).fetchone()["balance"])
                        if safe_win>0:
                            cur.execute("UPDATE players SET casino_wins=casino_wins+1,casino_total_win=casino_total_win+? WHERE id=?",(safe_win,player_id))
                        else:
                            cur.execute("UPDATE players SET casino_losses=casino_losses+1 WHERE id=?",(player_id,))
                        if bet>0: cur.execute("UPDATE players SET casino_total_bet=casino_total_bet+? WHERE id=?",(bet,player_id))
                        cur.execute("INSERT OR IGNORE INTO legacy_casino_ledger(player_id,game,bet,payout,profit,request_key,created_at) VALUES(?,?,?,?,?,?,?)",(player_id,game,bet,safe_win,safe_profit,key,int(time_module.time())))
                        conn.commit(); return ("ok",new_balance,safe_win,safe_profit)
                    except Exception:
                        conn.rollback(); raise
                    finally: conn.close()
                res=await run_sync_db(_update)
        if res is None: return JSONResponse({"error":"Player not found"},status_code=404)
        if res[0]=="funds": return JSONResponse({"status":"rejected","error":"Недостаточно средств в казино","new_balance":res[1]},status_code=400)
        await activate_pending_referral(int(tg_id), "casino_game")
        return JSONResponse({"status":"ok","new_balance":res[1],"game":game,"result":result})
    except Exception as e:
        print(f"❌ Ошибка в /game_result: {e}")
        return JSONResponse({"error":str(e)},status_code=500)

