@app.get("/referrals/preview/{tg_id}")
async def referral_preview(tg_id: int, request: Request, referrer_id: str = ""):
    if not _verify_telegram_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    token=str(referrer_id or "").strip()
    inviter_tg=await run_sync_db(resolve_referrer_token,token) if token else None
    if not inviter_tg or int(inviter_tg)==int(tg_id):
        return JSONResponse({"success":True,"has_referrer":False})
    inviter_player_id=await get_player_id_by_tg(int(inviter_tg))
    inviter_player=await run_sync_db(get_player_data,inviter_player_id) if inviter_player_id else None
    if not inviter_player:
        return JSONResponse({"success":True,"has_referrer":False})
    return JSONResponse({"success":True,"has_referrer":True,"invited_by":{"id":int(inviter_tg),"nickname":str(inviter_player.get("nickname") or "Игрок")},"inviter_reward":REFERRAL_DIRECT_REWARD,"invitee_reward":REFERRAL_INVITEE_BONUS})

@app.post("/register/{tg_id}")
async def register_webapp(tg_id: int, request: Request):
    """Create the RESSELL profile from the Telegram Mini App.

    Registration is bound to the signed Telegram initData. A valid referral is
    activated in the same request, so both sides receive their registration reward
    immediately and exactly once.
    """
    if not _verify_telegram_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    try:
        data=await request.json()
    except Exception:
        data={}
    nickname=str(data.get("nickname") or "").strip().lstrip("@").strip()
    shop_name=str(data.get("shop_name") or "").strip()
    referrer_id=str(data.get("referrer_id") or data.get("ref") or "").strip()
    if len(nickname)<2: return JSONResponse({"success":False,"error":"Минимум 2 символа!"},status_code=400)
    if len(nickname)>20: return JSONResponse({"success":False,"error":"Максимум 20 символов!"},status_code=400)
    if len(shop_name)<2: return JSONResponse({"success":False,"error":"Минимум 2 символа!"},status_code=400)
    if len(shop_name)>30: return JSONResponse({"success":False,"error":"Максимум 30 символов!"},status_code=400)

    player_id=await get_player_id_by_tg(tg_id)
    if not player_id:
        player_id=await run_sync_db(get_or_create_player,"tg",tg_id)
    if not player_id:
        return JSONResponse({"success":False,"error":"Не удалось создать профиль"},status_code=500)
    existing=await run_sync_db(find_user_by_nickname,nickname)
    if existing and int(existing["id"])!=int(player_id):
        return JSONResponse({"success":False,"error":"Этот никнейм уже занят"},status_code=400)
    ok,msg=await set_nickname(tg_id,nickname)
    if not ok: return JSONResponse({"success":False,"error":msg or "Не удалось сохранить никнейм"},status_code=400)
    ok,msg=await set_shop_name(tg_id,shop_name)
    if not ok: return JSONResponse({"success":False,"error":msg or "Не удалось сохранить название магазина"},status_code=400)
    language = str(data.get("language") or "ru").strip().lower()
    if language not in {"ru","en"}: language = "ru"
    def _save_language():
        conn=get_db(); conn.execute("UPDATE players SET language=? WHERE id=?",(language,int(player_id))); conn.commit(); conn.close()
    await run_sync_db(_save_language)

    incoming=referrer_id[4:] if referrer_id.startswith("ref_") else referrer_id
    if incoming:
        try:
            inviter_id=await run_sync_db(resolve_referrer_token,incoming)
            if inviter_id and int(inviter_id)!=int(tg_id):
                await run_sync_db(set_pending_referral,int(tg_id),int(inviter_id),"webapp_registration")
        except Exception as exc:
            print(f"⚠️ WebApp referral registration: {exc}")

    referral_result={"activated":False,"reason":"no_pending"}
    try:
        referral_result=await activate_pending_referral(int(tg_id),"webapp_registration", immediate=True)
    except Exception as exc:
        print(f"⚠️ Referral activation: {exc}")

    return JSONResponse({"success":True,"message":"Аккаунт RESSELL создан","nickname":nickname,"shop_name":shop_name,"referral":referral_result})

def _audit_safe_request_json(raw:bytes)->str:
    if not raw: return ''
    try:
        data=json.loads(raw.decode('utf-8','replace'))
        if isinstance(data,dict):
            clean=dict(data)
            for k in list(clean):
                lk=str(k).lower()
                if any(x in lk for x in ('token','authorization','initdata','hash','signature','secret','password')):
                    clean[k]='[REDACTED]'
            return json.dumps(clean,ensure_ascii=False,separators=(',',':'))[:8000]
        return json.dumps(data,ensure_ascii=False,separators=(',',':'))[:8000]
    except Exception:
        return ''

def _audit_player_snapshot_sync(tg_id:int):
    conn=get_db()
    try:
        p=conn.execute("SELECT id,balance,total_earned,total_profit,total_sales,items_sold,house,car_collection,inventory FROM players WHERE tg_id=?",(int(tg_id),)).fetchone()
        if not p: return None
        pid=int(p['id'])
        shops=int(conn.execute("SELECT COUNT(*) FROM user_shops WHERE player_id=?",(pid,)).fetchone()[0])
        taxi=int(conn.execute("SELECT COUNT(*) FROM user_taxoparks WHERE player_id=? AND status='active'",(pid,)).fetchone()[0])
        mining=int(conn.execute("SELECT COUNT(*) FROM mining_rigs WHERE player_id=? AND status='active'",(pid,)).fetchone()[0])
        market=int(conn.execute("SELECT COUNT(*) FROM resell_market_assets WHERE player_id=?",(pid,)).fetchone()[0])
        deposits=int(conn.execute("SELECT COALESCE(SUM(amount),0) FROM deposits WHERE player_id=? AND status='active'",(pid,)).fetchone()[0])
        stocks=int(conn.execute("SELECT COALESCE(SUM(quantity),0) FROM user_stocks WHERE player_id=? AND quantity>0",(pid,)).fetchone()[0])
        try: cars=len(json.loads(p['car_collection'] or '[]'))
        except Exception: cars=0
        try: inventory=len(json.loads(p['inventory'] or '[]'))
        except Exception: inventory=0
        return {'tg_id':int(tg_id),'player_id':pid,'balance':int(p['balance'] or 0),'total_earned':int(p['total_earned'] or 0),
                'total_profit':int(p['total_profit'] or 0),'total_sales':int(p['total_sales'] or 0),'items_sold':int(p['items_sold'] or 0),
                'house':str(p['house'] or 'room'),'cars':cars,'inventory':inventory,'shops':shops,'taxi':taxi,'mining':mining,'market_assets':market,'deposits':deposits,'stocks':stocks}
    finally: conn.close()

def _audit_request_details(request:Request, before, snapshot, delta:int, status_code:int)->str:
    if not snapshot:
        return f"HTTP {request.method} {request.url.path} · status={status_code}"
    changes=[]
    if before:
        for key,label in (("shops","бизнесы"),("cars","машины"),("taxi","такси"),("mining","майнинг"),("market_assets","market assets"),("inventory","инвентарь"),("deposits","депозиты"),("stocks","акции"),("total_sales","продажи"),("items_sold","товары")):
            b=int(before.get(key,0) or 0); a=int(snapshot.get(key,0) or 0)
            if a!=b: changes.append(f"{label} {b}→{a}")
        if before.get('house')!=snapshot.get('house'): changes.append(f"недвижимость {before.get('house')}→{snapshot.get('house')}")
    flag=" ⚠️ LARGE MONEY MOVE" if abs(int(delta or 0))>=1_000_000 else ""
    return (f"HTTP {request.method} {request.url.path} · status={status_code} · balance={snapshot['balance']:,} ₽ · "
            f"Δ={delta:+,} ₽{flag} · earned={snapshot['total_earned']:,} · profit={snapshot['total_profit']:,} · "
            f"sales={snapshot['total_sales']} · items={snapshot['items_sold']} · house={snapshot['house']} · "
            f"cars={snapshot['cars']} · shops={snapshot['shops']} · taxi={snapshot['taxi']} · "
            f"mining={snapshot['mining']} · market={snapshot['market_assets']} · deposits={snapshot['deposits']:,} · stocks={snapshot['stocks']}"
            + (" · CHANGES: " + ", ".join(changes) if changes else ""))

@app.middleware("http")
async def audit_and_ban_middleware(request:Request,call_next):
    # Подробный серверный аудит всех игровых API-запросов.
    # В лог никогда не попадают Telegram initData / bearer-токены.
    path=request.url.path
    prefixes=(
        '/profile/','/hold/','/business/','/upgrades/','/passive/','/quests/',
        '/epoch/','/referrals/','/referral/','/engagement/','/tycoon/','/avito/',
        '/rcoin/','/friends/','/race/','/poker/','/container/','/game_result',
        '/buy-case','/case-win','/claim-reward','/resell/','/deposit','/withdraw'
    )
    audit_enabled=(not path.startswith('/admin/')) and any(path.startswith(x) for x in prefixes)
    target=None
    if audit_enabled:
        for prefix in prefixes:
            if path.startswith(prefix):
                tail=path[len(prefix):].split('/')[0]
                if tail.isdigit(): target=int(tail)
                break
        # game_result/race/poker may carry the player id in JSON.
        body_bytes=b''
        if not target and request.method in ('POST','PUT','PATCH'):
            try:
                body_bytes=await request.body()
                payload=json.loads(body_bytes.decode('utf-8','replace') or '{}') if body_bytes else {}
                for key in ('userId','user_id','tg_id','tgId'):
                    try:
                        candidate=int(payload.get(key) or 0)
                        if candidate>0: target=candidate; break
                    except Exception: pass
            except Exception: payload={}
        elif request.method in ('POST','PUT','PATCH'):
            try:
                body_bytes=await request.body()
            except Exception: body_bytes=b''
        if target and await run_sync_db(_is_banned_sync,target):
            # Administrators retain operational access during maintenance and
            # moderation work, even if their own player record is flagged.
            if not await admin_allowed(int(target)):
                return JSONResponse({"success":False,"error":"Аккаунт заблокирован администратором","banned":True},status_code=403)
    else:
        body_bytes=b''

    # GET-поллинг интерфейса не меняет экономику и не должен запускать
    # тяжёлый before/after snapshot + запись audit_logs. Раньше каждый
    # read-only GET из /tycoon/, /profile/, /avito/ и т.д. делал несколько
    # дополнительных запросов к SQLite, что резко раздувало нагрузку
    # при нескольких одновременно открытых Mini App.
    if not audit_enabled or request.method not in {"POST", "PUT", "PATCH", "DELETE"}:
        return await call_next(request)

    request_id=request.headers.get('X-Request-ID') or uuid.uuid4().hex
    started=time_module.perf_counter()
    before=None
    try:
        if target:
            before=await run_sync_db(_audit_player_snapshot_sync,target)
    except Exception: before=None

    # request.body() is cached by Starlette, so downstream request.json() remains usable.
    try:
        response=await call_next(request)
    except Exception as exc:
        if audit_enabled and target:
            try:
                after=await run_sync_db(_audit_player_snapshot_sync,target)
                await audit(None,target,f"api:{request.method} {path}",0,
                    f"EXCEPTION {type(exc).__name__}: {str(exc)[:500]}",
                    event_type='http',method=request.method,path=path,status_code=500,
                    duration_ms=(time_module.perf_counter()-started)*1000,
                    ip=(request.client.host if request.client else ''),
                    user_agent=request.headers.get('user-agent',''),
                    before_balance=(before or {}).get('balance'),after_balance=(after or {}).get('balance'),
                    balance_delta=(after or {}).get('balance',0)-(before or {}).get('balance',0) if before and after else 0,
                    request_json=_audit_safe_request_json(body_bytes),request_id=request_id)
            except Exception: pass
        raise

    if audit_enabled:
        try:
            after=await run_sync_db(_audit_player_snapshot_sync,target) if target else None
            b=(before or {}).get('balance'); a=(after or {}).get('balance')
            delta=(int(a)-int(b)) if b is not None and a is not None else 0
            details=_audit_request_details(request,before,after,delta,response.status_code)
            await audit(None,target,f"api:{request.method} {path}",delta,details,
                event_type='http',method=request.method,path=path,status_code=response.status_code,
                duration_ms=(time_module.perf_counter()-started)*1000,
                ip=(request.client.host if request.client else ''),
                user_agent=request.headers.get('user-agent',''),
                before_balance=b,after_balance=a,balance_delta=delta,
                request_json=_audit_safe_request_json(body_bytes),request_id=request_id)
        except Exception as exc:
            print(f"⚠️ detailed audit: {exc}")
    return response


@app.post("/auth/resell/session")
async def resell_auth_session(request: Request):
    """Seamless Mini App bootstrap: validate Telegram initData and mint a RESSELL session.

    This endpoint is intentionally public at transport level, but it never trusts
    a user id supplied by the browser. The only accepted identity is the one
    cryptographically validated from Telegram.WebApp.initData.
    """
    try:
        # Resolve the signed Telegram user id first, then validate the exact
        # same raw initData against that id. No browser-supplied id is trusted.
        candidates = _telegram_init_data_candidates(request)
        signed_uid = 0
        valid_reason = "missing_init_data"
        for raw in candidates:
            data, _hash = _telegram_parse_init_data(raw)
            uid = _telegram_extract_uid(data)
            if uid <= 0:
                continue
            good, why = _telegram_verify_one(raw, uid, 365 * 24 * 60 * 60)
            if good:
                signed_uid = uid
                valid_reason = 'ok'
                break
            valid_reason = why
        if signed_uid <= 0:
            return JSONResponse({"success":False,"error":"Telegram-сессия не прошла криптографическую проверку","reason":valid_reason},status_code=401)
        token = _make_resell_launch_token(signed_uid, ttl=_RESELL_AUTH_SESSION_TTL)
        return JSONResponse({"success":True,"session":token,"tg_id":signed_uid,"expires_in":_RESELL_AUTH_SESSION_TTL})
    except Exception as exc:
        print(f"[AUTH] seamless bootstrap failed: {type(exc).__name__}: {exc}")
        return JSONResponse({"success":False,"error":"Не удалось создать RESSELL-сессию"},status_code=500)


