def _rcoin_hourly_price_sync():
    """Return one persisted RCOIN price for the current UTC hour.
    The price is random in the requested 10–12 ₽ range and stays stable
    during the hour so every player sees the same market rate.
    """
    conn=get_db()
    try:
        now=int(time_module.time())
        hour_key=now//3600
        conn.execute("CREATE TABLE IF NOT EXISTS rcoin_price_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, hour_key INTEGER UNIQUE NOT NULL, price REAL NOT NULL, created_at INTEGER NOT NULL)")
        row=conn.execute("SELECT price FROM rcoin_price_snapshots WHERE hour_key=?",(hour_key,)).fetchone()
        if row:
            price=round(float(row[0]),2)
        else:
            import random as _random
            price=round(_random.uniform(10.0,12.0),2)
            conn.execute("INSERT OR IGNORE INTO rcoin_price_snapshots(hour_key,price,created_at) VALUES(?,?,?)",(hour_key,price,now))
            conn.commit()
            row=conn.execute("SELECT price FROM rcoin_price_snapshots WHERE hour_key=?",(hour_key,)).fetchone()
            price=round(float(row[0]),2) if row else price
        return price
    finally:
        conn.close()

@app.get("/rcoin/market/{tg_id}")
async def rcoin_market(tg_id:int,request:Request):
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    def _market_snapshot():
        conn=get_db()
        try:
            now=int(time_module.time())
            hour_key=now//3600
            conn.execute("CREATE TABLE IF NOT EXISTS rcoin_price_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, hour_key INTEGER UNIQUE NOT NULL, price REAL NOT NULL, created_at INTEGER NOT NULL)")
            row=conn.execute("SELECT price FROM rcoin_price_snapshots WHERE hour_key=?",(hour_key,)).fetchone()
            if row:
                price=round(float(row[0]),2)
            else:
                import random as _random
                price=round(_random.uniform(10.0,12.0),2)
                conn.execute("INSERT OR IGNORE INTO rcoin_price_snapshots(hour_key,price,created_at) VALUES(?,?,?)",(hour_key,price,now))
                conn.commit()
                row=conn.execute("SELECT price FROM rcoin_price_snapshots WHERE hour_key=?",(hour_key,)).fetchone()
                price=round(float(row[0]),2) if row else price
            rows=conn.execute("SELECT price,created_at FROM rcoin_price_snapshots ORDER BY id DESC LIMIT 30").fetchall()
            return {"success":True,"price":price,"history":[{"created_at":int(r[1]),"price":round(float(r[0]),2)} for r in reversed(rows)]}
        finally:
            conn.close()
    return JSONResponse(await run_sync_db(_market_snapshot))

