@app.post("/ads/reward/{tg_id}")
async def ads_reward(tg_id: int, request: Request):
    if not _verify_tycoon_webapp_request(request, tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"}, status_code=401)
    try: data=await request.json()
    except Exception: data={}
    provider=str(data.get("provider") or "adsgram")[:32]
    if provider!="adsgram": return JSONResponse({"success":False,"error":"Неизвестный рекламный провайдер"},status_code=400)
    player_id=await get_player_id_by_tg(tg_id)
    if not player_id: return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    now=int(time_module.time())
    def _claim():
        conn=get_db(); cur=conn.cursor()
        try:
            cur.execute("BEGIN IMMEDIATE")
            row=cur.execute("SELECT created_at FROM players WHERE id=?",(player_id,)).fetchone()
            if not row:return {"error":"Игрок не найден"}
            created=row["created_at"]
            try:
                import datetime as _dt
                if isinstance(created,str): created_ts=int(_dt.datetime.fromisoformat(created.replace('Z','+00:00')).timestamp())
                else: created_ts=int(created or 0)
            except Exception: created_ts=0
            if created_ts and now-created_ts<AD_BOOST_MIN_ACCOUNT_AGE_SEC:return {"error":"Бонус доступен после 3 дней игры"}
            recent=cur.execute("SELECT COUNT(*) AS c FROM ad_boosts WHERE player_id=? AND created_at>=?",(player_id,now-AD_BOOST_WINDOW_SEC)).fetchone()
            views=int(recent["c"] or 0)
            if views>=AD_BOOST_MAX_VIEWS:return {"error":"Лимит рекламы: 20 просмотров за 12 часов"}
            active=cur.execute("SELECT COALESCE(MAX(expires_at),0) AS e FROM ad_boosts WHERE player_id=? AND expires_at>?",(player_id,now)).fetchone()
            active_until=max(now,int(active["e"] or 0)); expires=active_until+AD_BOOST_DURATION_SEC
            cur.execute("INSERT INTO ad_boosts(player_id,tg_id,provider,started_at,expires_at,created_at) VALUES(?,?,?,?,?,?)",(player_id,int(tg_id),provider,now,expires,now))
            conn.commit()
            return {"success":True,"active_until":expires,"duration_sec":AD_BOOST_DURATION_SEC,"views_12h":views+1,"views_left":max(0,AD_BOOST_MAX_VIEWS-(views+1)),"multiplier":AD_BOOST_MULTIPLIER}
        except Exception:
            conn.rollback(); raise
        finally: conn.close()
    result=await run_sync_db(_claim)
    if result.get("error"): return JSONResponse({"success":False,**result},status_code=400)
    await audit(tg_id,tg_id,"ad_boost",0,f"Rewarded ad: {provider}; +10m x2 income")
    return JSONResponse(result)

