DAILY_CALENDAR_REWARDS_BY_DAY = {int(x["day"]):x for x in DAILY_CALENDAR_REWARDS}
DAILY_CALENDAR_CAR_IDS = {str(x["car_id"]) for x in DAILY_CALENDAR_REWARDS if x.get("car_id")}


# ==================== RESSELL 30-DAY ACTIVE CALENDAR ENGINE V1 ====================
def _daily_calendar_cycle_key(ts:int) -> str:
    """Same daily rollover convention as the existing RESSELL daily systems (12:00 UTC+3)."""
    dt=datetime.fromtimestamp(int(ts), timezone.utc) + timedelta(hours=3)
    if dt.hour < 12:
        dt -= timedelta(days=1)
    return dt.strftime('%Y-%m-%d')

def _daily_calendar_reward(day:int) -> dict:
    item=DAILY_CALENDAR_REWARDS_BY_DAY.get(int(day))
    return dict(item) if item else {}

def _daily_calendar_upsert_row(cur, player_id:int, now:int, heartbeat_mode:str="normal") -> dict:
    cycle=_daily_calendar_cycle_key(now)
    row=cur.execute("SELECT * FROM daily_calendar WHERE player_id=?",(int(player_id),)).fetchone()
    if not row:
        # Preserve a small amount of legacy streak progress without touching XP
        # or granting a reward. Old 7-day streaks can seed at most day 8.
        legacy=cur.execute("SELECT login_streak FROM player_progress WHERE player_id=?",(int(player_id),)).fetchone()
        legacy_streak=max(0,int(legacy[0] or 0)) if legacy else 0
        seed_day=min(8, max(1, legacy_streak+1 if legacy_streak else 1))
        cur.execute(
            "INSERT INTO daily_calendar(player_id,progress_day,active_seconds,cycle_key,last_heartbeat_at,last_claim_cycle,total_claimed,last_claim_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",
            (int(player_id),int(seed_day),0,cycle,int(now),"",0,0,int(now)),
        )
        row=cur.execute("SELECT * FROM daily_calendar WHERE player_id=?",(int(player_id),)).fetchone()
        return dict(row)

    data=dict(row)
    progress_day=min(DAILY_CALENDAR_DAYS+1,max(1,int(data.get('progress_day') or 1)))
    active=min(DAILY_CALENDAR_REQUIRED_SECONDS,max(0,int(data.get('active_seconds') or 0)))
    stored_cycle=str(data.get('cycle_key') or '')
    last_heartbeat=max(0,int(data.get('last_heartbeat_at') or 0))
    last_claim_cycle=str(data.get('last_claim_cycle') or '')

    if stored_cycle != cycle:
        # Missing the previous day's claim breaks the streak. A jump of more
        # than one calendar cycle also means at least one day was skipped.
        # Once day 30 is completed, the calendar stays complete and never resets.
        skipped_days=1
        if stored_cycle:
            try:
                skipped_days=(datetime.strptime(cycle,'%Y-%m-%d').date()-datetime.strptime(stored_cycle,'%Y-%m-%d').date()).days
            except Exception:
                skipped_days=1
        if progress_day <= DAILY_CALENDAR_DAYS and (last_claim_cycle != stored_cycle or skipped_days > 1):
            progress_day=1
        active=0
        last_heartbeat=int(now)
    else:
        if str(heartbeat_mode or "normal") == "resume":
            # The app was hidden; resume the clock without counting the hidden interval.
            last_heartbeat=int(now)
        else:
            delta=max(0,min(int(now)-last_heartbeat,DAILY_CALENDAR_HEARTBEAT_CAP_SECONDS)) if last_heartbeat else 0
            if progress_day <= DAILY_CALENDAR_DAYS:
                active=min(DAILY_CALENDAR_REQUIRED_SECONDS,active+delta)
            else:
                active=0
            last_heartbeat=int(now)

    cur.execute(
        "UPDATE daily_calendar SET progress_day=?,active_seconds=?,cycle_key=?,last_heartbeat_at=?,updated_at=? WHERE player_id=?",
        (progress_day,active,cycle,last_heartbeat,int(now),int(player_id)),
    )
    return dict(cur.execute("SELECT * FROM daily_calendar WHERE player_id=?",(int(player_id),)).fetchone())

def _daily_calendar_snapshot_sync(player_id:int, now:int, heartbeat_mode:str="normal") -> dict:
    conn=get_db(); cur=conn.cursor()
    try:
        cur.execute("BEGIN IMMEDIATE")
        row=_daily_calendar_upsert_row(cur,int(player_id),int(now),heartbeat_mode)
        conn.commit()
        progress_day=int(row.get('progress_day') or 1)
        claimed_days=min(DAILY_CALENDAR_DAYS,max(0,progress_day-1))
        complete=progress_day>DAILY_CALENDAR_DAYS
        current_day=min(DAILY_CALENDAR_DAYS,max(1,progress_day))
        reward=_daily_calendar_reward(current_day) if not complete else _daily_calendar_reward(DAILY_CALENDAR_DAYS)
        active=int(row.get('active_seconds') or 0)
        ready=(not complete and active>=DAILY_CALENDAR_REQUIRED_SECONDS and str(row.get('last_claim_cycle') or '') != str(row.get('cycle_key') or ''))
        return {
            "success":True,
            "version":DAILY_CALENDAR_VERSION,
            "days":DAILY_CALENDAR_REWARDS,
            "total_days":DAILY_CALENDAR_DAYS,
            "required_seconds":DAILY_CALENDAR_REQUIRED_SECONDS,
            "active_seconds":active,
            "active_minutes":round(active/60,1),
            "active_progress":round(active/DAILY_CALENDAR_REQUIRED_SECONDS,4),
            "progress_day":current_day,
            "claimed_days":claimed_days,
            "complete":complete,
            "cycle_key":str(row.get('cycle_key') or ''),
            "last_claim_cycle":str(row.get('last_claim_cycle') or ''),
            "ready":ready,
            "reward":reward,
            "updated_at":int(row.get('updated_at') or now),
            "now":int(now),
        }
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()

def _daily_calendar_claim_sync(player_id:int, now:int) -> dict:
    conn=get_db(); cur=conn.cursor()
    try:
        cur.execute("BEGIN IMMEDIATE")
        row=_daily_calendar_upsert_row(cur,int(player_id),int(now),"normal")
        cycle=str(row.get('cycle_key') or '')
        progress_day=int(row.get('progress_day') or 1)
        active=int(row.get('active_seconds') or 0)
        if progress_day>DAILY_CALENDAR_DAYS:
            conn.rollback()
            return {"status":"complete","reward":{},"balance":None}
        if str(row.get('last_claim_cycle') or '')==cycle:
            reward=_daily_calendar_reward(progress_day)
            conn.rollback()
            return {"status":"already","reward":reward,"balance":None,"day":progress_day}
        if active<DAILY_CALENDAR_REQUIRED_SECONDS:
            reward=_daily_calendar_reward(progress_day)
            conn.rollback()
            return {"status":"locked","reward":reward,"balance":None,"day":progress_day,"active_seconds":active,"remaining_seconds":max(0,DAILY_CALENDAR_REQUIRED_SECONDS-active)}

        reward=_daily_calendar_reward(progress_day)
        cash=max(0,int(reward.get('cash') or 0))
        car_id=str(reward.get('car_id') or '')
        # Award only catalog-approved calendar cars.
        if car_id and car_id not in DAILY_CALENDAR_CAR_IDS:
            raise RuntimeError(f"Invalid calendar car: {car_id}")

        cur.execute("UPDATE players SET balance=balance+?,total_earned=total_earned+? WHERE id=?",(cash,cash,int(player_id)))
        if car_id:
            car_row=cur.execute("SELECT car_collection,garage_car_stats,current_car FROM players WHERE id=?",(int(player_id),)).fetchone()
            if car_row:
                cars=_safe_json_list(car_row['car_collection'] or [])
                stats=_safe_car_stats(car_row['garage_car_stats'] or [],len(cars))
                cars.append(car_id)
                stats.append({"mileage":0,"wear":0,"total_income":0,"updated_at":int(now),"tuning":_safe_car_tuning({})})
                # Do not auto-equip the calendar car. The reward belongs in the
                # garage while the player's current vehicle remains untouched.
                cur.execute("UPDATE players SET car_collection=?,garage_car_stats=? WHERE id=?",(json.dumps(cars,ensure_ascii=False),json.dumps(stats,ensure_ascii=False),int(player_id)))

        new_day=progress_day+1
        cur.execute(
            "UPDATE daily_calendar SET progress_day=?,active_seconds=0,last_claim_cycle=?,total_claimed=total_claimed+1,last_claim_at=?,last_heartbeat_at=?,updated_at=? WHERE player_id=?",
            (new_day,cycle, int(now), int(now), int(now), int(player_id)),
        )
        bal=cur.execute("SELECT balance FROM players WHERE id=?",(int(player_id),)).fetchone()
        balance=int(bal['balance'] if bal else 0)
        conn.commit()
        return {"status":"claimed","reward":reward,"balance":balance,"day":progress_day,"next_day":min(DAILY_CALENDAR_DAYS,new_day),"complete":new_day>DAILY_CALENDAR_DAYS}
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()

def _daily_calendar_auto_claim_sync(player_id:int, now:int) -> dict:
    # Compatibility wrapper: the timer only unlocks the reward. It never pays it out.
    snap=_daily_calendar_snapshot_sync(int(player_id),int(now),"normal")
    snap["auto_claim"]=False
    snap["claim_status"]="ready" if snap.get("ready") else "locked"
    return snap

