@app.get("/referral/income")
async def referral_income(request: Request):
    tg_id = request.query_params.get('tg_id')
    if not tg_id:
        return JSONResponse({"error": "No tg_id"}, status_code=400)
    try:
        tg_id = int(tg_id)
    except ValueError:
        return JSONResponse({"error": "Invalid tg_id"}, status_code=400)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"error": "Player not found"}, status_code=404)
    def _calc():
        conn = get_db()
        rows = conn.execute("SELECT r.invitee_tg_id FROM referral_relations r JOIN players p ON p.tg_id=r.invitee_tg_id WHERE r.inviter_tg_id=? AND r.reward_paid=1 AND p.is_banned=0", (tg_id,)).fetchall()
        conn.close()
        total_hourly=0
        count = len(rows)
        referral_passive_percent = get_referral_passive_percent(count)
        for row in rows:
            invitee_id = get_player_id_by_tg_sync(int(row["invitee_tg_id"]))
            if invitee_id:
                hourly,_ = get_hourly_income(invitee_id, include_referrals=False)
                total_hourly += int(hourly * referral_passive_percent / 100)
        return count, total_hourly, referral_passive_percent
    count, hourly, referral_passive_percent = await run_sync_db(_calc)
    return JSONResponse({"count": count, "hourly_income": hourly, "daily_income": hourly*24, "passive_percent": referral_passive_percent})

def _friends_list_sync(player_id:int):
    conn=get_db()
    try:
        rows=conn.execute(
            """SELECT p.id,p.tg_id,p.nickname,p.shop_name,p.balance,p.total_sales,p.total_profit,p.total_earned,
                      p.reputation_score,p.car_collection,p.current_car,p.house,p.taxopark,
                      COALESCE((SELECT COUNT(*) FROM user_shops us WHERE us.player_id=p.id),0) AS shop_count,
                      COALESCE((SELECT COUNT(*) FROM mining_rigs mr WHERE mr.player_id=p.id AND mr.status='active'),0) AS mining_count,
                      COALESCE((SELECT last_seen_at FROM player_security ps WHERE ps.player_id=p.id),0) AS last_seen_at
               FROM friends f
               JOIN players p ON p.id=f.friend_id
              WHERE f.player_id=?
              ORDER BY p.nickname COLLATE NOCASE""",
            (int(player_id),)
        ).fetchall()
        out=[]
        now=int(time_module.time())
        for r in rows:
            try:
                garage_raw=json.loads(r["car_collection"] or "[]")
                garage_count=len([x for x in garage_raw if x and str(x).lower() not in {"none","null"}]) if isinstance(garage_raw,list) else 0
            except Exception:
                garage_count=0
            try:
                taxi_raw=json.loads(r["taxopark"] or "{}")
                taxi_cars=taxi_raw.get("cars",[]) if isinstance(taxi_raw,dict) else []
                taxi_count=len(taxi_cars) if isinstance(taxi_cars,list) else 0
                taxi_active=bool(taxi_count or str(taxi_raw.get("level") or "none")!="none") if isinstance(taxi_raw,dict) else False
            except Exception:
                taxi_count=0; taxi_active=False
            house_active=str(r["house"] or "room") != "room"
            business_count=int(r["shop_count"] or 0)+int(r["mining_count"] or 0)+(1 if house_active else 0)+(1 if taxi_active else 0)
            last_seen=int(r["last_seen_at"] or 0)
            item={
                "id":int(r["id"]),
                "tg_id":int(r["tg_id"] or 0),
                "nickname":str(r["nickname"] or "Игрок"),
                "shop_name":str(r["shop_name"] or "Без магазина"),
                "balance":int(r["balance"] or 0),
                "total_sales":int(r["total_sales"] or 0),
                "total_profit":int(r["total_profit"] or 0),
                "total_earned":int(r["total_earned"] or 0),
                "reputation_score":int(r["reputation_score"] or 0),
                "business_count":business_count,
                "shop_count":int(r["shop_count"] or 0),
                "mining_count":int(r["mining_count"] or 0),
                "car_count":garage_count,
                "taxi_car_count":taxi_count,
                "current_car":str(r["current_car"] or "none"),
                "taxi_active":taxi_active,
                "last_seen_at":last_seen,
                "recently_active":bool(last_seen and now-last_seen <= 15*60),
            }
            item["customization"]=_public_customization_from_conn(conn,int(r["id"]),int(r["total_sales"] or 0))
            out.append(item)
        return out
    finally:
        conn.close()


def _friend_requests_sync(player_id:int):
    conn=get_db()
    try:
        rows=conn.execute(
            """SELECT fr.id,fr.sender_id,fr.receiver_id,fr.status,fr.created_at,fr.updated_at,
                      sp.tg_id AS sender_tg_id,sp.nickname AS sender_nickname,sp.shop_name AS sender_shop,
                      rp.tg_id AS receiver_tg_id,rp.nickname AS receiver_nickname,rp.shop_name AS receiver_shop
               FROM friend_requests fr
               JOIN players sp ON sp.id=fr.sender_id
               JOIN players rp ON rp.id=fr.receiver_id
              WHERE (fr.receiver_id=? OR fr.sender_id=?) AND fr.status='pending'
              ORDER BY fr.created_at DESC""",
            (int(player_id),int(player_id))
        ).fetchall()
        incoming=[]; outgoing=[]
        for r in rows:
            item={
                "id":int(r[0]),
                "status":str(r[3] or "pending"),
                "created_at":int(r[4] or 0),
                "updated_at":int(r[5] or 0),
                "sender_tg_id":int(r[6] or 0),
                "sender_nickname":str(r[7] or "Игрок"),
                "sender_shop":str(r[8] or "Без магазина"),
                "receiver_tg_id":int(r[9] or 0),
                "receiver_nickname":str(r[10] or "Игрок"),
                "receiver_shop":str(r[11] or "Без магазина"),
            }
            if int(r[2])==int(player_id): incoming.append(item)
            else: outgoing.append(item)
        return {"incoming":incoming,"outgoing":outgoing}
    finally:
        conn.close()


def _send_friend_request_sync(player_id:int, friend_tg_id:int):
    conn=get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        me=conn.execute("SELECT id,tg_id,nickname,shop_name FROM players WHERE id=?",(int(player_id),)).fetchone()
        friend=conn.execute("SELECT id,tg_id,nickname,shop_name FROM players WHERE tg_id=?",(int(friend_tg_id),)).fetchone()
        if not me or not friend:
            conn.rollback(); return {"success":False,"error":"Игрок не найден"}
        if int(friend["id"])==int(me["id"]):
            conn.rollback(); return {"success":False,"error":"Нельзя отправить заявку самому себе"}
        rel=conn.execute("SELECT 1 FROM friends WHERE player_id=? AND friend_id=?",(int(me["id"]),int(friend["id"]))).fetchone()
        if rel:
            conn.rollback(); return {"success":True,"already_friend":True,"status":"accepted","friend":{"id":int(friend["id"]),"tg_id":int(friend["tg_id"] or 0),"nickname":str(friend["nickname"] or "Игрок"),"shop_name":str(friend["shop_name"] or "Без магазина")}}
        reverse=conn.execute("SELECT id FROM friend_requests WHERE sender_id=? AND receiver_id=? AND status='pending'",(int(friend["id"]),int(me["id"]))).fetchone()
        if reverse:
            conn.rollback(); return {"success":True,"incoming_request":True,"request_id":int(reverse[0])}
        existing=conn.execute("SELECT id,status FROM friend_requests WHERE sender_id=? AND receiver_id=? ORDER BY id DESC LIMIT 1",(int(me["id"]),int(friend["id"]))).fetchone()
        if existing and str(existing[1] or '')=='pending':
            conn.rollback(); return {"success":True,"already_sent":True,"request_id":int(existing[0])}
        now=int(time_module.time())
        if existing:
            conn.execute("UPDATE friend_requests SET status='pending',created_at=?,updated_at=? WHERE id=?",(now,now,int(existing[0])))
            request_id=int(existing[0])
        else:
            cur=conn.execute("INSERT INTO friend_requests(sender_id,receiver_id,status,created_at,updated_at) VALUES(?,?,?,?,?)",(int(me["id"]),int(friend["id"]),'pending',now,now))
            request_id=int(cur.lastrowid)
        conn.commit()
        return {"success":True,"sent":True,"request_id":request_id,"recipient":{"id":int(friend["id"]),"tg_id":int(friend["tg_id"] or 0),"nickname":str(friend["nickname"] or "Игрок"),"shop_name":str(friend["shop_name"] or "Без магазина")}}
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()


def _respond_friend_request_sync(player_id:int, request_id:int, action:str):
    action=str(action or '').strip().lower()
    if action not in {'accept','reject'}:
        return {"success":False,"error":"Неизвестное действие"}
    conn=get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row=conn.execute(
            """SELECT fr.id,fr.sender_id,fr.receiver_id,fr.status,
                      sp.tg_id AS sender_tg_id,sp.nickname AS sender_nickname,sp.shop_name AS sender_shop,
                      rp.tg_id AS receiver_tg_id,rp.nickname AS receiver_nickname,rp.shop_name AS receiver_shop
               FROM friend_requests fr
               JOIN players sp ON sp.id=fr.sender_id
               JOIN players rp ON rp.id=fr.receiver_id
              WHERE fr.id=? AND fr.receiver_id=? AND fr.status='pending'""",
            (int(request_id),int(player_id))
        ).fetchone()
        if not row:
            conn.rollback(); return {"success":False,"error":"Заявка не найдена или уже обработана"}
        now=int(time_module.time())
        if action=='accept':
            conn.execute("INSERT OR IGNORE INTO friends(player_id,friend_id) VALUES(?,?)",(int(row[1]),int(row[2])))
            conn.execute("INSERT OR IGNORE INTO friends(player_id,friend_id) VALUES(?,?)",(int(row[2]),int(row[1])))
            conn.execute("UPDATE friend_requests SET status='accepted',updated_at=? WHERE id=?",(now,int(request_id)))
        else:
            conn.execute("UPDATE friend_requests SET status='rejected',updated_at=? WHERE id=?",(now,int(request_id)))
        conn.commit()
        return {"success":True,"status":"accepted" if action=='accept' else "rejected","request_id":int(request_id),"friend":{"id":int(row[1]),"tg_id":int(row[4] or 0),"nickname":str(row[5] or "Игрок"),"shop_name":str(row[6] or "Без магазина")} }
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()

def _add_friend_sync(player_id:int, friend_tg_id:int):
    conn=get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        me=conn.execute("SELECT id,tg_id,nickname,shop_name FROM players WHERE id=?",(int(player_id),)).fetchone()
        friend=conn.execute("SELECT id,tg_id,nickname,shop_name FROM players WHERE tg_id=?",(int(friend_tg_id),)).fetchone()
        if not me or not friend:
            conn.rollback(); return {"success":False,"error":"Игрок не найден"}
        if int(friend["id"])==int(me["id"]):
            conn.rollback(); return {"success":False,"error":"Нельзя добавить самого себя"}
        conn.execute("INSERT OR IGNORE INTO friends(player_id,friend_id) VALUES(?,?)",(int(me["id"]),int(friend["id"])))
        conn.execute("INSERT OR IGNORE INTO friends(player_id,friend_id) VALUES(?,?)",(int(friend["id"]),int(me["id"])))
        conn.commit()
        return {"success":True,"friend":{"id":int(friend["id"]),"tg_id":int(friend["tg_id"] or 0),"nickname":str(friend["nickname"] or "Игрок"),"shop_name":str(friend["shop_name"] or "Без магазина")},"already":False}
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()

@app.get("/friends/search/{tg_id}")
async def friends_search(tg_id:int, request:Request, q:str=""):
    if not _verify_telegram_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    pid=await get_player_id_by_tg(tg_id)
    if not pid: return JSONResponse({"success":False,"error":"Player not found"},status_code=404)
    query=str(q or "").strip().lstrip("@").lower()
    if len(query)<2: return JSONResponse({"success":True,"players":[]})
    def _search():
        conn=get_db()
        try:
            # Search the exact nickname stored in players.nickname at registration.
            # SQLite LOWER/NOCASE is not fully Unicode-aware for Cyrillic, so do
            # case-insensitive matching in Python with casefold() after reading
            # active players. This keeps @nick and Cyrillic nicknames reliable.
            all_rows=conn.execute("""SELECT id,tg_id,nickname,shop_name,balance,total_earned,total_sales,total_profit,reputation_score
                                     FROM players
                                     WHERE id<>? AND COALESCE(is_banned,0)=0""",(int(pid),)).fetchall()
            qfold=query.casefold()
            def rank_row(r):
                nick=str(r[2] or "")
                nf=nick.casefold()
                return (0 if nf==qfold else 1 if nf.startswith(qfold) else 2, nf)
            rows=[r for r in all_rows if qfold in str(r[2] or "").casefold()]
            rows.sort(key=rank_row)
            rows=rows[:12]
            existing={int(r[0]) for r in conn.execute("SELECT friend_id FROM friends WHERE player_id=?",(int(pid),)).fetchall()}
            out=[]
            for r in rows:
                item={"id":int(r[0]),"tg_id":int(r[1] or 0),"nickname":str(r[2] or "Игрок"),"shop_name":str(r[3] or "Без магазина"),"balance":int(r[4] or 0),"total_earned":int(r[5] or 0),"total_sales":int(r[6] or 0),"total_profit":int(r[7] or 0),"reputation_score":int(r[8] or 0),"is_friend":int(r[0]) in existing}
                item["customization"]=_public_customization_from_conn(conn,int(r[0]),int(r[6] or 0))
                out.append(item)
            return out
        finally: conn.close()
    return JSONResponse({"success":True,"players":await run_sync_db(_search)})


