@app.get("/referrals/{tg_id}")
async def referrals_status(tg_id: int):
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        player_id = await run_sync_db(get_or_create_player, "tg", tg_id)
    if not player_id:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)
    def _status():
        conn = get_db()
        rels = conn.execute("""SELECT r.invitee_tg_id,r.activated_at,r.reward_paid,COALESCE(p.is_banned,0) is_banned,
                                      COALESCE(p.nickname,'Игрок') nickname,COALESCE(p.shop_name,'Без магазина') shop_name,
                                      COALESCE(p.total_sales,0) total_sales,COALESCE(p.total_earned,0) total_earned,
                                      CASE WHEN EXISTS(SELECT 1 FROM friends f JOIN players me ON me.id=f.player_id
                                                       WHERE me.tg_id=? AND f.friend_id=p.id) THEN 1 ELSE 0 END is_friend,
                                      'active' AS referral_state
                               FROM referral_relations r
                               LEFT JOIN players p ON p.tg_id=r.invitee_tg_id
                               WHERE r.inviter_tg_id=?
                               UNION ALL
                               SELECT rp.invitee_tg_id,rp.created_at,0,COALESCE(p.is_banned,0),
                                      COALESCE(p.nickname,'Игрок'),COALESCE(p.shop_name,'Без магазина'),
                                      COALESCE(p.total_sales,0),COALESCE(p.total_earned,0),
                                      CASE WHEN EXISTS(SELECT 1 FROM friends f JOIN players me ON me.id=f.player_id
                                                       WHERE me.tg_id=? AND f.friend_id=p.id) THEN 1 ELSE 0 END,
                                      'pending' AS referral_state
                               FROM referral_pending rp
                               LEFT JOIN players p ON p.tg_id=rp.invitee_tg_id
                               WHERE rp.inviter_tg_id=?
                                 AND NOT EXISTS(SELECT 1 FROM referral_relations rr WHERE rr.invitee_tg_id=rp.invitee_tg_id)
                               ORDER BY activated_at DESC""", (tg_id,tg_id,tg_id,tg_id)).fetchall()
        incoming = conn.execute("SELECT inviter_tg_id FROM referral_relations WHERE invitee_tg_id=?", (tg_id,)).fetchone()
        pending = conn.execute("SELECT inviter_tg_id FROM referral_pending WHERE invitee_tg_id=?", (tg_id,)).fetchone()
        milestone_rows = conn.execute("SELECT target,reward FROM referral_milestones WHERE player_id=? ORDER BY target", (player_id,)).fetchall()
        conn.close()
        return rels, incoming, pending, milestone_rows
    rels, incoming, pending, milestone_rows = await run_sync_db(_status)
    active = len([r for r in rels if int(r["reward_paid"] or 0) == 1 and int(r["is_banned"] or 0) == 0])
    invited_users = [{
        "id": int(r["invitee_tg_id"]), "tg_id": int(r["invitee_tg_id"]),
        "nickname": str(r["nickname"] or "Игрок"),
        "shop_name": str(r["shop_name"] or "Без магазина"),
        "reward_paid": bool(r["reward_paid"]),
        "activated_at": int(r["activated_at"] or 0),
        "total_sales": int(r["total_sales"] or 0),
        "total_earned": int(r["total_earned"] or 0),
        "is_friend": bool(r["is_friend"]),
        "status": str(r["referral_state"] or ("active" if r["reward_paid"] else "pending")),
    } for r in rels if int(r["is_banned"] or 0) == 0]
    inviter_tg = int(incoming["inviter_tg_id"]) if incoming else (int(pending["inviter_tg_id"]) if pending else None)
    inviter = None
    if inviter_tg:
        inviter_player_id = await get_player_id_by_tg(inviter_tg)
        inviter_player = await run_sync_db(get_player_data, inviter_player_id) if inviter_player_id else None
        if inviter_player:
            inviter = {"id": inviter_tg, "nickname": inviter_player.get("nickname", "Друг"), "pending": bool(pending and not incoming)}
    milestone_earned = sum(int(r["reward"] or 0) for r in milestone_rows)
    next_target = next((x["target"] for x in REFERRAL_MILESTONES if x["target"] > active), 0)
    boost_multiplier = 1.0
    for target,mult in REFERRAL_BOOST_TIERS:
        if active>=target: boost_multiplier=mult
        else: break
    title=get_referral_title(active)
    referral_passive_percent = get_referral_passive_percent(active)
    milestones = [{"target":m["target"],"reward":f"+{m['reward']:,} ₽","title":m["title"],"sub":f"{m['target']} активных друзей","extra":f"+{m['reward']:,} ₽"} for m in REFERRAL_MILESTONES]
    return JSONResponse({"success": True, "active": active, "total": len(invited_users), "earned": active * REFERRAL_DIRECT_REWARD + milestone_earned, "pending": 0, "direct_reward": REFERRAL_DIRECT_REWARD, "passive_percent": referral_passive_percent, "passive_days": 0, "boost_multiplier": boost_multiplier, "referral_title": title, "invitee_bonus": REFERRAL_INVITEE_BONUS, "next_target": next_target, "invited_by": inviter, "pending_activation": bool(pending and not incoming), "invite_link": f"https://t.me/{BOT_USERNAME}?start=ref_{tg_id}", "milestones": milestones, "invited_users": invited_users})

