# ==================== R-FARM: REBUILT V2 / SERVER-AUTHORITATIVE ====================
# One round = one server-created session. The server owns time, reward and payout.
# The client only renders the hold and sends START / COMPLETE / CANCEL.
RFARM_VERSION = "v2"
RFARM_DURATION = 30
RFARM_MIN_REWARD = HOLD_REWARD_MIN
RFARM_MAX_REWARD = HOLD_REWARD_MAX


def _rfarm_cycle_key(ts: float) -> str:
    """R-Farm day starts exactly at 12:00 Europe/Moscow (UTC+03:00)."""
    from datetime import datetime, timedelta, timezone
    msk = timezone(timedelta(hours=3))
    dt = datetime.fromtimestamp(float(ts), tz=timezone.utc).astimezone(msk)
    if dt.hour < 12:
        dt -= timedelta(days=1)
    return dt.strftime("%Y-%m-%d")


def _rfarm_next_reset_ts(now: float) -> float:
    from datetime import datetime, timedelta, timezone
    msk = timezone(timedelta(hours=3))
    dt = datetime.fromtimestamp(float(now), tz=timezone.utc).astimezone(msk)
    reset = dt.replace(hour=12, minute=0, second=0, microsecond=0)
    if dt >= reset:
        reset += timedelta(days=1)
    return reset.timestamp()


def _rfarm_ready(last_completed_at: float, now: float) -> bool:
    if not last_completed_at:
        return True
    return _rfarm_cycle_key(now) != _rfarm_cycle_key(last_completed_at)


def _rfarm_reward_at(elapsed: float, duration: float, target_reward: int) -> int:
    duration = max(0.1, float(duration))
    p = max(0.0, min(1.0, float(elapsed) / duration))
    target = max(RFARM_MIN_REWARD, min(RFARM_MAX_REWARD * 8, int(target_reward or RFARM_MIN_REWARD)))
    return int(round(target * p))


def _equipped_rhold_style_sync(conn, player_id: int) -> dict:
    try:
        row = conn.execute(
            "SELECT skin_id FROM rhold_button_skins WHERE player_id=? AND skin_id LIKE 'equipped:rhold:%' ORDER BY purchased_at DESC LIMIT 1",
            (int(player_id),)
        ).fetchone()
        skin_id = str(row[0]).split(":", 2)[2] if row else "era1_core"
    except Exception:
        skin_id = "era1_core"
    skin = _rhold_skin_catalog_map().get(skin_id) or _rhold_skin_catalog_map().get("era1_core") or {}
    mult = max(1.0, float(skin.get("reward_multiplier", 1.0) or 1.0))
    return {
        "id": skin_id,
        "name": str(skin.get("name") or skin_id),
        "accent": str(skin.get("accent") or "#b7ff6a"),
        "multiplier": mult,
        "tier": str(skin.get("tier") or "BASE"),
        "bg": str(skin.get("bg") or ""),
        "border": str(skin.get("border") or ""),
        "glow": str(skin.get("glow") or ""),
        "symbol": str(skin.get("symbol") or "R"),
        "decoration": str(skin.get("decoration") or ""),
    }


def _rfarm_row_sync(player_id: int):
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT player_id,session_id,started_at,last_completed_at,total_claims,target_reward,target_duration,last_completed_session_id,last_reward "
            "FROM hold_sessions WHERE player_id=?", (int(player_id),)
        ).fetchone()
        if row:
            return dict(row)
        return {
            "player_id": int(player_id), "session_id": None, "started_at": 0,
            "last_completed_at": 0, "total_claims": 0, "target_reward": 0,
            "target_duration": RFARM_DURATION, "last_completed_session_id": "", "last_reward": 0,
        }
    finally:
        conn.close()


@app.get("/hold/status/{tg_id}")
async def hold_status(tg_id: int, request: Request):
    if not _verify_hold_and_checkin_request(request, tg_id):
        return JSONResponse({"success": False, "error": "Не найден Telegram ID"}, status_code=401)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)

    now = time_module.time()
    row = await run_sync_db(_rfarm_row_sync, player_id)
    sid = str(row.get("session_id") or "")
    started = float(row.get("started_at") or 0)
    duration = RFARM_DURATION
    elapsed = max(0.0, now - started) if sid and started else 0.0
    progress = max(0.0, min(1.0, elapsed / duration)) if sid else 0.0
    current_reward = _rfarm_reward_at(elapsed, duration, int(row.get("target_reward") or RFARM_MIN_REWARD)) if sid else 0
    last = float(row.get("last_completed_at") or 0)
    ready = (not sid) and _rfarm_ready(last, now)
    reset_ts = _rfarm_next_reset_ts(now)
    cooldown_until = 0.0 if ready else reset_ts
    cooldown_remaining = max(0.0, cooldown_until - now) if cooldown_until else 0.0

    def _style_read():
        conn = get_db()
        try:
            return _equipped_rhold_style_sync(conn, player_id)
        finally:
            conn.close()
    style = await run_sync_db(_style_read)

    return JSONResponse({
        "success": True,
        "version": RFARM_VERSION,
        "server_now": now,
        "cycle_key": _rfarm_cycle_key(now),
        "ready": ready,
        "session_id": sid or None,
        "started_at": started if sid else 0,
        "duration": duration,
        "active_elapsed": elapsed,
        "active_remaining": max(0.0, duration - elapsed) if sid else 0.0,
        "progress": progress,
        "current_reward": current_reward,
        "target_reward": int(row.get("target_reward") or 0) if sid else 0,
        "auto_complete": bool(sid and elapsed >= duration),
        "last_completed_at": last,
        "cooldown_until": cooldown_until,
        "cooldown_remaining": cooldown_remaining,
        "base_reward_min": RFARM_MIN_REWARD,
        "base_reward_max": int(RFARM_MAX_REWARD * float(style.get("multiplier", 1.0) or 1.0)),
        "reward_multiplier": float(style.get("multiplier", 1.0) or 1.0),
        "rhold_style": style,
        "claims": int(row.get("total_claims") or 0),
    })


@app.post("/hold/start/{tg_id}")
async def hold_start(tg_id: int, request: Request):
    if not _verify_hold_and_checkin_request(request, tg_id):
        return JSONResponse({"success": False, "error": "Не найден Telegram ID"}, status_code=401)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)

    now = time_module.time()
    sid = uuid.uuid4().hex

    def _style_read():
        conn = get_db()
        try:
            return _equipped_rhold_style_sync(conn, player_id)
        finally:
            conn.close()
    style = await run_sync_db(_style_read)
    multiplier = max(1.0, float(style.get("multiplier", 1.0) or 1.0))
    target_reward = int(round(random.randint(RFARM_MIN_REWARD, RFARM_MAX_REWARD) * multiplier))

    lock = player_action_locks.setdefault(f"rfarm:{player_id}", asyncio.Lock())
    async with lock:
        async with db_lock:
            def _start():
                conn = get_db(); cur = conn.cursor()
                try:
                    cur.execute("BEGIN IMMEDIATE")
                    row = cur.execute(
                        "SELECT session_id,last_completed_at,total_claims FROM hold_sessions WHERE player_id=?",
                        (player_id,)
                    ).fetchone()
                    if row and row["session_id"]:
                        conn.rollback(); return ("active", str(row["session_id"]))
                    last = float(row["last_completed_at"] or 0) if row else 0.0
                    if not _rfarm_ready(last, now):
                        conn.rollback(); return ("cooldown", _rfarm_next_reset_ts(now))

                    cur.execute("""
                        INSERT INTO hold_sessions(
                            player_id,session_id,started_at,last_completed_at,total_claims,
                            target_reward,target_duration,last_completed_session_id,last_reward
                        ) VALUES(?,?,?,?,?,?,?,?,?)
                        ON CONFLICT(player_id) DO UPDATE SET
                            session_id=excluded.session_id,
                            started_at=excluded.started_at,
                            target_reward=excluded.target_reward,
                            target_duration=excluded.target_duration
                    """, (player_id, sid, now, last, int(row["total_claims"] if row else 0),
                          target_reward, RFARM_DURATION, "", 0))
                    conn.commit()
                    return ("started", sid)
                except Exception:
                    conn.rollback(); raise
                finally:
                    conn.close()
            result = await run_sync_db(_start)

    if result[0] == "active":
        return JSONResponse({"success": False, "error": "R-Farm уже запущен", "session_id": result[1]}, status_code=409)
    if result[0] == "cooldown":
        return JSONResponse({
            "success": False,
            "error": "R-Farm уже использован в этом цикле",
            "cooldown_until": result[1],
            "cooldown_remaining": max(0.0, float(result[1]) - now),
        }, status_code=429)

    return JSONResponse({
        "success": True,
        "version": RFARM_VERSION,
        "session_id": sid,
        "started_at": now,
        "server_now": now,
        "duration": RFARM_DURATION,
        "target_reward": target_reward,
        "reward_multiplier": multiplier,
        "cycle_key": _rfarm_cycle_key(now),
    })


@app.post("/hold/cancel/{tg_id}")
async def hold_cancel(tg_id: int, request: Request):
    if not _verify_hold_and_checkin_request(request, tg_id):
        return JSONResponse({"success": False, "error": "Не найден Telegram ID"}, status_code=401)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)
    try:
        data = await request.json()
    except Exception:
        data = {}
    sid = str(data.get("session_id") or "")
    if not sid:
        return JSONResponse({"success": False, "error": "session_id обязателен"}, status_code=400)

    lock = player_action_locks.setdefault(f"rfarm:{player_id}", asyncio.Lock())
    async with lock:
        async with db_lock:
            def _cancel():
                conn = get_db(); cur = conn.cursor()
                try:
                    cur.execute("BEGIN IMMEDIATE")
                    cur.execute(
                        "UPDATE hold_sessions SET session_id=NULL,started_at=0,target_reward=0,target_duration=? "
                        "WHERE player_id=? AND session_id=?",
                        (RFARM_DURATION, player_id, sid)
                    )
                    changed = cur.rowcount
                    conn.commit()
                    return changed
                except Exception:
                    conn.rollback(); raise
                finally:
                    conn.close()
            changed = await run_sync_db(_cancel)
    return JSONResponse({"success": True, "cancelled": bool(changed), "session_id": sid})


@app.post("/hold/complete/{tg_id}")
async def hold_complete(tg_id: int, request: Request):
    if not _verify_hold_and_checkin_request(request, tg_id):
        return JSONResponse({"success": False, "error": "Не найден Telegram ID"}, status_code=401)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)
    try:
        data = await request.json()
    except Exception:
        data = {}
    sid = str(data.get("session_id") or "")
    if not sid:
        return JSONResponse({"success": False, "error": "session_id обязателен"}, status_code=400)

    now = time_module.time()
    lock = player_action_locks.setdefault(f"rfarm:{player_id}", asyncio.Lock())
    async with lock:
        async with db_lock:
            def _complete():
                conn = get_db(); cur = conn.cursor()
                try:
                    cur.execute("BEGIN IMMEDIATE")
                    row = cur.execute(
                        "SELECT session_id,started_at,last_completed_at,total_claims,target_reward,target_duration,last_completed_session_id,last_reward "
                        "FROM hold_sessions WHERE player_id=?", (player_id,)
                    ).fetchone()
                    if not row:
                        conn.rollback(); return ("invalid",)

                    # Idempotent replay: if Telegram/network lost the success response,
                    # repeating COMPLETE with the same session id returns the same payout.
                    if str(row["last_completed_session_id"] or "") == sid:
                        bal = cur.execute("SELECT balance FROM players WHERE id=?", (player_id,)).fetchone()
                        conn.rollback()
                        return ("replay", int(row["last_reward"] or 0), int(bal["balance"] if bal else 0), float(row["last_completed_at"] or 0))

                    if str(row["session_id"] or "") != sid:
                        conn.rollback(); return ("invalid",)

                    last = float(row["last_completed_at"] or 0)
                    if not _rfarm_ready(last, now):
                        conn.rollback(); return ("cooldown",)

                    started = float(row["started_at"] or 0)
                    duration = RFARM_DURATION
                    elapsed = max(0.0, now - started)
                    remaining = duration - elapsed
                    if remaining > 0:
                        conn.rollback(); return ("too_early", max(0.05, remaining))

                    reward = _rfarm_reward_at(duration, duration, int(row["target_reward"] or RFARM_MIN_REWARD))
                    cur.execute(
                        "UPDATE players SET balance=balance+?,total_earned=total_earned+? WHERE id=?",
                        (reward, reward, player_id)
                    )
                    cur.execute("""
                        UPDATE hold_sessions SET
                            session_id=NULL,started_at=0,last_completed_at=?,total_claims=total_claims+1,
                            target_reward=0,target_duration=?,last_completed_session_id=?,last_reward=?
                        WHERE player_id=? AND session_id=?
                    """, (now, RFARM_DURATION, sid, reward, player_id, sid))
                    bal = cur.execute("SELECT balance FROM players WHERE id=?", (player_id,)).fetchone()
                    conn.commit()
                    return ("ok", reward, int(bal["balance"] if bal else 0), elapsed)
                except Exception:
                    conn.rollback(); raise
                finally:
                    conn.close()
            result = await run_sync_db(_complete)

    if result[0] == "invalid":
        return JSONResponse({"success": False, "error": "Сессия не найдена или уже отменена"}, status_code=409)
    if result[0] == "cooldown":
        return JSONResponse({"success": False, "error": "R-Farm уже использован в этом цикле"}, status_code=429)
    if result[0] == "too_early":
        remaining = float(result[1])
        return JSONResponse({
            "success": False,
            "error": f"R-Farm ещё выполняется. Осталось {remaining:.2f} сек.",
            "remaining": remaining,
            "retry_after": remaining,
            "server_now": now,
        }, status_code=409)

    if result[0] == "replay":
        reward, balance, completed_at = result[1], result[2], result[3]
        reset_ts = _rfarm_next_reset_ts(now)
        return JSONResponse({
            "success": True, "version": RFARM_VERSION, "idempotent": True,
            "reward": reward, "balance": balance, "elapsed": RFARM_DURATION,
            "duration": RFARM_DURATION, "server_now": now,
            "cooldown_until": reset_ts, "cooldown_remaining": max(0.0, reset_ts-now),
            "cycle_key": _rfarm_cycle_key(now), "completed_at": completed_at,
        })

    reward, balance, elapsed = result[1], result[2], result[3]
    # Optional side effects must never turn a successful payout into an error.
    for _side_effect in (
        lambda: run_sync_db(update_daily_quest, player_id, "farm_once", 1),
        lambda: run_sync_db(_engagement_add_xp_sync, player_id, 20, "farm_complete"),
    ):
        try:
            await _side_effect()
        except Exception:
            pass
    try:
        await activate_pending_referral(int(tg_id), "hold_complete")
    except Exception:
        pass

    reset_ts = _rfarm_next_reset_ts(now)
    return JSONResponse({
        "success": True, "version": RFARM_VERSION, "idempotent": False,
        "reward": reward, "balance": balance, "elapsed": elapsed,
        "duration": RFARM_DURATION, "server_now": now,
        "cooldown_until": reset_ts, "cooldown_remaining": max(0.0, reset_ts-now),
        "cycle_key": _rfarm_cycle_key(now),
    })


# ==================== PRIVATE ADMIN API ====================
def _admin_inventory_item_label(item):
    """Return a human-readable inventory label while preserving the raw item for audit."""
    if isinstance(item, str):
        raw=item
        obj={"id":item}
    elif isinstance(item, dict):
        obj=item
        raw=str(item.get("id") or item.get("item_id") or item.get("code") or item.get("name") or "Предмет")
    else:
        return str(item)
    name=obj.get("name") or obj.get("title") or obj.get("label")
    if name:
        return str(name)
    wanted=str(obj.get("id") or obj.get("item_id") or obj.get("code") or raw)
    for source in (AVITO_FOUND_DROPS, RESSELL_DROP_CATALOG, RESSELL_COLLECTIBLE_CATALOG, RESSELL_EMPIRE_CATALOG, RESSELL_BLACK_MARKET_POOL, RESSELL_COLLECTOR_CARS):
        for entry in source:
            if str(entry.get("id"))==wanted or str(entry.get("found_id"))==wanted:
                return str(entry.get("name") or wanted)
    return wanted


def _admin_nightclub_value_from_row(row):
    if not row or int(row.get("level",0) or 0)<=0:
        return 0
    levels={int(x.get("level",0)):int(x.get("price",0) or 0) for x in NIGHT_CLUB_LEVELS}
    styles={str(x.get("id")):int(x.get("price",0) or 0) for x in NIGHT_CLUB_STYLES}
    level=int(row.get("level",0) or 0)
    style=str(row.get("venue_style") or "afterdark")
    artists=max(0,int(row.get("artist_count",0) or 0))
    security=max(0,int(row.get("security_level",0) or 0))
    return levels.get(level,0)+styles.get(style,0)+8_000_000*artists*(artists+1)//2+sum(20_000_000+15_000_000*i for i in range(security))


def _admin_asset_snapshot_sync(player_id:int):
    conn=get_db()
    try:
        p=conn.execute("SELECT id,tg_id,balance,house,car_collection,current_car,inventory,skin,skin_inventory,taxopark,trading_invested FROM players WHERE id=?",(int(player_id),)).fetchone()
        if not p: return None
        out={"balance":int(p["balance"] or 0),"house":None,"cars":[],"businesses":[],"taxopark":[],"mining":[],"market_assets":[],"deposits":[],"stocks":[],"skins":[],"rhold_skins":[],"container_items":[],"inventory":[],"nightclub":None}
        house_id=str(p["house"] or "room")
        house=next((h for h in HOUSES if str(h.get("id"))==house_id),None)
        if house_id!="room" and house: out["house"]={"id":house_id,"name":house.get("name"),"price":int(house.get("price",0))}
        try: owned=json.loads(p["car_collection"] or "[]")
        except Exception: owned=[]
        for idx,cid in enumerate(owned):
            c=next((x for x in CARS if x.get("id")==cid),None)
            out["cars"].append({"index":idx,"id":str(cid),"name":c.get("name",cid) if c else str(cid),"price":int(c.get("price",0)) if c else 0,"current":str(p["current_car"] or "none")==str(cid)})
        try: inv=json.loads(p["inventory"] or "[]")
        except Exception: inv=[]
        if isinstance(inv,list):
            for idx,item in enumerate(inv):
                out["inventory"].append({"index":idx,"item":item,"label":_admin_inventory_item_label(item)})
        try: tax=json.loads(p["taxopark"] or '{}')
        except Exception: tax={}
        out["taxopark_state"]={"level":tax.get("level","none"),"cars":tax.get("cars",[])}
        shop_cols={str(row[1]) for row in conn.execute("PRAGMA table_info(user_shops)").fetchall()}
        shop_purchase_ts = "purchased_at" if "purchased_at" in shop_cols else ("purchase_time AS purchased_at" if "purchase_time" in shop_cols else "NULL AS purchased_at")
        shop_last_payment = "last_payment" if "last_payment" in shop_cols else "0 AS last_payment"
        shop_paid_until = "paid_until" if "paid_until" in shop_cols else ("maintenance_paid_until AS paid_until" if "maintenance_paid_until" in shop_cols else "0 AS paid_until")
        shop_status = "status" if "status" in shop_cols else "'active' AS status"
        shop_purchase_price = "purchase_price" if "purchase_price" in shop_cols else "0 AS purchase_price"
        rows=conn.execute(f"SELECT id,shop_id,{shop_purchase_price},{shop_purchase_ts},{shop_last_payment},{shop_paid_until},{shop_status} FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id DESC",(int(player_id),)).fetchall()
        for r in rows:
            shop=next((x for x in SHOP_LEVELS if str(x.get('id'))==str(r['shop_id'])),None)
            out["businesses"].append({"row_id":int(r['id']),"id":str(r['shop_id']),"name":shop.get('name',r['shop_id']) if shop else str(r['shop_id']),"purchase_price":int(r['purchase_price'] or 0),"catalog_price":int(shop.get('price',0) or 0) if shop else 0,"purchased_at":r['purchased_at'],"status":str(r['status'] or 'active')})
        club=conn.execute("SELECT player_id,level,venue_style,pending_income,total_income,last_tick_at,guest_count,reputation,artist_count,security_level,reservation_count FROM night_clubs WHERE player_id=? AND level>0",(int(player_id),)).fetchone()
        if club:
            cr=dict(club); cr["row_id"]=int(player_id); cr["id"]=str(player_id); cr["value"]=_admin_nightclub_value_from_row(cr); cr["name"]="Ночной клуб"; out["nightclub"]=cr
        rows=conn.execute("SELECT id,level_id,purchase_price,status,paid_until FROM user_taxoparks WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id DESC",(int(player_id),)).fetchall()
        for r in rows: out["taxopark"].append({"row_id":int(r['id']),"level_id":str(r['level_id']),"purchase_price":int(r['purchase_price'] or 0),"status":str(r['status'] or '')})
        rows=conn.execute("SELECT id,rig_type,daily_income,price,purchase_time,status FROM mining_rigs WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id DESC",(int(player_id),)).fetchall()
        for r in rows: out["mining"].append({"row_id":int(r['id']),"rig_type":str(r['rig_type']),"daily_income":int(r['daily_income'] or 0),"price":int(r['price'] or 0),"purchase_time":r['purchase_time'],"status":str(r['status'] or '')})
        rows=conn.execute("SELECT asset_id,purchased_at FROM resell_market_assets WHERE player_id=? ORDER BY purchased_at DESC",(int(player_id),)).fetchall()
        for r in rows: out["market_assets"].append({"id":str(r['asset_id']),"purchased_at":r['purchased_at']})
        rows=conn.execute("SELECT id,amount,start_time,duration_days,interest_rate,status FROM deposits WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id DESC",(int(player_id),)).fetchall()
        for r in rows: out["deposits"].append({"row_id":int(r['id']),"amount":int(r['amount'] or 0),"start_time":r['start_time'],"duration_days":int(r['duration_days'] or 0),"interest_rate":float(r['interest_rate'] or 0),"status":str(r['status'] or '')})
        rows=conn.execute("SELECT id,symbol,quantity,avg_buy_price FROM user_stocks WHERE player_id=? AND quantity>0 ORDER BY id DESC",(int(player_id),)).fetchall()
        for r in rows: out["stocks"].append({"row_id":int(r['id']),"symbol":str(r['symbol']),"quantity":int(r['quantity'] or 0),"avg_buy_price":int(r['avg_buy_price'] or 0)})
        rows=conn.execute("SELECT id,skin_id,equipped FROM skins WHERE player_id=? ORDER BY id DESC",(int(player_id),)).fetchall()
        for r in rows: out["skins"].append({"row_id":int(r['id']),"skin_id":str(r['skin_id']),"equipped":int(r['equipped'] or 0)})
        rows=conn.execute("SELECT skin_id,purchased_at FROM rhold_button_skins WHERE player_id=? AND skin_id NOT LIKE 'equipped:%' ORDER BY purchased_at DESC",(int(player_id),)).fetchall()
        for r in rows: out["rhold_skins"].append({"id":str(r['skin_id']),"purchased_at":r['purchased_at']})
        try:
            rows=conn.execute("SELECT id,name,rarity,value,sold,purchase_id,created_at FROM container_inventory WHERE player_id=? AND COALESCE(sold,0)=0 ORDER BY created_at DESC",(int(player_id),)).fetchall()
            for r in rows: out["container_items"].append({"id":str(r['id']),"name":str(r['name']),"rarity":str(r['rarity']),"value":int(r['value'] or 0),"sold":int(r['sold'] or 0),"purchase_id":str(r['purchase_id']),"created_at":r['created_at']})
        except Exception: pass
        return out
    finally: conn.close()


def _admin_wealth_breakdown_sync(player_id:int):
    """Reproduce the public wealth formula for one player, with auditable components."""
    conn=get_db()
    try:
        p=conn.execute("SELECT id,balance,inventory,car_collection,house,property_purchase_value,trading_invested FROM players WHERE id=?",(int(player_id),)).fetchone()
        if not p: return None
        def parse_json(raw, default):
            try: return json.loads(raw) if isinstance(raw,str) else (raw if raw is not None else default)
            except Exception: return default
        shop_catalog={str(x.get('id')):int(x.get('price',0) or 0) for x in SHOP_LEVELS}
        car_catalog={str(x.get('id')):int(x.get('price',0) or 0) for x in CARS}
        house_catalog={str(x.get('id')):int(x.get('price',0) or 0) for x in HOUSES}
        taxi_catalog={str(x.get('id')):int(x.get('price',0) or 0) for x in TAXOPARK_LEVELS}
        mining_catalog={}
        for r in conn.execute("SELECT rig_type,MAX(price) AS price FROM mining_rigs GROUP BY rig_type").fetchall(): mining_catalog[str(r[0])]=int(r[1] or 0)
        market_catalog={str(x.get('id')):int(x.get('price',0) or 0) for x in (RESSELL_EMPIRE_CATALOG+RESSELL_COLLECTIBLE_CATALOG+RESSELL_BLACK_MARKET_POOL+RESSELL_COLLECTOR_CARS+RESSELL_DROP_CATALOG)}
        stock_prices={str(r[0]):int(r[1] or 0) for r in conn.execute("SELECT symbol,price FROM stock_prices").fetchall()}
        deposits=int(conn.execute("SELECT COALESCE(SUM(amount),0) FROM deposits WHERE player_id=? AND status='active'",(int(player_id),)).fetchone()[0] or 0)
        shops=sum(max(int(r[1] or 0),shop_catalog.get(str(r[0]),0)) for r in conn.execute("SELECT shop_id,purchase_price FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active'",(int(player_id),)).fetchall())
        taxi=sum(max(int(r[1] or 0),taxi_catalog.get(str(r[0]),0)) for r in conn.execute("SELECT level_id,purchase_price FROM user_taxoparks WHERE player_id=? AND status='active'",(int(player_id),)).fetchall())
        mining=sum(max(int(r[1] or 0),mining_catalog.get(str(r[0]),0)) for r in conn.execute("SELECT rig_type,price FROM mining_rigs WHERE player_id=? AND status='active'",(int(player_id),)).fetchall())
        stocks=sum(max(0,int(r[1] or 0))*stock_prices.get(str(r[0]),max(0,int(r[2] or 0))) for r in conn.execute("SELECT symbol,quantity,avg_buy_price FROM user_stocks WHERE player_id=? AND quantity>0",(int(player_id),)).fetchall())
        market=sum(market_catalog.get(str(r[0]),0) for r in conn.execute("SELECT asset_id FROM resell_market_assets WHERE player_id=?",(int(player_id),)).fetchall())
        club_row=conn.execute("SELECT level,venue_style,artist_count,security_level FROM night_clubs WHERE player_id=? AND level>0",(int(player_id),)).fetchone()
        club=_admin_nightclub_value_from_row(dict(club_row) if club_row else None)
        inventory=parse_json(p['inventory'],[]); inventory_value=sum(max(0,int(x.get('market_price',x.get('buy_price',x.get('value',0))) or 0)) for x in inventory if isinstance(x,dict)) if isinstance(inventory,list) else 0
        try: inventory_value += sum(max(0,int(r[0] or 0)) for r in conn.execute("SELECT value FROM container_inventory WHERE player_id=? AND COALESCE(sold,0)=0",(int(player_id),)).fetchall())
        except Exception: pass
        collection=parse_json(p['car_collection'],[]); collection=collection if isinstance(collection,list) else []
        cars=sum(car_catalog.get(str(cid),0) for cid in collection)
        house=int(p['property_purchase_value'] or PROPERTY_LEGACY_PURCHASE_PRICES.get(str(p['house'] or 'room'),0))
        trading=max(0,int(p['trading_invested'] or 0))
        debt=sum(max(0,int(r[0] or 0)-int(r[1] or 0)) for r in conn.execute("SELECT amount,paid_amount FROM loans WHERE player_id=? AND status IN ('active','overdue')",(int(player_id),)).fetchall())
        balance=int(p['balance'] or 0)
        gross=balance+deposits+inventory_value+cars+house+shops+taxi+mining+stocks+market+club+trading
        return {"balance":balance,"deposits":deposits,"inventory":inventory_value,"cars":cars,"house":house,"businesses":shops,"taxi":taxi,"mining":mining,"stocks":stocks,"market_assets":market,"nightclub":club,"trading":trading,"debt":debt,"gross_wealth":gross,"net_wealth":max(0,gross-debt)}
    finally: conn.close()

def _admin_remove_asset_sync(player_id:int, asset_type:str, asset_id:str):
    conn=get_db(); cur=conn.cursor(); now=int(time_module.time())
    try:
        cur.execute("BEGIN IMMEDIATE")
        if asset_type=="business":
            row=cur.execute("SELECT shop_id FROM user_shops WHERE id=? AND player_id=? AND COALESCE(status,'active')='active'",(int(asset_id),player_id)).fetchone()
            if not row: return (False,"Бизнес не найден")
            cur.execute("UPDATE user_shops SET status='confiscated' WHERE id=? AND player_id=? AND COALESCE(status,'active')='active'",(int(asset_id),player_id))
            if cur.rowcount != 1: return (False,"Бизнес уже забран")
            label=f"business:{row['shop_id']}#{asset_id}"
        elif asset_type=="car":
            row=cur.execute("SELECT car_collection,current_car FROM players WHERE id=?",(player_id,)).fetchone()
            if not row: return (False,"Игрок не найден")
            try: cars=json.loads(row['car_collection'] or '[]')
            except Exception: cars=[]
            if not isinstance(cars,list): cars=[]
            idx=int(asset_id)
            if idx<0 or idx>=len(cars): return (False,"Машина уже забрана или не найдена")
            removed=str(cars[idx]); cars.pop(idx)
            current=str(row['current_car'] or 'none')
            new_current='none' if current==removed and removed not in cars else current
            cur.execute("UPDATE players SET car_collection=?,current_car=? WHERE id=?",(json.dumps(cars,ensure_ascii=False),new_current,player_id))
            label=f"car:{removed}#{idx}"
        elif asset_type=="house":
            row=cur.execute("SELECT house FROM players WHERE id=?",(player_id,)).fetchone(); hid=str(row['house'] if row else 'room')
            if not row or hid=='room': return (False,"Недвижимость отсутствует")
            cur.execute("UPDATE players SET house='room' WHERE id=? AND house=?",(player_id,hid)); label=f"house:{hid}"
        elif asset_type=="nightclub":
            row=cur.execute("SELECT level,venue_style,artist_count,security_level FROM night_clubs WHERE player_id=? AND level>0",(player_id,)).fetchone()
            if not row: return (False,"Ночной клуб не найден")
            cur.execute("DELETE FROM night_clubs WHERE player_id=? AND level>0",(player_id,))
            if cur.rowcount != 1: return (False,"Ночной клуб уже забран")
            label=f"nightclub:level={int(row['level'] or 0)}:style={row['venue_style']}"
        elif asset_type=="taxopark":
            row=cur.execute("SELECT level_id FROM user_taxoparks WHERE id=? AND player_id=? AND status='active'",(int(asset_id),player_id)).fetchone()
            if not row: return (False,"Таксопарк не найден")
            cur.execute("UPDATE user_taxoparks SET status='confiscated' WHERE id=? AND player_id=? AND status='active'",(int(asset_id),player_id))
            # Also clear the player's JSON taxopark if it refers to the same level.
            prow=cur.execute("SELECT taxopark FROM players WHERE id=?",(player_id,)).fetchone()
            try: tax=json.loads(prow['taxopark'] or '{}') if prow else {}
            except Exception: tax={}
            if str(tax.get('level','none'))==str(row['level_id']):
                tax['level']='none'; tax['cars']=[]; tax['car_instance_indices']=[]; tax['pending_carry']=0
                cur.execute("UPDATE players SET taxopark=?,garage_car_stats='[]' WHERE id=?",(json.dumps(tax,ensure_ascii=False),player_id))
            try: cur.execute("DELETE FROM taxi_vehicle_state WHERE player_id=?",(player_id,))
            except Exception: pass
            label=f"taxopark:{row['level_id']}#{asset_id}"
        elif asset_type=="mining":
            row=cur.execute("SELECT rig_type FROM mining_rigs WHERE id=? AND player_id=? AND status='active'",(int(asset_id),player_id)).fetchone()
            if not row: return (False,"Майнинг-ферма не найдена")
            cur.execute("UPDATE mining_rigs SET status='confiscated' WHERE id=? AND player_id=? AND status='active'",(int(asset_id),player_id))
            if cur.rowcount != 1: return (False,"Майнинг-ферма уже забрана")
            label=f"mining:{row['rig_type']}#{asset_id}"
        elif asset_type=="market_asset":
            row=cur.execute("SELECT asset_id FROM resell_market_assets WHERE player_id=? AND asset_id=?",(player_id,str(asset_id))).fetchone()
            if not row: return (False,"Market-актив не найден")
            cur.execute("DELETE FROM resell_market_assets WHERE player_id=? AND asset_id=?",(player_id,str(asset_id))); label=f"market_asset:{asset_id}"
        elif asset_type=="deposit":
            row=cur.execute("SELECT amount,status FROM deposits WHERE id=? AND player_id=?",(int(asset_id),player_id)).fetchone()
            if not row or str(row['status'])!='active': return (False,"Активный депозит не найден")
            cur.execute("UPDATE deposits SET status='confiscated' WHERE id=? AND player_id=? AND status='active'",(int(asset_id),player_id))
            if cur.rowcount != 1: return (False,"Депозит уже забран")
            label=f"deposit:{asset_id}:{int(row['amount'] or 0)}"
        elif asset_type=="stock":
            row=cur.execute("SELECT symbol,quantity FROM user_stocks WHERE id=? AND player_id=? AND quantity>0",(int(asset_id),player_id)).fetchone()
            if not row: return (False,"Позиция акции не найдена")
            cur.execute("UPDATE user_stocks SET quantity=0 WHERE id=? AND player_id=?",(int(asset_id),player_id)); label=f"stock:{row['symbol']}#{asset_id} qty={int(row['quantity'] or 0)}"
        elif asset_type=="skin":
            row=cur.execute("SELECT skin_id FROM skins WHERE id=? AND player_id=?",(int(asset_id),player_id)).fetchone()
            if not row: return (False,"Скин не найден")
            cur.execute("DELETE FROM skins WHERE id=? AND player_id=?",(int(asset_id),player_id)); label=f"skin:{row['skin_id']}#{asset_id}"
        elif asset_type=="rhold_skin":
            row=cur.execute("SELECT skin_id FROM rhold_button_skins WHERE player_id=? AND skin_id=? AND skin_id NOT LIKE 'equipped:%'",(player_id,str(asset_id))).fetchone()
            if not row: return (False,"R-HOLD скин не найден")
            cur.execute("DELETE FROM rhold_button_skins WHERE player_id=? AND skin_id=?",(player_id,str(asset_id))); label=f"rhold_skin:{asset_id}"
        elif asset_type=="container_item":
            row=cur.execute("SELECT name,value,sold FROM container_inventory WHERE id=? AND player_id=?",(str(asset_id),player_id)).fetchone()
            if not row or int(row['sold'] or 0): return (False,"Контейнерный предмет не найден или уже продан")
            cur.execute("UPDATE container_inventory SET sold=1,sold_at=? WHERE id=? AND player_id=? AND sold=0",(now,str(asset_id),player_id)); label=f"container_item:{row['name']}#{asset_id} value={int(row['value'] or 0)}"
        elif asset_type=="inventory":
            row=cur.execute("SELECT inventory FROM players WHERE id=?",(player_id,)).fetchone()
            if not row: return (False,"Игрок не найден")
            inv=json.loads(row['inventory'] or '[]'); idx=int(asset_id)
            if not isinstance(inv,list) or idx<0 or idx>=len(inv): return (False,"Предмет инвентаря не найден")
            removed=inv.pop(idx); cur.execute("UPDATE players SET inventory=? WHERE id=?",(json.dumps(inv,ensure_ascii=False),player_id)); label=f"inventory:{json.dumps(removed,ensure_ascii=False)[:300]}#{idx}"
        else:
            return (False,"Неизвестный тип актива")
        conn.commit(); return (True,label)
    except Exception:
        conn.rollback(); raise
    finally: conn.close()

