def _admin_economy_detail_sync(player_id:int, target_tg_id:int):
    """Build a single authoritative admin snapshot of a player's economy."""
    conn=get_db()
    try:
        p=conn.execute("SELECT tg_id,balance,total_earned,total_profit,total_sales,items_sold,created_at,current_car,house,taxopark FROM players WHERE id=?",(int(player_id),)).fetchone()
        if not p: return None
        now=int(time_module.time())
        # players.created_at is a SQLite TIMESTAMP and older rows may contain
        # strings like "2026-09-15 07:55:37" rather than Unix timestamps.
        # Normalize it here so the admin economy panel can never crash on a
        # legacy/SQLite-created player row.
        def _safe_timestamp(value):
            if value is None:
                return 0
            try:
                return int(value)
            except (TypeError, ValueError):
                try:
                    from datetime import datetime as _dt
                    text=str(value).strip()
                    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f"):
                        try:
                            return int(_dt.strptime(text,fmt).timestamp())
                        except ValueError:
                            pass
                except Exception:
                    pass
                return 0
        # Current hourly income is the same server-authoritative calculation used by the game.
        hourly, breakdown=get_hourly_income(int(player_id), include_referrals=True)
        hourly_no_refs, breakdown_no_refs=get_hourly_income(int(player_id), include_referrals=False)
        levels=get_upgrade_state(int(player_id))
        upgrades=[]; upgrade_passive=0; upgrade_spent=0
        for key,cfg in UPGRADE_CARDS.items():
            level=int(levels.get(key,0)); costs=list(cfg.get("costs",[]))
            spent=sum(int(x) for x in costs[:level])
            passive=level*int(cfg.get("income_per_level",0))
            upgrade_passive += passive; upgrade_spent += spent
            upgrades.append({
                "id":key,"name":cfg.get("name"),"icon":cfg.get("icon"),"level":level,
                "max_level":len(costs),"next_cost":(int(costs[level]) if level<len(costs) else None),
                "income_per_level":int(cfg.get("income_per_level",0)),
                "hold_bonus_per_level":int(cfg.get("hold_bonus_per_level",0)),
                "passive_income":passive,"spent":spent
            })
        # Referral network: enough detail for an admin to trace the source of passive referral income.
        refs=conn.execute("""SELECT r.invitee_tg_id,r.activated_at,p.nickname,p.balance,p.total_earned,p.is_banned
            FROM referral_relations r LEFT JOIN players p ON p.tg_id=r.invitee_tg_id
            WHERE r.inviter_tg_id=? AND r.reward_paid=1 ORDER BY r.activated_at ASC""",(int(target_tg_id),)).fetchall()
        referral_rows=[]
        for r in refs:
            ipid=conn.execute("SELECT id FROM players WHERE tg_id=?",(int(r["invitee_tg_id"]),)).fetchone()
            ih=0
            if ipid:
                try: ih=int(get_hourly_income(int(ipid[0]),include_referrals=False)[0])
                except Exception: ih=0
            referral_rows.append({"tg_id":int(r["invitee_tg_id"]),"nickname":str(r["nickname"] or "Без никнейма"),"balance":int(r["balance"] or 0),"total_earned":int(r["total_earned"] or 0),"is_banned":bool(r["is_banned"] or 0),"activated_at":int(r["activated_at"] or 0),"hourly_income":ih})
        pos1=int(conn.execute("SELECT COALESCE(SUM(CASE WHEN balance_delta>0 THEN balance_delta ELSE 0 END),0) FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND created_at>=?",(int(target_tg_id),now-3600)).fetchone()[0] or 0)
        neg1=int(conn.execute("SELECT COALESCE(SUM(CASE WHEN balance_delta<0 THEN balance_delta ELSE 0 END),0) FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND created_at>=?",(int(target_tg_id),now-3600)).fetchone()[0] or 0)
        pos24=int(conn.execute("SELECT COALESCE(SUM(CASE WHEN balance_delta>0 THEN balance_delta ELSE 0 END),0) FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND created_at>=?",(int(target_tg_id),now-86400)).fetchone()[0] or 0)
        neg24=int(conn.execute("SELECT COALESCE(SUM(CASE WHEN balance_delta<0 THEN balance_delta ELSE 0 END),0) FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND created_at>=?",(int(target_tg_id),now-86400)).fetchone()[0] or 0)
        largest=conn.execute("SELECT id,created_at,balance_delta,before_balance,after_balance FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND balance_delta>0 ORDER BY balance_delta DESC,id DESC LIMIT 10",(int(target_tg_id),)).fetchall()
        return {
            "hourly_income":int(hourly),"hourly_income_without_referrals":int(hourly_no_refs),
            "daily_income":int(hourly*24),"breakdown":{k:int(v) for k,v in breakdown.items()},
            "breakdown_without_referrals":{k:int(v) for k,v in breakdown_no_refs.items()},
            "referral_multiplier":float(get_referral_boost_multiplier(int(player_id))),
            "referral_passive_percent":float(get_referral_passive_percent(len(referral_rows))),
            "upgrade_income":int(upgrade_passive),"upgrade_spent":int(upgrade_spent),"upgrades":upgrades,
            "referrals":referral_rows,"referral_count":len(referral_rows),
            "money_flow_1h":{"positive":pos1,"negative":neg1,"net":pos1+neg1},
            "money_flow_24h":{"positive":pos24,"negative":neg24,"net":pos24+neg24},
            "largest_positive_changes":[dict(x) for x in largest],
            "balance":int(p["balance"] or 0),"total_earned":int(p["total_earned"] or 0),
            "created_at":_safe_timestamp(p["created_at"]),"current_car":str(p["current_car"] or "none"),
            "house":str(p["house"] or "room"),"taxopark":p["taxopark"]
        }
    finally: conn.close()

def _economy_alert_candidates_sync():
    """Return players whose recent positive balance flow is materially above their expected income."""
    conn=get_db(); now=int(time_module.time())
    try:
        rows=conn.execute("""SELECT p.id,p.tg_id,p.balance,
            COALESCE(SUM(CASE WHEN a.balance_delta>0 THEN a.balance_delta ELSE 0 END),0) pos1,
            COALESCE(SUM(CASE WHEN a.balance_delta<0 THEN a.balance_delta ELSE 0 END),0) neg1,
            COALESCE(SUM(CASE WHEN a.balance_delta>0 THEN a.balance_delta ELSE 0 END),0) pos24
            FROM players p LEFT JOIN audit_logs a ON a.target_tg_id=p.tg_id AND a.action='balance_change' AND a.created_at>=?
            GROUP BY p.id HAVING pos1>=? OR pos24>=?""",(now-86400,20_000_000,100_000_000)).fetchall()
        out=[]
        for r in rows:
            # Recompute the 1h window separately because the aggregate above covers 24h.
            pos1=int(conn.execute("SELECT COALESCE(SUM(CASE WHEN balance_delta>0 THEN balance_delta ELSE 0 END),0) FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND created_at>=?",(int(r["tg_id"]),now-3600)).fetchone()[0] or 0)
            neg1=int(conn.execute("SELECT COALESCE(SUM(CASE WHEN balance_delta<0 THEN balance_delta ELSE 0 END),0) FROM audit_logs WHERE target_tg_id=? AND action='balance_change' AND created_at>=?",(int(r["tg_id"]),now-3600)).fetchone()[0] or 0)
            pos24=int(r["pos24"] or 0)
            latest=conn.execute("SELECT id,created_at,balance_delta,path,details FROM audit_logs WHERE target_tg_id=? AND action='balance_change' ORDER BY id DESC LIMIT 1",(int(r["tg_id"]),)).fetchone()
            out.append({"player_id":int(r["id"]),"tg_id":int(r["tg_id"]),"balance":int(r["balance"] or 0),"pos1":pos1,"neg1":neg1,"pos24":pos24,"latest":dict(latest) if latest else {}})
        return out
    finally: conn.close()

def _economy_alert_create_sync(c):
    now=int(time_module.time()); pid=int(c["player_id"]); tg=int(c["tg_id"])
    hourly=int(get_hourly_income(pid,include_referrals=True)[0] or 0)
    pos1=int(c["pos1"]); pos24=int(c["pos24"]); delta=int((c.get("latest") or {}).get("balance_delta") or 0)
    # Alert only on materially abnormal flow: large single jump, or sustained flow far above expected hourly income.
    single=delta>=25_000_000
    high1=pos1>=max(30_000_000, max(1,hourly)*6)
    high24=pos24>=max(100_000_000, max(1,hourly)*12)
    if not (single or high1 or high24): return None
    severity="CRITICAL" if high24 or delta>=100_000_000 or pos1>=max(100_000_000,max(1,hourly)*10) else "HIGH"
    # 15-minute cooldown per player/severity prevents notification spam.
    recent=conn=get_db()
    try:
        recent=conn.execute("SELECT id FROM economy_alerts WHERE tg_id=? AND created_at>=? AND severity=? LIMIT 1",(tg,now-900,severity)).fetchone()
        if recent:return None
        source=str((c.get("latest") or {}).get("path") or (c.get("latest") or {}).get("details") or "DB balance mutation")
        reason=[]
        if single: reason.append(f"разовое начисление {delta:,} ₽")
        if high1: reason.append(f"за 1ч +{pos1:,} ₽")
        if high24: reason.append(f"за 24ч +{pos24:,} ₽")
        details=f"Источник: {source}; ожидаемый серверный доход: ~{hourly:,} ₽/ч; множитель рефералов: {get_referral_boost_multiplier(pid):g}x"
        cur=conn.execute("INSERT INTO economy_alerts(player_id,tg_id,created_at,severity,reason,delta,window_1h,window_24h,hourly_income,balance,source,details) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(pid,tg,now,severity,"; ".join(reason),delta,pos1,pos24,hourly,int(c["balance"]),source,details))
        conn.commit(); return {"id":int(cur.lastrowid),"severity":severity,"tg_id":tg,"balance":int(c["balance"]),"delta":delta,"pos1":pos1,"pos24":pos24,"hourly":hourly,"reason":"; ".join(reason),"source":source}
    finally: conn.close()

async def economy_anomaly_monitor_loop():
    while True:
        try:
            candidates=await run_sync_db(_economy_alert_candidates_sync)
            for c in candidates:
                alert=await run_sync_db(_economy_alert_create_sync,c)
                if not alert: continue
                admins=await run_sync_db(lambda: [int(r[0]) for r in get_db().execute("SELECT tg_id FROM admin_users WHERE active=1").fetchall()])
                if int(ADMIN_SUPER_ID) not in admins: admins.append(int(ADMIN_SUPER_ID))
                msg=(f"🚨 <b>ECONOMY ALERT · {alert['severity']}</b>\n"
                     f"Игрок: <code>{alert['tg_id']}</code>\n"
                     f"Баланс: <b>{alert['balance']:,} ₽</b>\n"
                     f"Скачок: <b>+{alert['delta']:,} ₽</b>\n"
                     f"За 1ч: <b>+{alert['pos1']:,} ₽</b> · за 24ч: <b>+{alert['pos24']:,} ₽</b>\n"
                     f"Расчётный доход: <b>~{alert['hourly']:,} ₽/ч</b>\n"
                     f"Причина: {escape(str(alert['reason']))}\n"
                     f"Источник: <code>{escape(str(alert['source'])[:300])}</code>\n\n"
                     f"Открой профиль игрока в админке → полный аудит.")
                for admin_id in admins:
                    try: await bot.send_message(admin_id,msg,parse_mode="HTML")
                    except Exception as exc: print(f"⚠️ economy alert send {admin_id}: {exc}")
                await run_sync_db(lambda aid=alert['id']: _mark_economy_alert_sent_sync(aid))
        except asyncio.CancelledError: raise
        except Exception as exc: print(f"⚠️ Economy anomaly monitor: {exc}")
        await asyncio.sleep(90)

