def _admin_logs_sync(target_tg_id:int=None, limit:int=300, since_hours:int=0, q:str="", only_money:bool=False):
    conn=get_db()
    clauses=[]; params=[]
    if target_tg_id:
        clauses.append("target_tg_id=?"); params.append(int(target_tg_id))
    if since_hours and int(since_hours)>0:
        clauses.append("created_at>=?"); params.append(int(time_module.time())-int(since_hours)*3600)
    if q:
        like=f"%{str(q).strip()}%"
        clauses.append("(action LIKE ? OR details LIKE ? OR path LIKE ? OR request_json LIKE ?)")
        params.extend([like,like,like,like])
    if only_money:
        clauses.append("COALESCE(balance_delta,0)<>0")
    where=(" WHERE "+" AND ".join(clauses)) if clauses else ""
    params.append(max(1,min(int(limit),1000)))
    rows=conn.execute(f"SELECT id,actor_tg_id,target_tg_id,action,amount,details,created_at,event_type,method,path,status_code,duration_ms,ip,user_agent,before_balance,after_balance,balance_delta,request_json,request_id FROM audit_logs{where} ORDER BY id DESC LIMIT ?",params).fetchall()
    conn.close(); return [dict(r) for r in rows]

