async def _maintenance_request_user(request:Request):
    # Resolve the authenticated Telegram user for maintenance bypass.
    # Prefer the signed RESSELL session, then verified Telegram initData.
    # Never trust a bare userId by itself.
    candidates=[]
    for key in ('userId','user_id','tg_id','tgId'):
        try:
            v=int(request.query_params.get(key) or 0)
            if v and v not in candidates:candidates.append(v)
        except Exception: pass

    # JSON POST bodies often contain the user id while the URL does not.
    # Starlette caches request.body(), so downstream handlers can still read it.
    if request.method in ('POST','PUT','PATCH'):
        try:
            body=await request.body()
            payload=json.loads(body.decode('utf-8','replace') or '{}') if body else {}
            if isinstance(payload,dict):
                for key in ('userId','user_id','tg_id','tgId','player_id'):
                    try:
                        v=int(payload.get(key) or 0)
                        if v and v not in candidates:candidates.append(v)
                    except Exception: pass
        except Exception: pass

    path=request.url.path
    m=re.search(r'/(?:profile|hold|business|upgrades|passive|quests|epoch|referrals|referral|engagement|tycoon|avito|rcoin|friends|trading|container|race|poker|cars|garage|bank|taxi|game_result)/([0-9]+)',path)
    if m:
        v=int(m.group(1));
        if v not in candidates:candidates.append(v)

    token=_resell_session_from_request(request)
    if token:
        # A signed RESSELL session is itself bound to a Telegram id.
        # It can resolve the identity even when the endpoint has no user id.
        try:
            for uid in candidates:
                ok,_=_verify_resell_server_session(request,uid,365*24*60*60)
                if ok:return uid
            raw_token=str(token or '').strip()
            if raw_token.startswith('resell_session:'): raw_token=raw_token[len('resell_session:'):].strip()
            if raw_token.lower().startswith('bearer '): raw_token=raw_token[7:].strip()
            token_uid=0
            try: token_uid=int(raw_token.split('.',2)[0])
            except Exception: token_uid=0
            if token_uid:
                ok,_=_verify_resell_server_session(request,int(token_uid),365*24*60*60)
                if ok:return int(token_uid)
        except Exception: pass

    for raw in _telegram_init_data_candidates(request):
        try:
            data,_=_telegram_parse_init_data(raw); uid=_telegram_extract_uid(data)
            if uid and uid in candidates:
                ok,_=_telegram_verify_one(raw,uid,365*24*60*60)
                if ok:return uid
        except Exception: pass
    return 0

