def _create_update_announcement_sync(message:str,title:str='Сообщение от администрации'):
    conn=get_db()
    try:
        import time as _time
        now=int(_time.time()); msg=str(message).strip(); ttl=str(title).strip() or 'Сообщение от администрации'
        cols=[str(r["name"]) for r in conn.execute("PRAGMA table_info(update_announcements)").fetchall()]
        if 'title' not in cols:
            conn.execute("ALTER TABLE update_announcements ADD COLUMN title TEXT NOT NULL DEFAULT 'Сообщение от администрации'")
        cur=conn.execute("INSERT INTO update_announcements(message,created_at,title) VALUES(?,?,?)",(msg,now,ttl))
        conn.commit()
        return {"id":int(cur.lastrowid),"message":msg,"title":ttl,"created_at":now}
    finally: conn.close()

# ==================== LIVE EVENT API ====================
def _event_template(template_id: str):
    return next((dict(x) for x in EVENT_TEMPLATES if str(x.get("id")) == str(template_id)), None)

def _active_event_sync(now=None):
    now=int(now or time_module.time())
    conn=get_db()
    try:
        row=conn.execute("SELECT * FROM resell_events WHERE cancelled_at=0 AND ends_at>? ORDER BY id DESC LIMIT 1",(now,)).fetchone()
        return dict(row) if row else None
    finally: conn.close()

def _ensure_event_progress_sync(event_id:int, player_id:int, baseline:int):
    conn=get_db()
    try:
        conn.execute("INSERT OR IGNORE INTO resell_event_progress(event_id,player_id,baseline_total_earned) VALUES(?,?,?)",(int(event_id),int(player_id),int(baseline)))
        conn.commit()
    finally: conn.close()

def _event_state_sync(event:dict, tg_id:int):
    now=int(time_module.time()); player_id=get_player_id_by_tg_sync(int(tg_id))
    if not player_id:
        return {"current":0,"target":int(_event_template(event["template_id"])["target"]),"completed":False,"claimed":False}
    template=_event_template(event["template_id"])
    conn=get_db()
    try:
        prow=conn.execute("SELECT total_earned FROM players WHERE id=?",(int(player_id),)).fetchone()
        current_total=int(prow[0] or 0) if prow else 0
        conn.execute("INSERT OR IGNORE INTO resell_event_progress(event_id,player_id,baseline_total_earned) VALUES(?,?,?)",(int(event["id"]),int(player_id),current_total))
        base=int(conn.execute("SELECT baseline_total_earned FROM resell_event_progress WHERE event_id=? AND player_id=?",(int(event["id"]),int(player_id))).fetchone()[0])
        kind=template["kind"]
        if kind=="referrals":
            current=int(conn.execute("SELECT COUNT(*) FROM referral_relations WHERE inviter_tg_id=? AND activated_at>=? AND activated_at<=?",(int(tg_id),int(event["started_at"]),now)).fetchone()[0])
        elif kind=="earnings":
            current=max(0,current_total-base)
        elif kind=="containers":
            current=int(conn.execute("SELECT COUNT(*) FROM container_purchases cp WHERE cp.player_id=? AND cp.opened=1 AND cp.opened_at>=? AND cp.opened_at<=?",(int(player_id),int(event["started_at"]),now)).fetchone()[0])
        elif kind=="activity":
            allowed=("/container/open","/container/sell","/container/buy","/games/resell-run/claim","/passive/collect","/trading/","/race/","/upgrade/","/hold/")
            current=int(conn.execute("SELECT COUNT(*) FROM audit_logs WHERE actor_tg_id=? AND created_at>=? AND created_at<=? AND event_type='http' AND ("+" OR ".join(["path LIKE ?"]*len(allowed))+")",(int(tg_id),int(event["started_at"]),now,*[a+'%' for a in allowed])).fetchone()[0])
        elif kind=="trading_profit":
            current=int(conn.execute("SELECT COALESCE(SUM(amount),0) FROM audit_logs WHERE actor_tg_id=? AND action='trading_settlement' AND created_at>=? AND created_at<=?",(int(tg_id),int(event["started_at"]),now)).fetchone()[0] or 0)
        else:
            current=0
        claim=conn.execute("SELECT 1 FROM resell_event_claims WHERE event_id=? AND player_id=?",(int(event["id"]),int(player_id))).fetchone()
        conn.commit()
        cur,target=event_progress(template,{"referrals":current,"current_total_earned":base+current,"baseline_total_earned":base,"containers":current,"activity_count":current,"trading_profit":current})
        return {"current":int(cur),"target":int(target),"completed":int(cur)>=int(target),"claimed":bool(claim)}
    finally: conn.close()

@app.get("/events/active")
async def events_active(userId:int=0, request:Request=None):
    event=await run_sync_db(_active_event_sync)
    if not event:
        return JSONResponse({"success":True,"event":None})
    template=_event_template(event["template_id"])
    if not template:
        return JSONResponse({"success":False,"error":"Неизвестный тип ивента"},status_code=500)
    if not _verify_telegram_webapp_request(request,int(userId)):
        return JSONResponse({"success":False,"error":"Сессия Telegram недействительна. Открой игру заново."},status_code=401)
    state=await run_sync_db(_event_state_sync,event,int(userId))
    return JSONResponse({"success":True,"event":{**template,"id":int(event["id"]),"started_at":int(event["started_at"]),"ends_at":int(event["ends_at"])},"remaining":event_remaining(event["started_at"],int(time_module.time())),"progress":state})

@app.post("/events/claim")
async def events_claim(request:Request):
    try: data=await request.json()
    except Exception: data={}
    tg_id=int(data.get("userId") or 0); event_id=int(data.get("event_id") or 0)
    if not tg_id or not event_id: return JSONResponse({"success":False,"error":"Некорректные данные"},status_code=400)
    if not _verify_telegram_webapp_request(request,tg_id): return JSONResponse({"success":False,"error":"Сессия Telegram недействительна. Открой игру заново."},status_code=401)
    def _claim():
        now=int(time_module.time()); conn=get_db()
        try:
            conn.execute("BEGIN IMMEDIATE")
            event=conn.execute("SELECT * FROM resell_events WHERE id=? AND cancelled_at=0",(event_id,)).fetchone()
            if not event or now>int(event["ends_at"]): conn.rollback(); return {"error":"Ивент уже завершён или отменён"}
            template=_event_template(event["template_id"])
            p=conn.execute("SELECT id,balance,total_earned FROM players WHERE tg_id=?",(tg_id,)).fetchone()
            if not p: conn.rollback(); return {"error":"Игрок не найден"}
            pid=int(p["id"])
            if conn.execute("SELECT 1 FROM resell_event_claims WHERE event_id=? AND player_id=?",(event_id,pid)).fetchone(): conn.rollback(); return {"error":"Награда уже получена"}
            base_row=conn.execute("SELECT baseline_total_earned FROM resell_event_progress WHERE event_id=? AND player_id=?",(event_id,pid)).fetchone()
            if not base_row:
                base=int(p["total_earned"] or 0); conn.execute("INSERT INTO resell_event_progress(event_id,player_id,baseline_total_earned) VALUES(?,?,?)",(event_id,pid,base)); base_row=(base,)
            base=int(base_row[0]); current_total=int(p["total_earned"] or 0)
            kind=template["kind"]
            if kind=="referrals": current=int(conn.execute("SELECT COUNT(*) FROM referral_relations WHERE inviter_tg_id=? AND activated_at>=? AND activated_at<=?",(tg_id,int(event["started_at"]),now)).fetchone()[0])
            elif kind=="earnings": current=max(0,current_total-base)
            elif kind=="containers": current=int(conn.execute("SELECT COUNT(*) FROM container_purchases cp WHERE cp.player_id=? AND cp.opened=1 AND cp.opened_at>=? AND cp.opened_at<=?",(pid,int(event["started_at"]),now)).fetchone()[0])
            elif kind=="activity":
                allowed=("/container/open","/container/sell","/container/buy","/games/resell-run/claim","/passive/collect","/trading/","/race/","/upgrade/","/hold/")
                current=int(conn.execute("SELECT COUNT(*) FROM audit_logs WHERE actor_tg_id=? AND created_at>=? AND created_at<=? AND event_type='http' AND ("+" OR ".join(["path LIKE ?"]*len(allowed))+")",(tg_id,int(event["started_at"]),now,*[a+'%' for a in allowed])).fetchone()[0])
            elif kind=="trading_profit":
                current=int(conn.execute("SELECT COALESCE(SUM(amount),0) FROM audit_logs WHERE actor_tg_id=? AND action='trading_settlement' AND created_at>=? AND created_at<=?",(tg_id,int(event["started_at"]),now)).fetchone()[0] or 0)
            else: current=0
            if int(current)<int(template["target"]): conn.rollback(); return {"error":f"Условие ещё не выполнено: {min(int(current),int(template['target']))} / {int(template['target'])}"}
            reward=int(template["reward"])
            conn.execute("INSERT INTO resell_event_claims(event_id,player_id,reward,claimed_at) VALUES(?,?,?,?)",(event_id,pid,reward,now))
            before=int(p["balance"] or 0) if "balance" in p.keys() else int(conn.execute("SELECT balance FROM players WHERE id=?",(pid,)).fetchone()[0])
            conn.execute("UPDATE players SET balance=balance+?, total_earned=total_earned+?, stat_earned_today=stat_earned_today+? WHERE id=?",(reward,reward,reward,pid))
            after=before+reward
            new_total_earned=int(conn.execute("SELECT total_earned FROM players WHERE id=?",(pid,)).fetchone()[0] or 0)
            conn.commit()
            return {"reward":reward,"balance":after,"total_earned":new_total_earned}
        except Exception:
            conn.rollback(); raise
        finally: conn.close()
    result=await run_sync_db(_claim)
    if result.get("error"): return JSONResponse({"success":False,"error":result["error"]},status_code=400)
    await audit(tg_id,tg_id,"resell_event_claim",int(result["reward"]),f"event_id={event_id}")
    return JSONResponse({"success":True,**result})

