@app.post("/admin/events/{admin_tg_id}/start")
async def admin_events_start(admin_tg_id:int, request:Request):
    if not _admin_verify_request(request,admin_tg_id): return JSONResponse({"success":False,"error":"Нет доступа"},status_code=403)
    try: data=await request.json()
    except Exception: data={}
    template_id=str(data.get("template_id") or "")
    template=_event_template(template_id)
    if not template: return JSONResponse({"success":False,"error":"Ивент не найден"},status_code=400)
    def _start():
        now=int(time_module.time()); conn=get_db()
        try:
            conn.execute("BEGIN IMMEDIATE")
            active=conn.execute("SELECT id FROM resell_events WHERE cancelled_at=0 AND ends_at>? LIMIT 1",(now,)).fetchone()
            if active: conn.rollback(); return {"error":"Сейчас уже идёт другой ивент"}
            cur=conn.execute("INSERT INTO resell_events(template_id,started_at,ends_at,cancelled_at,created_by) VALUES(?,?,?,?,?)",(template_id,now,now+EVENT_DURATION_SEC,0,admin_tg_id))
            eid=int(cur.lastrowid)
            conn.execute("INSERT INTO resell_event_progress(event_id,player_id,baseline_total_earned) SELECT ?,id,COALESCE(total_earned,0) FROM players WHERE tg_id IS NOT NULL AND COALESCE(is_banned,0)=0",(eid,))
            conn.commit(); return {"event_id":eid,"started_at":now,"ends_at":now+EVENT_DURATION_SEC}
        except Exception:
            conn.rollback(); raise
        finally: conn.close()
    result=await run_sync_db(_start)
    if result.get("error"): return JSONResponse({"success":False,"error":result["error"]},status_code=409)
    await audit(admin_tg_id,admin_tg_id,"event_start",0,f"event_id={result['event_id']};template={template_id}")
    return JSONResponse({"success":True,**result})

