@app.post("/admin/update-announcement/{admin_tg_id}")
async def admin_update_announcement(admin_tg_id:int, request:Request):
    if not _admin_verify_request(request, admin_tg_id):
        return JSONResponse({"success":False,"error":"Нет доступа"},status_code=403)
    try: data=await request.json()
    except Exception: data={}
    message=str(data.get("message") or "").strip()
    title=str(data.get("title") or "Сообщение от администрации").strip()
    if not message:
        return JSONResponse({"success":False,"error":"Напиши сообщение для игроков"},status_code=400)
    if len(message)>4000:
        return JSONResponse({"success":False,"error":"Сообщение слишком длинное (максимум 4000 символов)"},status_code=400)
    if len(title)>80:
        return JSONResponse({"success":False,"error":"Заголовок слишком длинный (максимум 80 символов)"},status_code=400)
    try:
        row=await run_sync_db(_create_update_announcement_sync,message,title)
    except Exception as exc:
        print(f"[ADMIN BROADCAST] create failed: {type(exc).__name__}: {exc}")
        return JSONResponse({"success":False,"error":"Не удалось сохранить сообщение. Проверь соединение с базой и попробуй ещё раз."},status_code=200)
    await audit(admin_tg_id,admin_tg_id,'admin_broadcast',0,f"{title}: {message[:450]}")
    return JSONResponse({"success":True,"announcement":row})

