@app.get("/admin/player/{admin_tg_id}/{target_tg_id}")
async def admin_player(admin_tg_id:int,target_tg_id:int, request:Request):
    if not _admin_verify_request(request, admin_tg_id): return JSONResponse({"success":False,"error":"Нет доступа"},status_code=403)
    p=await run_sync_db(_admin_player_sync,target_tg_id)
    if not p: return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    pid=int(p["id"])
    # Не даём сбою второстепенного блока (аудит/активы/экономика) уронить
    # весь экран управления игроком. Каждая выборка открывает и закрывает своё соединение.
    async def _admin_optional(fn, *args, default=None):
        try:
            return await run_sync_db(fn, *args)
        except Exception:
            import logging
            logging.getLogger(__name__).exception(
                "Admin player optional section failed: tg_id=%s fn=%s",
                target_tg_id, getattr(fn, "__name__", "query")
            )
            return default

    def _shops():
        conn=get_db()
        try:
            return [dict(r) for r in conn.execute("SELECT shop_id FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active'",(pid,)).fetchall()]
        finally:
            conn.close()

    def _alerts():
        conn=get_db()
        try:
            return [dict(r) for r in conn.execute("SELECT id,created_at,severity,reason,delta,window_1h,window_24h,hourly_income,balance,source,details,sent_at FROM economy_alerts WHERE tg_id=? ORDER BY id DESC LIMIT 30",(int(target_tg_id),)).fetchall()]
        finally:
            conn.close()

    shops=await _admin_optional(_shops, default=[])
    cars=await _admin_optional(_admin_cars_sync,pid,default=[])
    logs=await _admin_optional(_admin_logs_sync,target_tg_id,300,default=[])
    security=await _admin_optional(_ban_status_sync,target_tg_id,default={})
    assets=await _admin_optional(_admin_asset_snapshot_sync,pid,default={})
    economic=await _admin_optional(_admin_economic_summary_sync,target_tg_id,default={})
    economy_detail=await _admin_optional(_admin_economy_detail_sync,pid,target_tg_id,default={})
    wealth=await _admin_optional(_admin_wealth_breakdown_sync,pid,default={})
    alerts=await _admin_optional(_alerts,default=[])
    def _leaderboard_hidden_sync():
        conn=get_db()
        try:
            return bool(conn.execute("SELECT 1 FROM leaderboard_exclusions WHERE player_id=?",(pid,)).fetchone())
        finally:
            conn.close()
    leaderboard_hidden=await _admin_optional(_leaderboard_hidden_sync,default=False)
    catalog=[{"id":x.get("id"),"name":x.get("name"),"price":int(x.get("price",0)),"income_per_hour":int(x.get("income_per_hour",0))} for x in SHOP_LEVELS if x.get("id") and x.get("id")!="none"]
    skins=[{"id":x.get("id"),"name":x.get("name"),"price":int(x.get("price",0))} for x in SKINS]
    return JSONResponse({"success":True,"player":p,"security":security,"shops":shops,"cars":cars,"catalog":catalog,"skins":skins,"logs":logs,"assets":assets,"economic":economic,"economy_detail":economy_detail,"economy_alerts":alerts,"wealth":wealth,"leaderboard_hidden":leaderboard_hidden})

