@app.post("/admin/player/{admin_tg_id}/{target_tg_id}/rfarm-reset")
async def admin_reset_rfarm(admin_tg_id:int,target_tg_id:int, request:Request):
    if not _admin_verify_request(request, admin_tg_id):
        return JSONResponse({"success":False,"error":"Нет доступа"},status_code=403)
    pid=await get_player_id_by_tg(target_tg_id)
    if not pid:return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    def _reset():
        conn=get_db();cur=conn.cursor()
        try:
            cur.execute("BEGIN IMMEDIATE")
            cur.execute("UPDATE hold_sessions SET last_completed_at=0,session_id=NULL,started_at=0,target_reward=0,target_duration=?,last_completed_session_id='',last_reward=0 WHERE player_id=?",(RFARM_DURATION,pid))
            if cur.rowcount==0:
                cur.execute("INSERT INTO hold_sessions(player_id,session_id,started_at,last_completed_at,total_claims,target_reward,target_duration,last_completed_session_id,last_reward) VALUES(?,?,?,?,?,?,?,?,?)",(pid,None,0,0,0,0,RFARM_DURATION,'',0))
            conn.commit();return True
        except Exception:conn.rollback();raise
        finally:conn.close()
    await run_sync_db(_reset)
    await audit(admin_tg_id,target_tg_id,"rfarm_reset",0,"Администратор снял CD R-Farm")
    return JSONResponse({"success":True,"message":"CD R-Farm снят. Игрок может запустить новый раунд."})

