def _export_all_player_logs_sync(target_tg_id:int):
    """Export the complete audit history for one player, with no time/row limit.

    The export is streamed from SQLite into a gzip-compressed CSV so the admin
    panel never has to load the player's entire history into browser memory.
    """
    target_tg_id=int(target_tg_id)
    conn=get_db()
    path=None
    try:
        player=conn.execute("SELECT tg_id,nickname,shop_name,balance,total_earned,total_profit,total_sales,items_sold,created_at,is_banned FROM players WHERE tg_id=?",(target_tg_id,)).fetchone()
        if not player:
            return None
        fd,path=tempfile.mkstemp(prefix=f"resell_player_{target_tg_id}_",suffix=".csv.gz")
        os.close(fd)
        columns=["id","actor_tg_id","target_tg_id","action","amount","details","created_at","event_type","method","path","status_code","duration_ms","ip","user_agent","before_balance","after_balance","balance_delta","request_json","request_id"]
        count=0
        with gzip.open(path,"wt",encoding="utf-8",newline="") as gz:
            writer=csv.writer(gz)
            writer.writerow(["RESSELL PLAYER AUDIT EXPORT"])
            writer.writerow(["target_tg_id",target_tg_id])
            writer.writerow(["nickname",str(player["nickname"] or "")])
            writer.writerow(["shop_name",str(player["shop_name"] or "")])
            writer.writerow(["current_balance",int(player["balance"] or 0)])
            writer.writerow(["total_earned",int(player["total_earned"] or 0)])
            writer.writerow(["total_profit",int(player["total_profit"] or 0)])
            writer.writerow(["total_sales",int(player["total_sales"] or 0)])
            writer.writerow(["items_sold",int(player["items_sold"] or 0)])
            writer.writerow(["created_at",str(player["created_at"] or "")])
            writer.writerow([])
            writer.writerow(columns)
            cursor=conn.execute("SELECT id,actor_tg_id,target_tg_id,action,amount,details,created_at,event_type,method,path,status_code,duration_ms,ip,user_agent,before_balance,after_balance,balance_delta,request_json,request_id FROM audit_logs WHERE target_tg_id=? ORDER BY id ASC",(target_tg_id,))
            for row in cursor:
                writer.writerow([row[c] for c in range(len(columns))])
                count+=1
        size=os.path.getsize(path)
        return {"path":path,"count":count,"size":size,"target_tg_id":target_tg_id,"nickname":str(player["nickname"] or "") }
    except Exception:
        if path:
            try: os.remove(path)
            except Exception: pass
        raise
    finally:
        conn.close()

@app.post("/admin/player/{admin_tg_id}/{target_tg_id}/logs/download")
async def admin_download_all_player_logs(admin_tg_id:int,target_tg_id:int,request:Request):
    """Generate the complete all-time audit file and send it to the admin in Telegram."""
    if not _admin_verify_request(request, admin_tg_id):
        return JSONResponse({"success":False,"error":"Нет доступа"},status_code=403)
    target_tg_id=int(target_tg_id); admin_tg_id=int(admin_tg_id)
    try:
        # Record the request before export so the export itself contains this audit event.
        await audit(admin_tg_id,target_tg_id,"admin_logs_export",0,"Администратор запросил полный аудит за всё время")
        result=await run_sync_db(_export_all_player_logs_sync,target_tg_id)
        if not result:
            return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
        path=result["path"]
        try:
            caption=(f"📋 RESSELL · полный аудит игрока\n"
                     f"Игрок: {target_tg_id} · {result['nickname'] or 'Без никнейма'}\n"
                     f"Событий: {result['count']:,}\n"
                     f"Период: всё время\n"
                     f"Формат: CSV + gzip")
            await bot.send_document(admin_tg_id,FSInputFile(path,filename=f"resell_audit_{target_tg_id}_all_time.csv.gz"),caption=caption)
        finally:
            try: os.remove(path)
            except Exception: pass
        return JSONResponse({"success":True,"count":result["count"],"message":f"Полный аудит отправлен в Telegram: {result['count']:,} событий"})
    except Exception as exc:
        print(f"⚠️ [ADMIN LOG EXPORT] {target_tg_id}: {type(exc).__name__}: {exc}")
        return JSONResponse({"success":False,"error":"Не удалось сформировать или отправить файл логов"},status_code=500)

