# ==================== RESSELL TYCOON MINI APP API ====================
# These endpoints expose the existing game logic to the Mini App. All money,
# validation and database mutations remain server-side.

@app.get("/tycoon/bank/{tg_id}")
async def tycoon_bank(tg_id: int, request: Request):
    if not _verify_tycoon_webapp_request(request,tg_id): return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"success":False,"error":"Вы не зарегистрированы"},status_code=404)
    player = await run_sync_db(get_player_data, player_id)
    now=int(time_module.time())
    def _read():
        conn=get_db()
        deps=conn.execute("SELECT id,amount,start_time,duration_days,interest_rate,status FROM deposits WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id DESC",(player_id,)).fetchall()
        loans=conn.execute("SELECT id,amount,interest_rate,start_time,due_date,status,paid_amount FROM loans WHERE player_id=? ORDER BY id DESC",(player_id,)).fetchall()
        conn.close()
        return [dict(x) for x in deps],[dict(x) for x in loans]
    deps,loans=await run_sync_db(_read)
    for d in deps:
        d["return_amount"]=int(d["amount"]*(1+d["interest_rate"]/100))
        d["remaining_seconds"]=max(0,int(d["start_time"]+d["duration_days"]*86400-now)) if d["status"]=="active" else 0
        d["ready"]=d["status"]=="active" and d["remaining_seconds"]<=0
    for l in loans:
        l["return_amount"]=int(l["amount"]*(1+l["interest_rate"]/100))
        l["remaining_seconds"]=max(0,int(l["due_date"]-now)) if l["status"]=="active" else 0
    max_loan=await calculate_max_loan(player)
    return JSONResponse({"success":True,"balance":int(player.get("balance",0) or 0),"deposits":deps,"loans":loans,"max_loan":int(max_loan),"deposit_min":10000,"deposit_max":MAX_DEPOSIT_AMOUNT,"economy_build":RESSELL_ECONOMY_BUILD})

@app.post("/tycoon/bank/{tg_id}/deposit")
async def tycoon_open_deposit(tg_id:int,request:Request):
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    try: data=await request.json()
    except Exception: data={}
    days=int(data.get("days") or 0); amount=int(data.get("amount") or 0)
    rates={1:2,3:5,7:10}
    rate=rates.get(days)
    if not rate: return JSONResponse({"success":False,"error":"Неверный срок депозита"},status_code=400)
    if amount<10000 or amount>MAX_DEPOSIT_AMOUNT: return JSONResponse({"success":False,"error":f"Сумма депозита от 10 000 до {MAX_DEPOSIT_AMOUNT:,} ₽"},status_code=400)
    pid=await get_player_id_by_tg(tg_id)
    player=await run_sync_db(get_player_data,pid) if pid else None
    if not player: return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    now=int(time_module.time())
    async with db_lock:
        conn=get_db()
        try:
            conn.execute("BEGIN IMMEDIATE")
            changed=conn.execute("UPDATE players SET balance=balance-? WHERE id=? AND balance>=?",(amount,pid,amount)).rowcount
            if changed!=1:
                conn.rollback(); conn.close()
                return JSONResponse({"success":False,"error":"Недостаточно средств"},status_code=400)
            conn.execute("INSERT INTO deposits(player_id,amount,start_time,duration_days,interest_rate,status) VALUES(?,?,?,?,?,'active')",(pid,amount,now,days,rate))
            conn.commit()
        except Exception:
            conn.rollback(); raise
        finally:
            conn.close()
    fresh=await run_sync_db(get_player_data,pid) or {}
    return JSONResponse({"success":True,"message":f"Депозит на {amount:,} ₽ открыт на {days} дн. под {rate}%","balance":int(fresh.get("balance",0) or 0)})

@app.post("/tycoon/bank/{tg_id}/loan")
async def tycoon_take_loan(tg_id:int,request:Request):
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    try:
        data=await request.json()
    except Exception:
        data={}
    amount=int(data.get("amount") or 0)
    if amount<10000 or amount>1000000:
        return JSONResponse({"success":False,"error":"Кредит от 10 000 до 1 000 000 ₽"},status_code=400)

    pid=await get_player_id_by_tg(tg_id)
    player=await run_sync_db(get_player_data,pid) if pid else None
    if not player:
        return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)

    max_loan=await calculate_max_loan(player)
    if amount>max_loan:
        return JSONResponse({"success":False,"error":f"Банк одобряет максимум {max_loan:,} ₽"},status_code=400)

    now=int(time_module.time())
    due=now+2*86400
    rate=5.0

    lock=player_action_locks.setdefault(f"loan:{pid}",asyncio.Lock())
    async with lock:
        async with db_lock:
            def _take():
                conn=get_db(); cur=conn.cursor()
                try:
                    cur.execute("BEGIN IMMEDIATE")
                    active=cur.execute(
                        "SELECT id FROM loans WHERE player_id=? AND status='active' LIMIT 1",
                        (pid,)
                    ).fetchone()
                    if active:
                        conn.rollback()
                        return ("active",)

                    row=cur.execute("SELECT balance FROM players WHERE id=?",(pid,)).fetchone()
                    if not row:
                        conn.rollback()
                        return ("missing",)

                    cur.execute(
                        "UPDATE players SET balance=balance+? WHERE id=?",
                        (amount,pid)
                    )
                    cur.execute(
                        """INSERT INTO loans(
                            player_id,amount,interest_rate,start_time,due_date,status
                        ) VALUES(?,?,?,?,?,'active')""",
                        (pid,amount,rate,now,due)
                    )
                    fresh=cur.execute("SELECT balance FROM players WHERE id=?",(pid,)).fetchone()
                    conn.commit()
                    return ("ok",int(fresh["balance"] if fresh else 0))
                except Exception:
                    conn.rollback()
                    raise
                finally:
                    conn.close()

            result=await run_sync_db(_take)

    if result[0]=="active":
        return JSONResponse({"success":False,"error":"У вас уже есть активный кредит"},status_code=400)
    if result[0]=="missing":
        return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)

    return JSONResponse({
        "success":True,
        "message":f"Кредит {amount:,} ₽ одобрен",
        "balance":result[1]
    })


@app.post("/tycoon/bank/{tg_id}/repay")
async def tycoon_repay_loan(tg_id:int,request:Request):
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    try: data=await request.json()
    except Exception: data={}
    loan_id=int(data.get("loan_id") or 0); amount=int(data.get("amount") or 0)
    pid=await get_player_id_by_tg(tg_id); player=await run_sync_db(get_player_data,pid) if pid else None
    if not player: return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    conn=get_db(); loan=conn.execute("SELECT amount,interest_rate,status FROM loans WHERE id=? AND player_id=?",(loan_id,pid)).fetchone(); conn.close()
    if not loan or loan["status"]!='active': return JSONResponse({"success":False,"error":"Активный кредит не найден"},status_code=404)
    due=int(loan["amount"]*(1+loan["interest_rate"]/100))
    if amount<due: return JSONResponse({"success":False,"error":f"Для полного погашения нужно {due:,} ₽"},status_code=400)
    over=amount-due
    async with db_lock:
        conn=get_db()
        try:
            conn.execute("BEGIN IMMEDIATE")
            fresh_loan=conn.execute("SELECT amount,interest_rate,status FROM loans WHERE id=? AND player_id=?",(loan_id,pid)).fetchone()
            if not fresh_loan or fresh_loan["status"]!='active':
                conn.rollback(); return JSONResponse({"success":False,"error":"Кредит уже погашен"},status_code=409)
            fresh_due=int(fresh_loan["amount"]*(1+fresh_loan["interest_rate"]/100))
            if amount<fresh_due:
                conn.rollback(); return JSONResponse({"success":False,"error":f"Для полного погашения нужно {fresh_due:,} ₽"},status_code=400)
            fresh_over=amount-fresh_due
            changed=conn.execute("UPDATE players SET balance=balance-?+? WHERE id=? AND balance>=?",(amount,fresh_over,pid,amount)).rowcount
            if changed!=1:
                conn.rollback(); return JSONResponse({"success":False,"error":"Недостаточно средств"},status_code=400)
            closed=conn.execute("UPDATE loans SET status='closed',paid_amount=? WHERE id=? AND status='active'",(fresh_due,loan_id)).rowcount
            if closed!=1:
                conn.rollback(); return JSONResponse({"success":False,"error":"Кредит уже погашен"},status_code=409)
            conn.commit()
        except Exception:
            conn.rollback(); raise
        finally:
            conn.close()
    fresh=await run_sync_db(get_player_data,pid) or {}
    return JSONResponse({"success":True,"message":f"Кредит погашен. Переплата {over:,} ₽ возвращена.","balance":int(fresh.get("balance",0) or 0)})


# ==================== TYCOON AUTO API ====================
# Frontend /tycoon/cars/* endpoints.  Kept separate from the taxi engine.
@app.get("/tycoon/cars/{tg_id}")
async def tycoon_cars(tg_id:int, request:Request):
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    pid=await get_player_id_by_tg(tg_id)
    if not pid:
        return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    player=await run_sync_db(get_player_data,pid) or {}
    collection=list(player.get("car_collection",[]) or [])
    now=int(time_module.time())
    stats=_safe_car_stats(player.get("garage_car_stats"),len(collection),now)
    # Load tuning from its authoritative table so a restart or taxi refresh
    # cannot make purchased upgrades disappear.
    conn=get_db()
    try:
        stats=_load_authoritative_car_tuning(conn,pid,collection,stats)
        conn.commit()
    finally:
        conn.close()
    garage=[]
    for i,car_id in enumerate(collection):
        car=next((c for c in CARS if c.get("id")==car_id),None)
        if not car: continue
        st=stats[i] if isinstance(stats[i],dict) else {}
        tuning=_safe_car_tuning(st.get("tuning"))
        tuned_speed=_car_speed(car,tuning)
        tuned_income=_car_income_per_hour(car,tuning)
        garage.append({**car,"instance_index":i,"wear":max(0.0,min(100.0,float(st.get("wear",0) or 0))),
                       "mileage":float(st.get("mileage",0) or 0),"total_income":int(st.get("total_income",0) or 0),
                       "updated_at":float(st.get("updated_at") or now),"tuning":tuning,
                       "tuned_speed":tuned_speed,"tuned_income_per_hour":tuned_income,"lease_income_per_hour":tuned_income,
                       "taxi_income_per_hour":int(round(tuned_income*_taxi_multiplier_for_player(pid))),
                       "in_taxopark":i in _taxi_indices(_safe_taxopark(player.get("taxopark")),collection)})
    current_id=player.get("current_car","none")
    current=next((c for c in CARS if c.get("id")==current_id),None)
    if current:
        current_idx=next((i for i,cid in enumerate(collection) if str(cid)==str(current_id)), -1)
        current_tuning=stats[current_idx].get("tuning") if 0 <= current_idx < len(stats) else {}
        current={**current,"tuning":_safe_car_tuning(current_tuning),"tuned_speed":_car_speed(current,current_tuning),"tuned_income_per_hour":_car_income_per_hour(current,current_tuning),"lease_income_per_hour":_car_income_per_hour(current,current_tuning)}
    regular_catalog=[c for c in CARS if not c.get("custom")]
    return JSONResponse({"success":True,"balance":int(player.get("balance",0) or 0),"cars":regular_catalog,"garage":garage,
                         "current":current,"current_car":current_id,
                         "car_tuning_config":CAR_TUNING_CONFIG})

@app.get("/tycoon/custom/{tg_id}")
async def tycoon_custom(tg_id:int, request:Request):
    """Dedicated RESSELL Custom showroom. Read-only metadata plus ownership state."""
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    pid=await get_player_id_by_tg(tg_id)
    if not pid:
        return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    player=await run_sync_db(get_player_data,pid) or {}
    owned=set(str(x) for x in (player.get("car_collection") or []))
    tuning_max={k:int(v.get("max",5)) for k,v in CAR_TUNING_CONFIG.items()}
    multiplier=_taxi_multiplier_for_player(pid)
    cars=[]
    for car in RESSELL_CUSTOM_CARS:
        tuned_speed=_car_speed(car,tuning_max)
        tuned_income=_car_income_per_hour(car,tuning_max)
        cars.append({**car,"owned":car["id"] in owned,"tuned_speed":tuned_speed,
                     "lease_income_per_hour":tuned_income,
                     "taxi_income_per_hour":int(round(tuned_income*multiplier)),
                     "tuning":"MAX"})
    return JSONResponse({"success":True,"balance":int(player.get("balance",0) or 0),
                         "cars":cars,"owned":sorted(owned.intersection({c["id"] for c in RESSELL_CUSTOM_CARS})),
                         "current_car":str(player.get("current_car") or "none"),"taxi_multiplier":multiplier})

@app.post("/tycoon/custom/{tg_id}/buy")
async def tycoon_custom_buy(tg_id:int, request:Request):
    """Purchase one limited Custom car. One copy per model per player; all tuning is pre-installed."""
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    try: data=await request.json()
    except Exception: data={}
    car_id=str(data.get("car_id") or "")
    car=next((c for c in RESSELL_CUSTOM_CARS if c.get("id")==car_id),None)
    if not car:
        return JSONResponse({"success":False,"error":"Коллекционная машина не найдена"},status_code=404)
    pid=await get_player_id_by_tg(tg_id)
    if not pid:
        return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    async with db_lock:
        conn=get_db()
        try:
            cur=conn.cursor(); cur.execute("BEGIN IMMEDIATE")
            row=cur.execute("SELECT balance,car_collection,garage_car_stats,current_car FROM players WHERE id=?",(pid,)).fetchone()
            if not row:
                conn.rollback(); return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
            balance=int(row["balance"] or 0)
            collection=_safe_json_list(row["car_collection"])
            if car_id in [str(x) for x in collection]:
                conn.rollback(); return JSONResponse({"success":False,"error":"Эта машина уже находится в вашей коллекции"},status_code=409)
            price=int(car["price"])
            if balance<price:
                conn.rollback(); return JSONResponse({"success":False,"error":f"Недостаточно средств. Нужно {price:,} ₽","balance":balance},status_code=400)
            try: stats=json.loads(row["garage_car_stats"] or "[]")
            except Exception: stats=[]
            if not isinstance(stats,list): stats=[]
            now=int(time_module.time())
            tuning={k:int(v.get("max",5)) for k,v in CAR_TUNING_CONFIG.items()}
            collection.append(car_id)
            stats.append({"mileage":0.0,"wear":0.0,"total_income":0,"updated_at":now,"tuning":tuning})
            current=str(row["current_car"] or "none")
            if not current or current=="none": current=car_id
            newbal=balance-price
            cur.execute("UPDATE players SET balance=?,car_collection=?,garage_car_stats=?,current_car=? WHERE id=?",
                        (newbal,json.dumps(collection,ensure_ascii=False),json.dumps(stats,ensure_ascii=False),current,pid))
            idx=len(collection)-1
            cur.execute(
                "INSERT INTO car_tuning_state(player_id,instance_index,car_id,tuning,updated_at) VALUES(?,?,?,?,?) "
                "ON CONFLICT(player_id,instance_index) DO UPDATE SET car_id=excluded.car_id,tuning=excluded.tuning,updated_at=excluded.updated_at",
                (int(pid),idx,car_id,json.dumps(tuning,ensure_ascii=False),now)
            )
            conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
            raise
        finally:
            conn.close()
    tuned_speed=_car_speed(car,tuning); tuned_income=_car_income_per_hour(car,tuning)
    taxi_income=int(round(tuned_income*_taxi_multiplier_for_player(pid)))
    return JSONResponse({"success":True,"message":f"{car['name']} добавлена в RESSELL Custom.","balance":newbal,
                         "car":{**car,"owned":True,"tuned_speed":tuned_speed,"lease_income_per_hour":tuned_income,"taxi_income_per_hour":taxi_income,"tuning":"MAX"},
                         "current_car":current})

