def _web_chat_payload(chat: dict) -> dict:
    """Serialize an internal Avito chat to the stable frontend contract."""
    chat = chat if isinstance(chat, dict) else {}
    history = chat.get("history") if isinstance(chat.get("history"), list) else []
    last_message = ""
    for msg in reversed(history):
        if isinstance(msg, dict) and msg.get("content"):
            last_message = str(msg.get("content"))
            break

    market_price = max(1, int(chat.get("price", 0) or 1))
    current_offer = max(1, int(chat.get("offer", market_price) or market_price))
    # На этапах 1–4 кнопки ответа берутся из конкретного сценария,
    # поэтому вопрос про дату покупки, доставку, состояние и т.д.
    # больше не получает одинаковые универсальные ответы.
    dialogue = chat.get("dialogue") if isinstance(chat.get("dialogue"), dict) else {}
    answer_sets = dialogue.get("answer_sets") if isinstance(dialogue.get("answer_sets"), list) else []
    phase_num = int(chat.get("phase", 1) or 1)
    if 1 <= phase_num <= 4:
        if phase_num <= len(answer_sets) and isinstance(answer_sets[phase_num - 1], list):
            answer_row = answer_sets[phase_num - 1]
            choices = [{"label": str(x), "kind": "dialogue", "score": [12, 7, 2][i]} for i, x in enumerate(answer_row[:3])]
        else:
            # Даже специальные диалоги обязаны пройти четыре текстовых этапа.
            # Цена появляется только после завершения переговорной части.
            generic = [
                ["Показать подтверждение", "Дать подробности", "Ответить коротко"],
                ["Показать состояние", "Уточнить детали", "Ответить по факту"],
                ["Показать комплект", "Подтвердить наличие", "Уточнить нюанс"],
                ["Подтвердить условия", "Обсудить детали", "Завершить обсуждение"],
            ][phase_num - 1]
            choices = [{"label": x, "kind": "dialogue", "score": [12, 7, 2][i]} for i, x in enumerate(generic)]
    else:
        choices = []
    if not choices and current_offer == market_price:
        base = market_price
        special_type=str(chat.get("found_type") or chat.get("hunt_type") or chat.get("item_obj",{}).get("found_type") or chat.get("item_obj",{}).get("hunt_type") or "")
        if special_type:
            choices = [
                {"label": "Быстро закрыть · −7%", "price": max(1, int(round(base * 0.93))), "risk": 5},
                {"label": "Рыночная цена", "price": base, "risk": 20},
                {"label": "Проверить потолок · +8%", "price": max(1, int(round(base * 1.08))), "risk": 55},
            ]
        else:
            choices = [
                {"label": "Быстрая сделка · −10%", "price": max(1, int(round(base * 0.90))), "risk": 5},
                {"label": "Цена рынка", "price": base, "risk": 20},
                {"label": "Попробовать дороже · +10%", "price": max(1, int(round(base * 1.10))), "risk": 55},
            ]
    elif not choices:
        midpoint = max(1, int(round(((current_offer + market_price) / 2) / 100.0) * 100))
        choices = [
            {"label": "Быстрая сделка", "price": current_offer, "risk": 8},
            {"label": "Компромисс", "price": midpoint, "risk": 25},
            {"label": "Держать цену", "price": market_price, "risk": 48},
        ]
    # Dialogue answers do not have a numeric price. Older code tried to
    # read c["price"] for every choice, which raised KeyError during publish
    # because the freshly-created chat was serialized immediately.
    # Deduplicate numeric price choices and textual dialogue choices safely.
    seen=set(); unique_choices=[]
    for c in choices:
        if not isinstance(c, dict):
            continue
        if c.get("kind") == "dialogue" or "score" in c:
            key=("dialogue", str(c.get("label") or ""))
        else:
            try:
                key=("price", int(c.get("price", 0) or 0))
            except Exception:
                key=("price", str(c.get("label") or ""))
        if key not in seen:
            seen.add(key); unique_choices.append(c)

    return {
        "chat_key": str(chat.get("chat_key") or ""),
        "buyer_id": int(chat.get("buyer_id", 0) or 0),
        "item": str(chat.get("item") or "Товар"),
        "item_uid": str(chat.get("item_uid") or ""),
        "message": last_message or "Клиент ждёт ответа.",
        "offer": current_offer,
        "price": market_price,
        "phase": int(chat.get("phase", 1) or 1),
        "round": int(chat.get("round", 1) or 1),
        "max_rounds": int(chat.get("max_rounds", 5) or 5),
        "trust": int(chat.get("trust", 50) or 50),
        "unread": bool(chat.get("unread")),
        "finished": bool(chat.get("finished")),
        "retry_available": bool(chat.get("retry_available")),
        "can_find_new_buyer": bool(chat.get("retry_available")),
        "last_activity_at": float(chat.get("last_activity_at", 0) or 0),
        "choices": unique_choices[:3],
    }


# ==================== AVITO LOAD PROTECTION ====================
_AVITO_STATE_CACHE = {}
_AVITO_STATE_CACHE_TTL = 3.5
_AVITO_STATE_LAST_REQUEST = {}
# Revision counter prevents a GET that started before a purchase from putting
# its stale supplier list back into cache after the purchase invalidates it.
_AVITO_STATE_CACHE_EPOCH = {}
_AVITO_STATE_MIN_INTERVAL = 1.0
_AVITO_REFRESH_MIN_INTERVAL = 0.8

def _avito_admit_request(pid:int, manual_refresh:bool=False):
    now=time_module.monotonic()
    last=float(_AVITO_STATE_LAST_REQUEST.get(int(pid),0.0) or 0.0)
    min_gap=_AVITO_REFRESH_MIN_INTERVAL if manual_refresh else _AVITO_STATE_MIN_INTERVAL
    if now-last < min_gap:
        return False, max(0.0, min_gap-(now-last))
    _AVITO_STATE_LAST_REQUEST[int(pid)]=now
    return True,0.0

@app.get("/avito/{tg_id}/unread")
async def avito_unread(tg_id: int):
    """Very cheap unread badge endpoint. Never rebuilds the Avito marketplace state."""
    pid=await get_player_id_by_tg(tg_id)
    if not pid:
        return JSONResponse({"success":False,"error":"Игрок не найден"},status_code=404)
    try:
        async with chats_lock:
            unread=sum(1 for v in active_chats.values() if v.get("user_id")==pid and not v.get("finished") and v.get("unread"))
        return JSONResponse({"success":True,"unread_count":int(unread)},headers={"Cache-Control":"no-store"})
    except Exception:
        return JSONResponse({"success":True,"unread_count":0},headers={"Cache-Control":"no-store"})

@app.get("/avito/{tg_id}")
async def avito_state(tg_id: int, request: Request):
    pid = await get_player_id_by_tg(tg_id)
    if not pid:
        return JSONResponse({"success": False, "error": "Игрок не найден"}, status_code=404)
    cache_key = int(pid)
    cache_epoch = int(_AVITO_STATE_CACHE_EPOCH.get(cache_key, 0) or 0)
    manual_refresh_requested = request.query_params.get("force_refresh") == "1"
    allowed, retry_after = _avito_admit_request(pid, manual_refresh_requested)
    if not allowed:
        cached = _AVITO_STATE_CACHE.get(int(pid))
        if cached and not manual_refresh_requested:
            return JSONResponse(cached.get("payload") or {}, headers={"Cache-Control":"no-store", "X-Avito-Cache":"rate-limit"})
        return JSONResponse({"success":False,"error":"Avito обновляется…","retry_after":round(retry_after,2)}, status_code=429, headers={"Retry-After":str(max(1,int(retry_after+0.99)))})
    if not manual_refresh_requested:
        cached = _AVITO_STATE_CACHE.get(int(pid))
        if cached and (time_module.monotonic()-float(cached.get("_cached_at",0) or 0)) < _AVITO_STATE_CACHE_TTL:
            return JSONResponse(cached.get("payload") or {}, headers={"Cache-Control":"no-store", "X-Avito-Cache":"hit"})
    try:
        # pid уже разрешён выше; не выполняем второй идентичный запрос к SQLite.
        player = await run_sync_db(ensure_inventory_uids_sync, pid, await run_sync_db(get_player_data, pid)) or {}
        normalized_career = _avito_career_load(player.get('avito_career') or {})
        raw_career_version = 0
        try:
            raw_career = player.get('avito_career') or {}
            if isinstance(raw_career,str): raw_career=json.loads(raw_career or '{}')
            raw_career_version=int((raw_career if isinstance(raw_career,dict) else {}).get('schema_version',0) or 0)
        except Exception: raw_career_version=0
        if raw_career_version < CAREER_SCHEMA_VERSION:
            # Persist the canonical dict through the existing serializer and keep the
            # in-memory snapshot canonical as well. This avoids double-encoding.
            await run_sync_db(update_player_data, pid, {"avito_career":normalized_career})
            player['avito_career']=normalized_career
        player = await run_sync_db(ensure_market_state_sync, pid, player)
        # Brand V3 is server-authoritative. Sales accrue as pending revenue and
        # are never auto-added to the main balance here.
        try:
            cstate=_avito_career_load(player.get('avito_career') or {})
            if isinstance(cstate,dict) and cstate.get('direction')=='brand':
                bstate=await run_sync_db(_brand_v3_state_sync,pid)
                if isinstance(bstate,dict) and bstate.get('name'):
                    cstate['brand']=bstate
                    player['avito_career']=cstate
        except Exception as _brand_v3_state_exc:
            print(f'[BRAND V3 STATE] {type(_brand_v3_state_exc).__name__}: {_brand_v3_state_exc}')
        # Refresh is intentionally a light path: do not run assistant procurement
        # cycles or inventory maintenance while the player is waiting for a new
        # supplier feed. Those workers still advance on normal Avito polls.
        assistant_tick = {"count": await run_sync_db(_get_avito_assistant_count_sync, pid), "events": []} if manual_refresh_requested else await run_sync_db(_tick_avito_assistants_sync, pid)
        # Assistant purchases/sales can mutate balance/inventory. Manual feed
        # refresh deliberately skips assistant cycles, so reuse the fresh player
        # snapshot already loaded above instead of querying SQLite a second time.
        if not manual_refresh_requested:
            player = await run_sync_db(ensure_inventory_uids_sync, pid, await run_sync_db(get_player_data, pid)) or player
        # The market state builder stores the current event on the player.
        # Older builds forgot to bind it locally here, so the next line that
        # checked ``if event`` raised NameError and /avito returned HTTP 500.
        event = player.get("current_event") or None
        # Manual supplier refresh is intentionally unlimited again. Anti-farming
        # is handled by the found-item algorithm itself: early searches are empty,
        # rare finds are probabilistic, and cars have a separate search cooldown.
        refresh_blocked = False
        refresh_cooldown = 300
        refresh_available = True
        refresh_remaining = 0
        async with supplier_lock:
            last_update = float(supplier_stock["last_update_by_player"].get(pid, 0) or 0)
            now = time_module.time()
            if manual_refresh_requested:
                await asyncio.to_thread(generate_supplier_items, pid, player, True)
            elif not supplier_stock["items_by_player"].get(pid) or now - last_update >= refresh_cooldown:
                await asyncio.to_thread(generate_supplier_items, pid, player, True)
            # IMPORTANT: do not call get_supplier_items() here. That helper acquires
            # supplier_lock itself; calling it while this block already owns the
            # lock deadlocks the request forever. This was a direct cause of
            # /avito appearing to hang when the page was opened.
            suppliers = list(supplier_stock["items_by_player"].get(pid, []))
        suppliers = sorted(suppliers, key=lambda x: (float(x.get("buy_price", x.get("price", 0)) or 0), float(x.get("market_price", x.get("value", 0)) or 0), float(x.get("margin_pct", 0) or 0)), reverse=True)[:30]
        async with chats_lock:
            chats = [_web_chat_payload(v) for v in active_chats.values() if v.get("user_id") == pid and not v.get("finished")]
        chats.sort(key=lambda x: float(x.get("last_activity_at", 0) or 0), reverse=True)
        unread_count = sum(1 for x in chats if x.get("unread"))
        # Published manual listings reserve their exact inventory UID. The item is
        # intentionally absent from warehouse while the ad is active. Only malformed
        # sessions are cleaned here; never recreate/duplicate a phantom item.
        listing_was_cleaned = False
        pub_uid = ""
        async with published_lock:
            pub = published_items.get(pid)
            published = None
            if pub:
                pub_uid = str(pub.get("item_uid") or pub.get("item", {}).get("uid") or "").strip()
                if not pub_uid or not isinstance(pub.get("item"), dict):
                    published_items.pop(pid, None)
                    listing_was_cleaned = True
                else:
                    published = {"item": pub.get("item"), "description": pub.get("description", ""), "quality": pub.get("quality", 0), "chat": None}
        if listing_was_cleaned:
            async with chats_lock:
                for key in [k for k,v in active_chats.items() if v.get("user_id") == pid and not v.get("finished") and str(v.get("item_uid") or "") == str(pub_uid)]:
                    active_chats.pop(key, None)
            await run_sync_db(_avito_persist_player_sync, pid, None, [])
        demand = player.get("market_demand") or {}
        top = sorted(demand.items(), key=lambda x: x[1], reverse=True)
        top3 = top[:3]
        low3 = sorted(demand.items(), key=lambda x: x[1])[:3]
        avg_demand = (sum(float(v) for v in demand.values()) / max(1, len(demand))) if demand else 1.0
        competition = "high" if avg_demand >= 1.15 else ("low" if avg_demand <= 0.85 else "mid")
        conditions = []
        if event:
            conditions.append({"id":"event","icon":"⚡","title":"Событие рынка","text":str(event.get("text") or "Рынок изменился")})
        conditions.append({"id":f"competition_{competition}","icon":"🔥" if competition=="high" else ("🟢" if competition=="low" else "⚖️"),"title":"Конкуренция высокая" if competition=="high" else ("Конкуренция ниже обычного" if competition=="low" else "Конкуренция стабильная"),"text":"Больше продавцов — цены сильнее конкурируют." if competition=="high" else ("Меньше продавцов — легче удерживать цену." if competition=="low" else "Рынок без резких перекосов.")})
        if top3:
            conditions.append({"id":"hot_categories","icon":"📈","title":"Горячий спрос","text":"".join([]) + ", ".join(f"{k} ×{float(v):.2f}" for k,v in top3)})
        if low3:
            conditions.append({"id":"cold_categories","icon":"📉","title":"Слабый спрос","text":", ".join(f"{k} ×{float(v):.2f}" for k,v in low3)})
        all_demand=[{"category":k,"multiplier":round(float(v),2)} for k,v in top]
        avito_level=get_avito_level_info(int(player.get("total_sales",0) or 0))
        reviews=await run_sync_db(get_avito_review_summary_sync,pid,50)
        discovery=await run_sync_db(get_avito_discovery_info,pid,player)
        assistant_meta=await run_sync_db(_get_avito_assistant_meta_sync,pid)
        assistant_active=sum(1 for x in chats if str(x.get("client_type") or "") == "assistant")
        payload = {
            "success": True,
            "balance": int(player.get("balance", 0) or 0),
            "inventory": player.get("inventory", []),
            "suppliers": suppliers,
            "supplier_refresh": {
                "cooldown": refresh_cooldown,
                "available": True,
                "blocked": False,
                "message": "Поставка готова к обновлению.",
            },
            "published": published,
            "chats": chats,
            "assistants": {
                "count": int(assistant_tick.get("count",0) or 0),
                "max": AVITO_ASSISTANT_MAX,
                "cost": AVITO_ASSISTANT_COST,
                "active": int(assistant_active),
                "next_run_at": float(assistant_meta.get("next_run_at",0) or 0),
                "updated_at": int(assistant_meta.get("updated_at",0) or 0),
                "events": assistant_tick.get("events",[])
            },
            "unread_count": unread_count,
            "shop_name": str(player.get("shop_name") or "Без названия"),
            "reputation": {"total_sales": int(player.get("total_sales", 0) or 0), "total_profit": int(player.get("total_profit", 0) or 0), "rating": get_avito_rating(int(player.get("total_sales", 0) or 0)), "level": get_rep_level(int(player.get("total_sales", 0) or 0))},
            "demand": {"hot": [{"category": k, "multiplier": round(float(v), 2)} for k, v in top3], "all": all_demand, "cold": [{"category": k, "multiplier": round(float(v), 2)} for k,v in low3]},
            "market_event": event,
            "market_conditions": conditions,

            "market_cycle_key": player.get("market_cycle_key"),
            "avito_level": avito_level,
            "career": {**_avito_career_load(player.get("avito_career") or {}), "eligible": int(player.get("total_sales",0) or 0) >= AVITO_CAREER_MAX_SALES},
            "reviews": reviews,
            "discovery": {
                "wealth": int(discovery.get("wealth",0) or 0),
                "passive_income": int(discovery.get("passive_income",0) or 0),
                "sales": int(discovery.get("sales",0) or 0),
                "chance": round(float(discovery.get("chance",0) or 0)*100,1),
                "max_chance": round(float(discovery.get("max_chance",0) or 0)*100,1),
                "next_sales": int(discovery.get("next_sales",0) or 0),
                "misses": int(discovery.get("misses",0) or 0),
                "max_car_tier": int(discovery.get("max_car_tier",-1) or -1),
                "tier_label": str(discovery.get("tier_label") or "Обычная поставка"),
                "eligible_count": len(discovery.get("eligible",[])),
                "unlocks": discovery.get("unlocks",[]),
            },
        }
        # Do not let an older in-flight GET overwrite cache invalidation made
        # by a successful purchase while this state payload was being assembled.
        if cache_epoch == int(_AVITO_STATE_CACHE_EPOCH.get(cache_key, 0) or 0):
            _AVITO_STATE_CACHE[cache_key]={"payload":payload,"_cached_at":time_module.monotonic()}
        return JSONResponse(payload, headers={"Cache-Control":"no-store", "X-Avito-Cache":"miss"})

    except Exception as exc:
        print(f"[AVITO STATE] safe fallback for tg={tg_id}: {type(exc).__name__}: {exc}")
        try:
            safe_player=await run_sync_db(get_player_data,pid) if pid else {}
        except Exception:
            safe_player={}
        safe_player=safe_player or {}
        try:
            safe_career=_avito_career_load(safe_player.get("avito_career") or {})
        except Exception:
            safe_career=_avito_career_default()
        return JSONResponse({
            "success": True,
            "balance": int(safe_player.get("balance",0) or 0),
            "inventory": safe_player.get("inventory",[]) or [],
            "suppliers": [],
            "supplier_refresh": {"cooldown":300,"available":True,"blocked":False,"message":"Поставка готова к обновлению."},
            "published": None,
            "chats": [],
            "assistants": {"count":0,"max":AVITO_ASSISTANT_MAX,"cost":AVITO_ASSISTANT_COST,"active":0,"next_run_at":0,"updated_at":0,"events":[]},
            "unread_count": 0,
            "shop_name": str(safe_player.get("shop_name") or "Без названия"),
            "reputation": {"total_sales":int(safe_player.get("total_sales",0) or 0),"total_profit":int(safe_player.get("total_profit",0) or 0),"rating":5.0,"level":1},
            "demand": {"hot":[],"all":[],"cold":[]},
            "market_event": None,
            "market_conditions": [],
            "market_cycle_key": safe_player.get("market_cycle_key"),
            "avito_level": {"level":1,"xp":0,"next_xp":100},
            "career": {**safe_career,"eligible":int(safe_player.get("total_sales",0) or 0) >= AVITO_CAREER_MAX_SALES},
            "reviews": {"items":[],"summary":{}},
            "discovery": {"wealth":0,"passive_income":0,"sales":int(safe_player.get("total_sales",0) or 0),"chance":0,"max_chance":0,"next_sales":10,"misses":0,"max_car_tier":-1,"tier_label":"Обычная поставка","eligible_count":0,"unlocks":[]}
        })
