@app.post("/avito/{tg_id}/buy")
async def avito_buy(tg_id: int, request: Request):
    # A successful purchase changes the supplier list, balance and inventory.
    # Validate the request and never let malformed JSON produce an opaque 500.
    try:
        data = await request.json()
    except Exception:
        return JSONResponse(
            {"success": False, "error": "Некорректный запрос покупки. Обнови Avito и попробуй ещё раз."},
            status_code=400,
            headers={"Cache-Control": "no-store"},
        )
    item_id = data.get("item_id") if isinstance(data, dict) else None
    if item_id is None or not str(item_id).strip():
        return JSONResponse(
            {"success": False, "error": "Не выбран товар для покупки. Обнови Avito и выбери лот ещё раз."},
            status_code=400,
            headers={"Cache-Control": "no-store"},
        )

    result = await api_call(tg_id, "buy_from_supplier", {"item_id": item_id})
    if not result.get("success"):
        return JSONResponse(
            {"success": False, "error": result.get("message", "Не удалось купить товар")},
            status_code=400,
            headers={"Cache-Control": "no-store"},
        )

    # The client immediately reloads /avito/{tg_id}; without invalidation the
    # short TTL cache/rate limiter could return the old list, making a bought
    # lot appear purchasable and preventing the next purchase/refresh.
    try:
        player_id = await get_player_id_by_tg(tg_id)
        if player_id:
            cache_key = int(player_id)
            _AVITO_STATE_CACHE_EPOCH[cache_key] = int(_AVITO_STATE_CACHE_EPOCH.get(cache_key, 0) or 0) + 1
            _AVITO_STATE_CACHE.pop(cache_key, None)
            _AVITO_STATE_LAST_REQUEST.pop(cache_key, None)
    except Exception as exc:
        # Buying is already committed; cache cleanup must never undo/report a
        # failed purchase. The cache naturally expires if cleanup is unavailable.
        print(f"[AVITO BUY] cache invalidation warning tg_id={tg_id}: {type(exc).__name__}: {exc}")

    return JSONResponse({"success": True, **result}, headers={"Cache-Control": "no-store"})

@app.post("/avito/{tg_id}/publish")
async def avito_publish(tg_id: int, request: Request):
    # Expected marketplace validation failures are returned as JSON, never as
    # a transport-level 400. This keeps the Mini App from turning a normal
    # business error into a generic "Load failed" screen.
    try:
        data = await request.json()
    except Exception:
        data = {}
    try:
        description = str(data.get("description") or "").strip()[:1000]
        result = await api_call(tg_id, "publish_item", {"item_uid": data.get("item_uid"), "description": description})
        if not result.get("success"):
            return JSONResponse({"success": False, "error": result.get("message", "Не удалось опубликовать товар")}, status_code=200)
        return JSONResponse({"success": True, **result}, status_code=200)
    except Exception as exc:
        print(f"[AVITO] publish endpoint error tg_id={tg_id}: {type(exc).__name__}: {exc}")
        return JSONResponse({"success": False, "error": "Не удалось опубликовать товар. Попробуй ещё раз."}, status_code=200)

