@app.get("/business/{tg_id}")
async def business_state(tg_id: int, request: Request):
    """Полное состояние бизнесов для RESSELL Mini App."""
    if not _verify_tycoon_webapp_request(request,tg_id):
        return JSONResponse({"success":False,"error":"Недействительная сессия Telegram"},status_code=401)
    player_id = await get_player_id_by_tg(tg_id)
    if not player_id:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)
    player = await run_sync_db(get_player_data, player_id)
    if not player:
        return JSONResponse({"success": False, "error": "Player not found"}, status_code=404)

    def _state():
        conn = get_db()
        now_state=int(time_module.time())
        candidates=conn.execute(
            "SELECT id,player_id,shop_id,purchase_price,purchased_at,last_payment,status FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id ASC", (player_id,)
        ).fetchall()
        for r in candidates:
            debt=get_business_maintenance_debt(get_business_purchase_price(r['shop_id'], r['purchase_price']),int(r['last_payment'] or 0),now_state)
            if debt >= get_business_maintenance_limit(get_business_purchase_price(r['shop_id'], r['purchase_price'])):
                conn.execute("UPDATE user_shops SET status='seized' WHERE id=? AND COALESCE(status,'active')='active'",(int(r['id']),))
        conn.commit()
        rows = conn.execute(
            "SELECT id, shop_id, purchase_price, purchased_at, last_payment, status FROM user_shops WHERE player_id=? AND COALESCE(status,'active')='active' ORDER BY id ASC", (player_id,)
        ).fetchall()
        conn.close()
        return [dict(r) for r in rows]

    rows = await run_sync_db(_state)
    catalog = []
    for shop in SHOP_LEVELS:
        if shop.get("id") == "none":
            continue
        catalog.append({
            "id": shop["id"], "name": shop["name"], "price": int(shop["price"]),
            "income_per_hour": int(shop["income_per_hour"]),
            "income_per_day": int(shop["income_per_hour"] * 24),
            "sell_price": int(shop["price"] * 0.9)
        })

    businesses=[]
    for row in rows:
        shop=next((x for x in SHOP_LEVELS if x["id"]==row["shop_id"]), None)
        if not shop: continue
        now=int(time_module.time())
        last_payment=int(row.get("last_payment") or 0)
        effective_purchase_price=get_business_purchase_price(row.get("shop_id"), row.get("purchase_price")) or int(shop["price"])
        maintenance_debt=get_business_maintenance_debt(effective_purchase_price,last_payment,now)
        maintenance_limit=get_business_maintenance_limit(effective_purchase_price)
        businesses.append({
            "instance_id": int(row["id"]), "id": shop["id"], "name": shop["name"],
            "price": int(shop["price"]), "purchase_price": int(effective_purchase_price),
            "income_per_hour": int(shop["income_per_hour"]), "income_per_day": int(shop["income_per_hour"]*24),
            "sell_price": int(shop["price"]*0.9), "status": row.get("status") or "active",
            "last_payment": last_payment, "maintenance_cost": get_maintenance_cost_shop(int(effective_purchase_price)),
            "maintenance_debt": maintenance_debt, "maintenance_limit": maintenance_limit,
            "maintenance_days_left": max(0, int((BUSINESS_MAINTENANCE_MAX_DEBT_PERIOD_SEC - max(0,now-last_payment))/86400)) if last_payment else 0
        })

    pending, hourly, breakdown = await get_pending_income(player_id)
    avito_sales=int(player.get("total_sales",0) or 0)
    business_capacity=get_business_capacity(avito_sales)
    # Keep a named pending breakdown so the Mini App can show the taxopark as
    # a first-class business without inventing a second collection mechanism.
    pending_breakdown = {k:int(v) for k,v in breakdown.items()}
    debt = await calculate_total_debt(player_id)
    taxi_hourly = int((breakdown.get("taxopark",0) if breakdown else 0))
    return JSONResponse({
        "success": True,
        "balance": int(player.get("balance",0) or 0),
        "businesses": businesses,
        "catalog": catalog,
        "pending_collect": int(pending),
        "total_per_hour": int(hourly),
        "total_per_day": int(hourly*24),
        "hourly_breakdown": breakdown,
        "pending_breakdown": pending_breakdown,
        "taxi_business": {"hourly_income":taxi_hourly,"pending_collect":int(pending_breakdown.get("taxopark",0) if pending_breakdown else 0)},
        "maintenance_debt": int(debt),
        "legacy_shop_level": player.get("shop_level","none"),
        "avito_sales": avito_sales,
        "avito_level": get_rep_level(avito_sales),
        "business_capacity": int(business_capacity),
        "business_capacity_left": max(0,int(business_capacity)-len(businesses))
    })

